INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182000,'31202','Basílica de San Miguel','religioso','religioso_osm','San Migel eliza Argako Erriberako Azkoien udalerrian kokatutako XVII. mendeko kristiau basilika bat da. Barroko estiloa ditu.',42.3389718,-1.7994446,'https://eu.wikipedia.org/wiki/San_Migel_eliza_(Azkoien)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182001,'38037','Santuario de Nuestra Señora de Las Nieves','religioso','religioso_osm','El Real Santuario Insular de Nuestra Señora de las Nieves, se encuentra en el término municipal de Santa Cruz de La Palma (Canarias, España). Es un edificio religioso en el que se encuentra la venerada imagen de Nuestra Señora de las Nieves, patrona de la isla de La Palma junto a San Miguel Arcángel.',28.6943506,-17.782164,'https://es.wikipedia.org/wiki/Real_Santuario_Insular_de_Nuestra_Señora_de_las_Nieves');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182002,'28065','Convento de Carmelitas Descalzas','religioso','religioso_osm','En 1925 se comenzó a construir este convento en el Cerro de los Ángeles de Getafe (Madrid), a iniciativa de la Madre Maravillas de Jesús​ (que había creado la primera comunidad de monjas Carmelitas Descalzas en Getafe, a la espera de poder instalarse en el mismo). El 26 de octubre de 1926 se ocupó el edificio y…',40.309269,-3.6842164,'https://es.wikipedia.org/wiki/Convento_del_Sagrado_Corazón_y_Nuestra_Señora_de_los_Ángeles_(Cerro_de_los_Ángeles)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182003,'90366','Monestir de Sant Esperit','religioso','religioso_osm','El monestir de Sant Esperit (Sancti Spiritu del Monte) és un monestir franciscà del segle xvii enclavat en la serra de la Calderona a la vall de Toliu, al municipi valencià de Gilet (Camp de Morvedre).',39.668137,-0.3491535,'https://www.santoespiritu.org/','https://ca.wikipedia.org/wiki/Monestir_de_Sant_Esperit');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182004,'46024','Ermita de la Mare de Déu dels Afligits','religioso','religioso_osm','La ermita de la Virgen de los Afligidos es un templo católico situado en la cima de la Muntanyeta de l''Ermita, en el municipio de Alfara de la Baronía, provincia de Valencia, Comunidad Valenciana, España.',39.7645853,-0.3576692,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_los_Afligidos_(Alfara_de_la_Baronía)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182005,'43092','Mare de Déu de la Roca','religioso','religioso_osm','L''Ermita de la Mare de Déu de la Roca és una ermita situada a Mont-roig del Camp (Baix Camp). Es troba a 294 metes d''altitud, damunt una roca molt erosionada.',41.0947328,0.9379915,'https://ca.wikipedia.org/wiki/Ermita_de_la_Mare_de_Déu_de_la_Roca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182006,'90884','Capella de la Mare de Déu de l''Erola','religioso','religioso_osm','Mare de Déu de l''Erola és una obra del municipi de Tordera (Maresme) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6695376,2.634031,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_l''Erola');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182007,'34171','Santuario de la Virgen del Brezo','religioso','religioso_osm','El santuario de la Virgen del Brezo es un santuario católico mariano situado en la localidad de Villafría de la Peña del municipio de Santibáñez de la Peña, en Palencia (España), donde se venera a la Virgen del Brezo, patrona de la Montaña Palentina y que según la leyenda se habría aparecido en 1478.​​ Está…',42.8488808,-4.7127009,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_del_Brezo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182008,'12111','Església de la Mare de Déu del Pilar','religioso','religioso_osm','L''església de la Mare de Déu del Pilar de Tírig, a la comarca de l''Alt Maestrat, és un lloc de culte catalogat com a Bé de Rellevància Local, amb la categoria de Monument per declaració genèrica, amb codiː 12.02.111.001, segons la Disposició Addicional Cinquena de la Llei 5/2007, de 9 de febrer, de la Generalitat,…',40.4235056,0.0774859,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_del_Pilar_(Tírig)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182009,'12130','Iglesia Parroquial de la Natividad de Nuestra Señora','religioso','religioso_osm','La iglesia de la Natividad de la Virgen María de Villahermosa del Río, está situada en el centro de la población, en la plaza de la Iglesia. Es la parroquia de la población, templo católico que pertenece al obispado de Segorbe-Castelló.',40.2024896,-0.4181274,'https://es.wikipedia.org/wiki/Iglesia_de_la_Natividad_de_Nuestra_Señora_(Villahermosa_del_Río)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182010,'08089','Ermita de la Mare de Déu de Bruguers','religioso','religioso_osm','La Mare de Déu de Bruguers o Ermita de Bruguers és un edifici originalment romànic del segle xiii al poble de Bruguers a mig camí dels nuclis de Begues i Gavà (Baix Llobregat) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. S''hi venera la Mare de Déu de Bruguers, una marededeu trobada.',41.3145719,1.9612561,'https://ca.wikipedia.org/wiki/Ermita_de_Bruguers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182011,'12061','Església Parroquial de la Mare de Déu de l''Assumpció','religioso','religioso_osm','L''Església de l''Assumpció de Maria, al municipi del Forcall de la comarca valenciana dels Ports, és un temple parroquial catòlic. És un edifici construït sobre l''antiga església gòtica (del segle xiii) que fou destruïda durant les guerres carlistes del segle xix.',40.6462812,-0.1980487,'https://ca.wikipedia.org/wiki/Església_de_l''Assumpció_del_Forcall');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182012,'90094','Basílica Santa Lucía del Trampal','religioso','religioso_osm','La iglesia de Santa Lucía del Trampal es un templo de datación discutida (entre el siglo VII y el siglo IX)​​ situado en el municipio español de Alcuéscar, en la provincia de Cáceres. Se trata de un templo singular con características arquitectónicas visigodas y posible influencia posterior mozárabe,​ que ordena su…',39.1527731,-6.2226393,'https://es.wikipedia.org/wiki/Basílica_de_Santa_Lucía_del_Trampal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182013,'46110','Ermita Virgen de la Salud','religioso','religioso_osm','L''Ermita de la Salut, és un edifici religiós situat al municipi de Xirivella.',39.4657772,-0.4264576,'https://ca.wikipedia.org/wiki/Ermita_de_la_Salut_de_Xirivella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182014,'11018','Ermita de la Mare de Déu de la Misericòrdia de Vinaròs','religioso','religioso_osm','L''Ermita de la Mare de Déu de la Misericòrdia de Vinaròs, també coneguda com a ermita de la Mare de Déu de la Misericòrdia i de Sant Sebastià, ermita de Sant Sebastià o ermita dels Sants Patrons, està dedicada a la Verge de la Misericòrdia i a Sant Sebastià, patrons de la ciutat, i a Sant Antoni, antiga advocació…',40.5068862,0.431478,'https://ca.wikipedia.org/wiki/Ermita_de_la_Mare_de_Déu_de_la_Misericòrdia_de_Vinaròs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182015,'90030','Iglesia de Nuestra Señora de Muslera','religioso','religioso_osm','La iglesia de Nuestra Señora de Muslera, situada en la localidad de Guarnizo, perteneciente al municipio cántabro de El Astillero, es una iglesia cuyo origen se remonta al siglo IX y está dedicada a la Virgen de Muslera, patrona de la localidad desde 1947. Junto al ábside de la iglesia se encuentra la Residencia de…',43.3981117,-3.8294198,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Muslera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182016,'33049','Santuario de la Virgen de la Cueva','religioso','religioso_osm','El santuario de la Virgen de la Cueva es un lugar de culto católico que se encuentra en la comunidad del Principado de Asturias (España), en la parroquia de Ques, a unos dos kilómetros de la localidad de Infiesto, concejo de Piloña, en la zona central de Asturias.',43.3493621,-5.3746928,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_de_la_Cueva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182017,'25074','Santuari de la Mare de Déu de la Bovera','religioso','religioso_osm','Santa Maria de la Bovera és un santuari marià i antic monestir femení de l''orde del Cister situat en un tossal a 590 metres d''altitud al terme de Guimerà (Urgell). És una obra inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.5702053,1.1585745,'https://www.guimera.info/esglesia/santuari.htm','https://ca.wikipedia.org/wiki/Santa_Maria_de_la_Bovera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182018,'43139','Mare de Déu de la Llet','religioso','religioso_osm','L''Església de Sant Gallard és un temple dedicat a Sant Josep i a la Mare de Déu de la Llet depenent de la parròquia de Santa Coloma de Queralt, però ubicada al terme de les Piles. És una església d''una sola nau, de planta rectangular en volta de pedra i dos altars laterals, un a banda i banda.',41.513008,1.3916126,'https://ca.wikipedia.org/wiki/Església_de_Sant_Gallard');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182019,'40132','Santuario de Nuestra Señora de Hornuez','religioso','religioso_osm','El santuario de Nuestra Señora de Hornuez está ubicado en el municipio de Moral de Hornuez, en la provincia de Segovia, comunidad autónoma de Castilla y León, España, a 2 km de su casco urbano.',41.482638,-3.6229536,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_Hornuez');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182020,'17139','Mare de Déu de les Olletes','religioso','religioso_osm','El santuari de la Mare de Déu de les Olletes està situat a la Vall d''en Bas dins un barranc i es troba a 1.036 metres sobre el nivell del mar, al vessant nord del Puigsacalm just sota Santa Magdalena del Mont. La cova té cinc metres d''alçada per vuit de fondària i quatre d''amplada.',42.1344506,2.3952656,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Olletes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182021,'43176','Mare de Déu dels Torrents','religioso','religioso_osm','La Mare de Déu dels Torrents és un petita església d''estructura molt senzilla al terme municipal de Vimbodí i Poblet (Conca de Barberà) protegit com a bé cultural d''interès local. El reverend Magí Alandó, farmacèutic del cenobi de Poblet, va erigir aquest temple amb el permís de l''abat Josep Escuder el 1714, com…',41.3949831,1.0616317,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Torrents');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182022,'14038','Santuario de Nuestra Señora de Araceli','religioso','religioso_osm','El Real Santuario Diocesano de Nuestra Señora de Araceli está ubicado muy cerca de Lucena, provincia de Córdoba. La Ermita está en la cumbre de la Sierra de Aras.',37.3763273,-4.4667583,'https://virgendearaceli.net/','https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_Araceli');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182023,'39050','Ermita de Nuestra Señora de la Asunción','religioso','religioso_osm','Para ver otras iglesias bajo la misma advocación, véase Ermita de Nuestra Señora de la Asunción. La ermita de Nuestra Señora de la Asunción en Caloca, municipio de Pesaguero (Cantabria, España), fue declarada bien de interés cultural el 24 de junio de 1996.',43.0434134,-4.5625706,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_la_Asunción_(Caloca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182024,'22223','Monasterio de Santa María de Alaón','religioso','religioso_osm','Santa Maria d''Alaó és un monestir romànic llombard del final del segle xi, situat al municipi de Sopeira, dins de la Franja de Ponent, a la comarca de la Ribagorça a la província d''Osca (Aragó). La seva planta és basilical de tres naus i absis cilíndrics, amb arcuacions cegues, amb un campanar en torre quadrada de…',42.3181562,0.7495984,'https://ca.wikipedia.org/wiki/Santa_Maria_d''Alaó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182025,'05006','Monasterio de Courias','religioso','religioso_osm','El monasterio de San Juan Bautista de Corias, también conocido como el Escorial Asturiano, es un complejo monumental que se encuentra en la localidad asturiana de Corias, en el concejo de Cangas del Narcea (España). Está situado en la margen derecha del río Narcea.',43.1946596,-6.5435213,'https://es.wikipedia.org/wiki/Monasterio_de_San_Juan_Bautista_(Corias)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182026,'12129','Santuari de la Mare de Déu del Llosar','religioso','religioso_osm','L''ermita de la Mare de Déu del Llosar de Vilafranca, està situada a 1,5 km de la localitat, en la carretera CV-15, en direcció a l''Anglesola. Aquest conjunt està qualificat com a Bé de Rellevància Local amb la categoria de Monument d''Interès Local.',40.4444993,-0.2727839,'https://ca.wikipedia.org/wiki/Ermita_de_la_Mare_de_Déu_del_Llosar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182027,'12120','Ermita de la Mare de Déu de la Font','religioso','religioso_osm','La Virgen María de la Fuente es una ermita en la calle de la Fuente de Torre Endoménech y que cuenta con una espadaña en el tejado. Está formada por un arco con molduras en los laterales y para rematarla una cruz.',40.264308,0.0700608,'https://es.wikipedia.org/wiki/Ermita_Virgen_de_la_Fuente_(Torre_Endoménech)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182028,'29035','Convento de San Francisco','religioso','religioso_osm','El convento de San Francisco es un convento del municipio de Cañete la Real, en la provincia de Málaga, España. Su nombre popular es La Cartuja.',36.9520566,-5.0242511,'https://es.wikipedia.org/wiki/Convento_de_San_Francisco_(Cañete_la_Real)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182029,'28079','Capilla de Nuestra Señora de la Soledad','religioso','religioso_osm','El humilladero de Nuestra Señora de la Soledad es una pequeña capilla situada en el número 44 de la calle de Fuencarral de Madrid, esquina a la antigua calle de Santa María del Arco.​ Fue construida en 1712 debido a que en las inmediaciones existía un cuadro de la Virgen de Nuestra Señora de la Soledad, al que los…',40.423084,-3.7006213,'https://es.wikipedia.org/wiki/Humilladero_de_Nuestra_Señora_de_la_Soledad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182030,'10082','Convento de las Monjas Jerónimas','religioso','religioso_osm','El monasterio de Nuestra Señora de la Salud, más conocido localmente como el "convento de las Jerónimas", es un monasterio de clausura monástica de monjas de la Orden de San Jerónimo ubicado en la villa española de Garrovillas de Alconétar, en la provincia de Cáceres.​',39.7141877,-6.5508337,'https://www.garrovillasdealconetar.es/patrimonio/-/asset_publisher/ZdCfP2V3ozyl/content/id/1861900','https://es.wikipedia.org/wiki/Monasterio_de_Nuestra_Señora_de_la_Salud_(Garrovillas_de_Alconétar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182031,'31232','Parroquia de Inmaculada Concepción y Convento de las Capuchinas','religioso','religioso_osm','La iglesia y convento de las Capuchinas de Tudela (Navarra) es una iglesia barroca y convento neoclásico de mediados del siglo XVIII,​ perteneciente a la Orden de las Capuchinas, situado en el Paseo que lleva su mismo nombre.​ La Diócesis de Tudela tiene asignado al templo la Parroquia de la Inmaculada Concepción.',42.0626407,-1.611907,'https://es.wikipedia.org/wiki/Iglesia_y_convento_de_las_Capuchinas_(Tudela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182032,'08003','Mare de Déu del Coll','religioso','religioso_osm','La Mare de Déu del Coll, o de Font-rúbia, és una església al barri del Coll —al qual dona nom—, al districte de Gràcia de Barcelona. Es tracta d''una església romànica del segle xi, de la que es conserva el cos central i el campanar, essent els altres elements actuals de l''església del segle xx.',41.4200523,2.151552,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Coll_(Barcelona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182033,'25905','Mare de Deu de la Providencia','religioso','religioso_osm','La Mare de Déu de la Providència és una ermita al municipi de Ribera d''Ondara (Segarra) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Tant la construcció com la construcció d''aquesta ermita ve de la mà dels pares Claretians de Cervera que en un lloc pròxim a la mateixa tenien la seva casa de…',41.6521725,1.3394472,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Providència');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182034,'25234','Mare de Déu del Roser','religioso','religioso_osm','La Mare de Déu del Roser de Puigmaçana és l''església del petit nucli de Puigmaçana, del terme municipal de Castell de Mur, a l''antic terme de Mur. Està situada a l''extrem de ponent del petit poble de Puigmaçana, ran del camí que hi accedeix.',42.1420361,0.8701663,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_de_Puigmaçana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182035,'25016','Mare de Déu del Merli','religioso','religioso_osm','La Mare de Déu del Merli és una església del municipi d''Alguaire (Segrià) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7387077,0.5810997,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Merli');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182036,'43019','Mare de Déu del Carme','religioso','religioso_osm','La Mare de Déu del Carme és una ermita al sud del nucli d''Ascó, entre la carretera i la xarxa ferroviària.',41.177719,0.5692352,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Carme_(Ascó)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182037,'22095','Ermita de Nuestra Señora de Gracia','religioso','religioso_osm','La Mare de Déu de Gràcia és una ermita romànica llombarda de començament del segle xii, situada al municipi de Castilló de Sos, dins de la Franja de Ponent a la comarca de la Ribagorça a l''indret conegut com el Ru. La seva planta és d''una nau i absis cilíndric amb arcuacions cegues, amb un campanar en torre sobre…',42.504407,0.4717898,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Gràcia_(el_Ru)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182038,'27031','Mosteiro de San Vicente do Pino','religioso','religioso_osm','O mosteiro de San Vicente do Pino é un conxunto monumental situado en Monforte de Lemos, flanqueado polos restos do castelo, do que se conserva parte da muralla e mailos cubos defensivos, a torre da homenaxe, dende a cal se pode contemplar todo o Val de Lemos, e os restos do palacio dos condes de Lemos, edificio…',42.5239015,-7.5104999,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Vicente_do_Pino');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182039,'46087','Ermita Virgen de la Huerta','religioso','religioso_osm','La ermita de Nuestra Señora de la Huerta constituye el edificio más antiguo de la villa de Ademuz, en la capital de la comarca valenciana del Rincón de Ademuz y una de las joyas del románico valenciano. Situada en un privilegiado emplazamiento, entre el río Turia y el antiguo Camino Real, fue erigida en el siglo…',40.0650831,-1.2841469,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_la_Huerta_(Ademuz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182040,'21044','Capilla Cristo del Mar','religioso','religioso_osm','La capilla del Cristo del Mar, también conocida como ermita del Cristo del Mar, es un templo católico que se encuentra en el municipio de Lepe, provincia de Huelva (España), y pertenece a la parroquia de Santo Domingo de Guzmán.',37.2581849,-7.2054247,'https://es.wikipedia.org/wiki/Capilla_del_Cristo_del_Mar_(Lepe)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182041,'42152','Ermita de la Virgen de la Calzada','religioso','religioso_osm','La ermita de la Virgen de la Calzada, en Brías, municipio de Berlanga de Duero (Provincia de Soria, España) es uno de los ejemplares más antiguos del románico de la provincia de Soria, de principios del siglo XII, con claras influencias orientales.',41.3973212,-2.9549208,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_la_Calzada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182042,'46131','Convento de Santa Clara','religioso','religioso_osm','El Convent de Santa Clara és un convent de clausura situat a la ciutat valenciana de Gandia (La Safor). Va ser fundat al segle xv i actualment està habitat per monges de l''Orde de les Clarisses Coletines.',38.9674669,-0.1780133,'https://ca.wikipedia.org/wiki/Convent_de_Santa_Clara_de_Gandia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182043,'43172','Mare de Déu de Montgoi','religioso','religioso_osm','Mare de Déu del Montgoi és un santuari del municipi de Vilaverd (Conca de Barberà) protegit com a bé cultural d''interès local. El primer esment d''una capella en aquest lloc data del 1214.',41.3387202,1.1750163,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Montgoi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182044,'43137','Ermita De La Mare De Déu Dels Arquets','religioso','religioso_osm','Mare de Déu dels Arquets és un edifici religiósdel municipi de Sant Jaume dels Domenys (Baix Penedès) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.2969802,1.5679852,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Arquets');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182045,'37297','Ermita de Nuestra Señora de Valparaíso','religioso','religioso_osm','La ermita de Nuestra Señora de Valparaíso es un templo del municipio de Santibáñez de Béjar, dónde se encuentra la patrona de la villa, la Virgen de Valparaíso. Es una ermita originalmente construida sobre un templo romano del que se conservan las bases.',40.4901699,-5.6050796,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Valparaíso_(Santibáñez_de_Béjar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182046,'43111','Mare de Déu de Montornès','religioso','religioso_osm','La Mare de Déu de Montornès és un monument del municipi de la Pobla de Montornès protegit com a bé cultural d''interès local. L''església parroquial de la Pobla de Montornès, dedicada a Santa Maria, és a un quart d''hora, aproximadament de la localitat, dalt d''un turó.',41.170706,1.4037532,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montornès');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182047,'08101','Parròquia Mare de Déu dels Dolors','religioso','religioso_osm','L''església dels Dolors és un temple parroquial situat al carrer de Begur, 8 al barri de Sants de Barcelona.',41.3750507,2.1288414,'https://ca.wikipedia.org/wiki/Església_dels_Dolors');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182048,'16009','Real Capilla de Nuestra Señora del Populo','religioso','religioso_osm','La Real Capilla de Nuestra Señora del Pópulo está situada en la ciudad de Cádiz (España)​',36.5295919,-6.2935646,'https://es.wikipedia.org/wiki/Real_Capilla_de_Nuestra_Señora_del_Pópulo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182049,'21021','Convento de Nuestra Señora de la Merced','religioso','religioso_osm','El antiguo convento de Mercedarios Descalzos de la Santísima Trinidad de Cartaya (provincia de Huelva, España) es un ejemplo de la arquitectura conventual de la segunda mitad del siglo XVIII, ya academicista, de transición del barroco al neoclasicismo. En el plano urbanístico, el convento se sitúa en el centro de…',37.2834541,-7.1530092,'https://es.wikipedia.org/wiki/Convento_de_la_Santísima_Trinidad_(Cartaya)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182050,'90862','Santuari de la Mare de Déu de la Vallivana','religioso','religioso_osm','Santuari de la Verge de Vallivana (Llogaret i antic santuari de la província de Castelló, municipi de Morella. L''eremitori de Vallivana és un dels més grandiosos i històrics del País Valencià.',40.5399409,0.0535409,'https://ca.wikipedia.org/wiki/Santuari_de_la_Verge_de_Vallivana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182051,'25171','Mare de Déu de la Serreta','religioso','religioso_osm','La Mare de Déu de la Serreta o de la Serra, és una capella romànica del poble de Claverol (Conca de Dalt), al Pallars Jussà. Fins al 1969 formava part del terme municipal de Claverol.',42.2381611,0.9935066,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Serreta');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182052,'25017','Mare de Déu de Montserrat de Casa Coix','religioso','religioso_osm','La Mare de Déu de Montserrat de Casa Coix és una capella particular, romànica, de Casa Coix, a la vila d''Alins, en el terme municipal del mateix nom, a la comarca del Pallars Sobirà. Està situada en el centre de la població, al costat de Casa Coix.',42.5481487,1.3168522,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montserrat_de_Casa_Coix');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182053,'25208','Mare de Déu del Roser de Casa Franquet','religioso','religioso_osm','La Mare de Déu del Roser de Casa Franquet és la capella particular de Casa Franquet, del poble de Vilamur, pertanyent al terme municipal de Soriguera, a la comarca del Pallars Sobirà. Formava part del seu terme primigeni.',42.3798876,1.1618405,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_de_Casa_Franquet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182054,'25141','Mare de Déu del Coll de la Guàrdia Lada','religioso','religioso_osm','Mare de Déu del Coll és una església del poble de la Guàrdia Lada, al municipi de Montoliu de Segarra (Segarra) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.5911738,1.2913013,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Coll_de_la_Guàrdia_Lada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182055,'50006','Iglesia de la Asunción de Nuestra Señora','religioso','religioso_osm','Igokundeko Ama Birjinaren eliza Arabako Artziniega herriko eliza nagusia da. XVII. mendean eraikia Barroko estiloan eraiki zen.',43.1207626,-3.1274628,'https://eu.wikipedia.org/wiki/Igokundeko_Ama_Birjinaren_eliza_(Artziniega)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182056,'22006','Convento de las Hermanas de la Cruz de Ayamonte','religioso','religioso_osm','El convento de las Hermanas de la Cruz es un convento de monjas, situado en la localidad de Ayamonte, Huelva.',37.2152381,-7.408362,'https://es.wikipedia.org/wiki/Convento_de_las_Hermanas_de_la_Cruz_(Ayamonte)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182057,'36011','Santuario das Aparicións','religioso','religioso_osm','O Santuario das Aparicións ou Santuario do Inmaculado Corazón de María é un santuario mariano en Pontevedra. Aparecéronselle aquí, segundo relata Sor Lucía, o Neno Xesús e a Virxe María en 1925 e 1926 e, co corazón rodeado de espiñas, reveláronlle a devoción dos cinco primeiros sábados.',42.4338899,-8.6464355,'https://gl.wikipedia.org/wiki/Santuario_das_Aparicións');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182058,'25064','Mare de Déu del Remei de Castellar','religioso','religioso_osm','Mare de Déu del Remei de Castellar és una capella de la masia de la Llena, a Castellar de la Ribera (Solsonès), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9932332,1.3601206,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Remei_de_Castellar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182059,'18140','Iglesia Parroquial de Nuestra Señora de la Encarnación','religioso','religioso_osm','La iglesia mayor de la Encarnación,​ Iglesia Mayor o simplemente iglesia de la Encarnación es una iglesia parroquial católica situada en la ciudad española de Motril, en Granada, comunidad autónoma de Andalucía. La parroquia depende del Arzobispado de Granada y en ella se guarda una importante colección de figuras…',36.7457108,-3.5209317,'https://cultura.motril.es/iglesia-mayor-de-la-encarnacion/','https://es.wikipedia.org/wiki/Iglesia_Mayor_de_la_Encarnación');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182060,'18140','Parroquia de Nuestra Señora de la Cabeza','religioso','religioso_osm','El Santuario o Parroquia de Nuestra Señora de la Cabeza es un templo religioso católico situado en la ciudad española de Motril, provincia de Granada, con la advocación mariana de la Virgen de la Cabeza, patrona de Motril.​',36.7423119,-3.5184235,'https://cultura.motril.es/parroquia-santuario-de-nuestra-senora-de-la-cabeza/','https://es.wikipedia.org/wiki/Parroquia_Nuestra_Señora_de_la_Cabeza_(Motril)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182061,'32052','Mosteiro de San Vicente de Pombeiro','religioso','religioso_osm','O mosteiro de San Vicenzo de Pombeiro ou San Vicente Polumbario é unha edificación relixiosa da que queda a igrexa de estilo románico situada na parroquia de Pombeiro do concello de Pantón na Ribeira Sacra.',42.4481401,-7.7028697,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Vicenzo_de_Pombeiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182062,'14021','Colegiata de San Hipólito','religioso','religioso_osm','La Real Colegiata de San Hipólito es una iglesia católica de la ciudad de Córdoba (España), ubicada entre la avenida del Gran Capitán y las calles Menéndez Pelayo, Alonso Aguilar y la plaza de San Ignacio de Loyola. Fue fundada en 1343 por iniciativa de Alfonso XI de Castilla.',37.8858631,-4.783171,'https://es.wikipedia.org/wiki/Real_Colegiata_de_San_Hipólito_(Córdoba)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182063,'33044','Basílica de San Juan El Real','religioso','religioso_osm','San Juan el Real es un templo católico situado en la ciudad de Oviedo (Principado de Asturias, España). Se trata de una iglesia parroquial perteneciente a la archidiócesis de Oviedo que tiene el título de basílica menor.',43.365041,-5.850869,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_el_Real_(Oviedo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182064,'03003','Basílica de Santa María','religioso','religioso_osm','La basílica de Santa María es un templo católico ubicado en la plaza de Santa María de Alicante (España).',38.346202,-0.4792172,'https://es.wikipedia.org/wiki/Basílica_de_Santa_María_(Alicante)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182065,'03003','iglesia Nuestra Señora de Gracia','religioso','religioso_osm','L''església de la Mare de Déu de Gràcia és una església situada a la plaça de la Montanyeta de la ciutat d''Alacant (l''Alacantí, País Valencià). Es va construir entre 1945 i 1951 segons el projecte de l''arquitecte A. Serrano Peral.',38.3447757,-0.4876137,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_de_Gràcia_d''Alacant');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182066,'28508','Parroquia Virgen de Guadalupe','religioso','religioso_osm','La iglesia de Nuestra Señora de Guadalupe (también conocida con el nombre de iglesia de los Mexicanos)​ es un templo católico de España situado en la ciudad de Madrid. Fue obra de los arquitectos Enrique de la Mora y Palomar y José Ramón Azpiazu, y de José Antonio Torroja y Félix Candela (estos dos últimos como…',40.4521104,-3.6750831,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Guadalupe_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182067,'12040','Basílica de la Mare de Déu del Lledó','religioso','religioso_osm','El santuari-basílica (des de 1993) de la Mare de Déu del Lledó està en plena horta de la Plana, a un quilòmetre de Castelló, en el conegut com a "camí Lledó". Es tracta d''un temple catòlic catalogat com a Bé de Rellevància Local segons la Disposició addicional cinquena de la Llei 5/2007, de 9 de febrer, de la…',39.9971159,-0.0200523,'https://ca.wikipedia.org/wiki/Basílica_de_la_Mare_de_Déu_del_Lledó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182068,'26089','Concatedral de Santa María de la Redonda','religioso','religioso_osm','La concatedral de Santa María de la Redonda es una iglesia situada en el centro del casco histórico de Logroño (La Rioja, España). Junto a las catedrales de Calahorra y de Santo Domingo de La Calzada, conforman un caso singular en el orbe católico, al ser una diócesis con tres sedes catedralicias.',42.4665972,-2.4453362,'https://www.laredonda.org/','https://es.wikipedia.org/wiki/Concatedral_de_Logroño');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182069,'39075','Iglesia de Nuestra Señora de Consolación','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de Consolación es un templo de culto católico situado en el municipio de Santander, su estilo es barroco y fue construida en el siglo XVIII.',43.4602151,-3.8117851,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Consolación_(Santander)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182070,'48078','Andra Maria basilika / Basílica de Santa María','religioso','religioso_osm','La basílica de Santa María es un templo parroquial católico de estilo gótico-renacentista situado en el municipio de Portugalete, Vizcaya, País Vasco, España.',43.3198165,-3.0167447,'https://es.wikipedia.org/wiki/Basílica_de_Santa_María_(Portugalete)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182071,'30030','Catedral de Murcia','religioso','religioso_osm','La Santa Iglesia Catedral de Santa María,​ conocida como catedral de Murcia, es el templo principal y sede de la diócesis de Cartagena. Se encuentra en pleno casco antiguo de la ciudad de Murcia, en la plaza del Cardenal Belluga.',37.9840741,-1.1286307,'https://diocesisdecartagena.org/es/inicio/diocesis/catedral.aspx','https://es.wikipedia.org/wiki/Catedral_de_Murcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182072,'28509','Santuario de Nuestra Señora de Valverde','religioso','religioso_osm','El santuario de Nuestra Señora de Valverde es un conjunto monumental situado en el distrito de Fuencarral-El Pardo de la villa de Madrid. Se encuentra en el km 12 de la carretera de Colmenar Viejo (antigua carretera de Francia).',40.5158745,-3.6862782,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_Valverde');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182073,'28079','Real Basílica de San Francisco el Grande','religioso','religioso_osm','La Real Basílica de San Francisco el Grande, oficialmente Basílica de Nuestra Señora de los Ángeles, es una iglesia católica en Madrid, en el barrio de Palacio, dentro del casco histórico de la capital de España. Preside la cara occidental de la plaza de San Francisco, configurada por la intersección de la calle…',40.4104314,-3.7145624,'https://es.wikipedia.org/wiki/Real_basílica_de_San_Francisco_el_Grande');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182074,'33044','Catedral de San Salvador de Oviedo','religioso','religioso_osm','La Santa Iglesia Basílica Catedral Metropolitana de San Salvador de Oviedo es una catedral de estilo gótico que se encuentra en la ciudad de Oviedo (Principado de Asturias, España). Es conocida también como Sancta Ovetensis, refiriéndose a la calidad y cantidad de las reliquias que contiene.​ Comenzó a edificarse a…',43.3625242,-5.8432972,'https://catedraldeoviedo.com/','https://es.wikipedia.org/wiki/Catedral_de_Oviedo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182075,'15055','Mosteiro de San Martiño de Xuvia','religioso','religioso_osm','O popularmente coñecido Mosteiro do Couto, tamén chamado Mosteiro de San Martiño de Xuvia está situado na parroquia eclesiástica do mesmo nome, no concello de Narón, provincia da Coruña. O edificio actual foi construído a comezos do século XII en estilo románico compostelán.',43.4979723,-8.174282,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Martiño_do_Couto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182076,'39087','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción de la localidad de Torrelavega (Cantabria, España) es un templo religioso de culto católico bajo la advocación mariana de Nuestra Señora de la Asunción. Se trata de una iglesia monumental, de estilo neogótico, construida a finales del siglo XIX. Se concibió como la obra…',43.3518411,-4.0472205,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Torrelavega)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182077,'22002','Ermita de Nuestra Señora del Rocio','religioso','religioso_osm','La ermita del Rocío, denominada oficialmente como santuario de Nuestra Señora del Rocío, es un templo católico situado en la aldea de El Rocío, Almonte, provincia de Huelva. El santuario actual fue diseñado por Antonio Delgado y Roig y Alberto Balbontín de Orta y se terminó en 1969.​ En la ermita se venera la…',37.1307097,-6.4847478,'https://es.wikipedia.org/wiki/Ermita_de_El_Rocío');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182078,'33036','Basílica de Llanes','religioso','religioso_osm','La basílica menor de Santa María de la Asunción de Llanes, también llamada Santa María del Conceyu en Llanes (Asturias, España) es uno de los pocos ejemplos del gótico en Asturias. Su construcción fue a instancias del pueblo de Llanes, iniciándose las obras en 1240, continuándose hasta el siglo XIV-XV. Declarada…',43.4213786,-4.7539498,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_del_Conceyu_(Llanes)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182079,'35016','Catedral de Santa Ana','religioso','religioso_osm','La Santa Iglesia Catedral-Basílica de Canarias​​​ o catedral-basílica de Santa Ana​​ es una catedral, sede de la diócesis de Canarias de la Iglesia católica, que está ubicada en el casco histórico de la ciudad de Las Palmas de Gran Canaria, en el barrio de Vegueta, junto a la plaza Mayor de Santa Ana. Cada 26 de…',28.100842,-15.4146987,'https://es.wikipedia.org/wiki/Catedral_de_Canarias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182080,'35016','Parroquia San Augustín, Santuario Santa Rita','religioso','religioso_osm','La parroquia matriz de san Agustín de Hipona y santuario de santa Rita de Cassia es la parroquia matriz de la ciudad de Las Palmas de Gran Canaria y de la isla de Gran Canaria (Islas Canarias, España). Se encuentra situada en el casco histórico del barrio de Vegueta.',28.1001256,-15.4123139,'https://es.wikipedia.org/wiki/Parroquia_Matriz_de_San_Agustín_(Las_Palmas_de_Gran_Canaria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182081,'38023','Iglesia de Nuestra Señora de la Concepción','religioso','religioso_osm','La parroquia matriz de Nuestra Señora de La Concepción es un templo católico situado en la ciudad de Santa Cruz de Tenerife (Canarias, España). Esta iglesia es el principal templo e iglesia matriz de la ciudad, razón por la cual es llamada "la Catedral de Santa Cruz" por muchos santacruceros, pese a no ser una…',28.4644242,-16.2489506,'https://es.wikipedia.org/wiki/Iglesia_Matriz_de_la_Concepción_(Santa_Cruz_de_Tenerife)');
