INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182083,'42173','Ermita de Nuestra Señora de la Soledad','religioso','religioso_osm','Situada en el centro urbano de Soria, extramuros de la vieja ciudad medieval, la ermita de la Soledad se alza en la parte baja de la Alameda de Cervantes (Soria), junto al paseo del Espolón con el que linda por el norte. En un enclave natural privilegiado de más de nueve hectáreas de extensión, la Alameda se abre…',41.7643393,-2.4708993,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_la_Soledad_(Soria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182084,'20903','Parroquia de la Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción​ es un inmueble de la localidad española de Astigarraga, en la provincia de Guipúzcoa.',43.2814978,-1.9486741,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Astigarraga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182085,'39076','Colegiata de Santillana del Mar','religioso','religioso_osm','La colegiata de Santa Juliana de Santillana del Mar (Cantabria, España), a la que debe su nombre esta localidad cántabra (Sant Iuliana-Santillana), es uno de los monumentos románicos más representativos de la región. Fue declarada Monumento Nacional de España el 12 de marzo de 1889.',43.3923004,-4.1060322,'https://es.wikipedia.org/wiki/Colegiata_de_Santillana_del_Mar');
