INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182101,'29069','Parroquia Nuestra Señora de La Encarnación','religioso','religioso_osm','La iglesia de Santa María de la Encarnación es un templo religioso bajo la advocación de Santa María de la Encarnación de la ciudad de Marbella, en la provincia de Málaga, comunidad autónoma de Andalucía, en España.',36.5098046,-4.8838994,'https://es.wikipedia.org/wiki/Iglesia_de_la_Encarnación_(Marbella)');
