INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182103,'28079','Basílica Pontificia de San Miguel','religioso','religioso_osm','La Basílica de San Miguel (oficialmente Basílica Pontificia de San Miguel) está ubicada en la calle de San Justo número 4, en Madrid (España). Se encuentra junto al Palacio Arzobispal, en el corazón de la zona conocida como Madrid de los Austrias.',40.4143913,-3.7096273,'https://es.wikipedia.org/wiki/Basílica_pontificia_de_San_Miguel');
