INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182107,'51025','Catedral de Ávila','religioso','religioso_osm','La Catedral del Salvador es un templo de culto católico de la ciudad española de Ávila, sede episcopal de la diócesis del mismo nombre. Fue proyectada como templo y fortaleza, siendo su ábside uno de los cubos de la muralla de la ciudad.',40.6558008,-4.6972391,'https://es.wikipedia.org/wiki/Catedral_de_Ávila');
