INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182114,'90631','Iglesia de Nuestra Señora del Rosario','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora del Rosario se encuentra en el término municipal de Barlovento, isla de La Palma (Canarias, España). Se desconoce la fecha de construcción aunque se estima que fue alrededor del año 1581.',28.8297412,-17.8032184,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Rosario_(Barlovento)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182115,'09003','Iglesia de Nuestra Señora de Fátima','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de Fátima es un templo católico levantado en el siglo XX en Burgos (Castilla y León, España). El templo está situado en la calle Nuestra Señora de Fátima, cerca de la plaza de Lavaderos y del busto de Juan XXIII (en el barrio de Gamonal).',42.351186,-3.6748332,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Fátima_(Burgos)');
