INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182117,'30030','Monasterio de Santa Clara la Real','religioso','religioso_osm','El monasterio de Santa Clara la Real es un conjunto monástico de la orden de las Clarisas situado en la ciudad de Murcia (Región de Murcia, España). Tiene su origen en el siglo XIV, ocupando lo que fue el antiguo Al-Qasr al-Sagir (Alcázar Menor) musulmán del siglo XIII.​ Es uno de los edificios históricos más…',37.9882233,-1.1303786,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_Clara_la_Real_(Murcia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182118,'30030','Santuario de Nuestra Señora de la Fuensanta','religioso','religioso_osm','El santuario de la Virgen de la Fuensanta se encuentra situado en la pedanía de Algezares en Murcia (Región de Murcia, España); se comenzó a construir en 1694 sobre los restos de una antigua ermita medieval.​ En este santuario se aloja la imagen de la Virgen de la Fuensanta, patrona de la ciudad de Murcia y su…',37.9375232,-1.1182252,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_la_Fuensanta_(Murcia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182119,'37011','Catedral Vieja','religioso','religioso_osm','La catedral de Santa María de la Sede, conocida como catedral Vieja, es una de las dos catedrales que hay en Salamanca. Fundada por el obispo Jerónimo de Perigord, se empezó a construir en el primer tercio del siglo XII y se terminó a finales del siglo XIV, en estilo románico y gótico.',40.9605036,-5.6666149,'https://es.wikipedia.org/wiki/Catedral_Vieja_de_Salamanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182120,'37011','Convento de Las Agustinas','religioso','religioso_osm','El convento de las Agustinas y la iglesia de la Purísima forman un conjunto conventual de clausura situado en el centro histórico de la ciudad de Salamanca. Fue declarado Monumento Nacional por Decreto de 15 de abril de 1935.',40.9644425,-5.6668776,'https://es.wikipedia.org/wiki/Convento_de_las_Agustinas_e_Iglesia_de_la_Purísima_(Salamanca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182121,'09439','Iglesia de Nuestra Señora del Pilar','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora del Pilar es un templo católico levantado en el siglo XX en Burgos (Castilla y León, España). Está situada frente a la Plaza Virgen del Pilar, en el barrio del Pilar (también conocido como “de la SESA”).​ La Sociedad Española de Seda Artificial, “SESA” (antigua Alday y…',42.3440088,-3.7387716,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Pilar_(Burgos)');
