INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182125,'47186','Iglesia de Nuestra Señora de las Angustias','religioso','religioso_osm','La iglesia penitencial de Nuestra Señora de las Angustias es una iglesia vallisoletana situada en el centro de la ciudad frente al Teatro Calderón y cerca de la Iglesia de Santa María La Antigua. La iglesia es propiedad y sede de la Ilustre Cofradía Penitencial de Nuestra Señora de las Angustias una de las…',41.653916,-4.7238889,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_las_Angustias_(Valladolid)');
