INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182132,'24139','Santuario de la Peregrina','religioso','religioso_osm','El santuario de la Peregrina (Sahagún, León, España), en la actualidad sede del Centro de Documentación del Camino de Santiago de Sahagún, está situado en el extrarradio de la villa. Se asienta sobre una colina, que es el punto más alto de la localidad, a 845 m s.',42.3677694,-5.0324226,'https://es.wikipedia.org/wiki/Iglesia_de_la_Peregrina_(Sahagún)');
