INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182148,'31070','Colegiata de San Miguel Arcángel','religioso','religioso_osm','La colegiata de San Miguel Arcángel es un templo católico ubicado en Alfaro​ (La Rioja, España), fue declarada Monumento Nacional el 23 de abril de 1976. Es el santuario más grande de La Rioja y la única colegiata de España realizada por completo en ladrillo.',42.1780723,-1.7489712,'https://es.wikipedia.org/wiki/Colegiata_de_San_Miguel_Arcángel');
