INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182153,'28079','Ermita de la Virgen del Puerto','religioso','religioso_osm','La ermita de la Virgen del Puerto de Madrid (España) está situada en el paseo de la Virgen del Puerto (antiguo paseo Nuevo de la Corte), en las inmediaciones del Palacio Real. Es obra de Pedro de Ribera,​ fue construida entre 1716 y 1718 por empeño personal de Antonio de Salcedo y Aguirre, primer marqués de…',40.4155353,-3.7212473,'https://www.ermitavirgendelpuerto.es/','https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_del_Puerto_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182154,'28043','Ermita del Santísimo Cristo del Humilladero','religioso','religioso_osm','La ermita del Santísimo Cristo del Humilladero situada en el municipio de Colmenar de Oreja (Comunidad de Madrid, España) agrupa distintas construcciones en distintas épocas; una capilla del siglo XVI, camarín y habitaciones para el capellán. Puede considerarse el tercero de los monumentos más importantes de la…',40.1031113,-3.3849338,'https://es.wikipedia.org/wiki/Ermita_del_Santísimo_Cristo_del_Humilladero_(Colmenar_de_Oreja)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182155,'16078','Convento de San Pedro de las Justinianas','religioso','religioso_osm','El convento de San Pedro de las Justinianas en Cuenca (España), data de mediados del siglo XVIII, cuando el canónigo Lujando decidió llamar a Alejandro González Velázquez y a Blas de Rentería para que hicieran las trazas y redactaran las condiciones de las obras de la iglesia, aunque quien realmente la diseñó fue…',40.0788548,-2.1300495,'https://es.wikipedia.org/wiki/Convento_de_San_Pedro_de_las_Justinianas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182156,'24209','Colegiata de Santa María','religioso','religioso_osm','La colegiata de Santa María del Cluniaco, Coruniego o Cruñego sita en la localidad de Villafranca del Bierzo, en la comarca de El Bierzo (provincia de León, comunidad autónoma de Castilla y León, España) tuvo sus orígenes en un monasterio benedictino erigido en el siglo XII, con hospedería aneja para atender a los…',42.6094889,-6.8094531,'https://es.wikipedia.org/wiki/Colegiata_de_Santa_María_(Villafranca_del_Bierzo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182157,'28079','Catedral Castrense de las Fuerzas Armadas','religioso','religioso_osm','La Iglesia Catedral de las Fuerzas Armadas, también conocida como Catedral Castrense, iglesia de las bernardas del Sacramento o iglesia del Sacramento, es un templo católico de la ciudad española de Madrid. Está situada en la calle del Sacramento, frente al Palacio de los Consejos.',40.4146498,-3.7122284,'https://es.wikipedia.org/wiki/Iglesia_del_Sacramento_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182158,'51003','Iglesia de la Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia mayor de la Asunción de Nuestra Señora es un templo católico de España localizado en el municipio de El Barco de Ávila, perteneciente a la provincia de Ávila, comunidad autónoma de Castilla y León.',40.3559109,-5.5268552,'https://es.wikipedia.org/wiki/Iglesia_Mayor_de_la_Asunción_de_Nuestra_Señora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182159,'41024','Convento de Santa Clara','religioso','religioso_osm','El convento de Santa Clara, situado en Carmona (provincia de Sevilla), fue fundado en 1460, siendo una de las primeras muestras de arquitectura conventual existente en la ciudad. Su fundación se autorizó mediante una bula otorgada por el pontífice Pío II en 1460, a petición de sus fundadoras doña Teresa y doña…',37.4742833,-5.6361678,'https://es.wikipedia.org/wiki/Convento_de_Santa_Clara_(Carmona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182160,'51025','Basílica de San Vicente','religioso','religioso_osm','La basílica de los Santos Hermanos Mártires, Vicente, Sabina y Cristeta, más conocida simplemente como basílica de San Vicente,​ es un templo románico ubicado en Ávila, España, el de mayor tamaño e importancia de la ciudad después de la catedral del Salvador y una de las obras más destacadas de este estilo…',40.6579937,-4.6960023,'https://es.wikipedia.org/wiki/Basílica_de_San_Vicente_(Ávila)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182161,'31076','Parroquia de Nuestra Señora de la Purificación','religioso','religioso_osm','La iglesia de Nuestra Señora de la Purificación es una iglesia románica del siglo XIII situada en la localidad de Gazólaz (Cizur, Navarra, España).​​​​ Cuenta con una galería porticada, excepcional en Navarra, y es uno de los ejemplares más septentrionales de esta forma arquitectónica típica de la zona más…',42.7916015,-1.7178801,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Purificación_(Gazólaz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182162,'27030','Santuario de Nosa Señora dos Remedios','religioso','religioso_osm','O Santuario da Nosa Señora dos Remedios é un santuario localizado na parroquia dos Remedios, no concello de Mondoñedo. No interior do santuario destaca o conxunto barroco.',43.4282805,-7.3702353,'https://gl.wikipedia.org/wiki/Santuario_da_Nosa_Señora_dos_Remedios_de_Mondoñedo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182163,'41044','Ermita de la Virgen de Valme','religioso','religioso_osm','La Virgen de Valme es una imagen mariana venerada en la Iglesia Parroquial de Santa María Magdalena (Dos Hermanas Sevilla) y es considerada como la mayor devoción de la ciudad. Es la única imagen de la ciudad coronada canónicamente el 23 de junio de 1973 y posee el título de Protectora de la ciudad y Patrona del…',37.3255986,-5.9738201,'https://es.wikipedia.org/wiki/Virgen_de_Valme');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182164,'38023','Parroquia Matriz de Nuestra Señora de La Concepción','religioso','religioso_osm','La parroquia matriz de Nuestra Señora de la Concepción es la parroquia matriz de la ciudad de San Cristóbal de La Laguna y de la isla de Tenerife (Canarias, España), erigida en 1497. Está encuadrada entre las plazas de La Concepción y Doctor Olivera.',28.4904301,-16.3203302,'https://es.wikipedia.org/wiki/Parroquia_Matriz_de_Nuestra_Señora_de_la_Concepción_(San_Cristóbal_de_La_Laguna)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182165,'41091','Convento Santa María de Jesús','religioso','religioso_osm','El convento de Santa María de Jesús es un establecimiento religioso de Sevilla fundado en 1502, perteneciente a la orden de las clarisas.',37.3895277,-5.9876947,'https://es.wikipedia.org/wiki/Convento_de_Santa_María_de_Jesús_(Sevilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182166,'41091','Convento de Santa Isabel','religioso','religioso_osm','El convento de Santa Isabel de la Congregación de Religiosas Filipenses Hijas de María Dolorosa en Sevilla (España) se encuentra situado en el centro histórico de la ciudad con accesos desde el número 2 de la calle Hiniesta, y desde la plaza Santa Isabel. En sus proximidades se halla otro de los grandes conventos…',37.3966578,-5.9866506,'https://es.wikipedia.org/wiki/Convento_de_Santa_Isabel_(Sevilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182167,'41091','Monasterio Santa María del Socorro','religioso','religioso_osm','El convento de Santa María del Socorro se encuentra en la calle Socorro del barrio de San Julián de Sevilla, Andalucía, España.',37.3955792,-5.9874927,'https://es.wikipedia.org/wiki/Convento_de_Santa_María_del_Socorro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182168,'41091','Convento de Santa Paula','religioso','religioso_osm','El convento de Santa Paula es un monasterio de clausura en Sevilla, España, de monjas de la Orden de San Jerónimo, catalogado como monumento histórico. Dedicado a Santa Paula de Roma, se encuentra situado en el centro histórico de la ciudad, a espaldas de la parroquia de San Marcos y muy próximo a otro de los…',37.3963438,-5.9854202,'https://es.wikipedia.org/wiki/Convento_de_Santa_Paula_(Sevilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182169,'41091','Iglesia de Nuestra Señora de la Paz','religioso','religioso_osm','El hospital de Nuestra Señora de la Paz de Sevilla (Andalucía, España), también conocido como asilo de San Juan de Dios, es un antiguo hospital cuya construcción se inició en el siglo XVI, está catalogado como Bien de Interés Cultural. Se encuentra situado en el centro de la ciudad, con fachadas a la plaza del…',37.3899406,-5.9934578,'https://sevillapedia.wikanda.es/wiki/Antiguo_Hospital_de_Nuestra_Se%C3%B1ora_de_la_Paz_%28Sevilla%29','https://es.wikipedia.org/wiki/Hospital_de_Nuestra_Señora_de_la_Paz_(Sevilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182170,'41091','Capilla de Nuestra Señora de la Piedad','religioso','religioso_osm','La capilla de la Piedad es un edificio de culto católico que se encuentra en la calle Adriano nº 13 del barrio del Arenal, en la localidad de Sevilla, Andalucía, España.',37.386233,-5.9974702,'https://es.wikipedia.org/wiki/Capilla_de_la_Piedad_(Sevilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182171,'41091','Basílica del Gran Poder','religioso','religioso_osm','La basílica de Jesús del Gran Poder es un templo católico situado en el barrio de San Lorenzo de la ciudad de Sevilla, comunidad autónoma de Andalucía, en España.',37.3971741,-5.9961527,'https://es.wikipedia.org/wiki/Basílica_de_Jesús_del_Gran_Poder');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182172,'41091','Iglesia del Sagrado Corazón de Jesús','religioso','religioso_osm','La iglesia del Sagrado Corazón de Jesús se encuentra en Sevilla (Andalucía, España). Fue la iglesia del antiguo Colegio de San Francisco de Paula, de los mínimos, entre el siglo XVI y comienzos del siglo XIX. Desde 1887 pertenece a los jesuitas.',37.3957501,-5.9953361,'https://es.wikipedia.org/wiki/Iglesia_del_Sagrado_Corazón_de_Jesús_(Sevilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182173,'01014','Igrexa do Mosteiro de San Xusto de Toxosoutos','religioso','religioso_osm','O Mosteiro dos Santos Xusto e Pastor de Toxos Outos é un antigo mosteiro, hoxe abandonado, no lugar de San Xusto, no concello de Lousame.',42.8117694,-8.81982,'https://gl.wikipedia.org/wiki/Mosteiro_dos_Santos_Xusto_e_Pastor_de_Toxos_Outos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182174,'90778','Basilica Nuestra Señora de Candelaria','religioso','religioso_osm','La Basílica​ y Real Santuario​ Mariano de Nuestra Señora de Candelaria es el primer templo mariano del Archipiélago Canario.​ Esta basílica se encuentra en el municipio de Candelaria en la isla de Tenerife (Canarias, España). Está situada a 20 kilómetros al sur de la capital de la isla, Santa Cruz de Tenerife.',28.3512166,-16.3699075,'https://www.dominicoshispania.org/donde-estamos/convento-de-ntra-sra-de-candelaria-tenerife/horarios/','https://es.wikipedia.org/wiki/Basílica_de_Nuestra_Señora_de_la_Candelaria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182175,'08211','Catedral de Sant Feliu de Llobregat','religioso','religioso_osm','La Catedral de Sant Feliu de Llobregat o Església Catedral de Sant Llorenç és un edifici religiós situat a la Plaça de la Vila de Sant Feliu de Llobregat i dedicat al Sant Llorenç.',41.3808773,2.0462359,'https://ca.wikipedia.org/wiki/Catedral_de_Sant_Feliu_de_Llobregat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182176,'18087','Catedral de Granada','religioso','religioso_osm','La Santa y Apostólica Iglesia Catedral Metropolitana Basílica de la Encarnación de Granada​ es un templo católico de la ciudad española de Granada, sede de la archidiócesis de la ciudad. El templo es una de las obras cumbres del Renacimiento español.',37.1764612,-3.5991698,'https://catedraldegranada.com/','https://es.wikipedia.org/wiki/Catedral_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182177,'50067','Iglesia de la Virgen de la Peña','religioso','religioso_osm','El santuario de Nuestra Señora de la Peña es una iglesia de la localidad española de Calatayud.',41.3543565,-1.6487957,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_la_Peña_(Calatayud)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182178,'30024','Colegiata de San Patricio','religioso','religioso_osm','La antigua colegiata de San Patricio de Lorca (aunque comúnmente sigue siendo llamada colegiata de San Patricio), es un edificio de estilo renacentista declarado Monumento Histórico-Artístico Nacional por decreto del 27 de enero de 1941.​ La Colegiata es la piedra angular del conjunto monumental de la Plaza de…',37.6769623,-1.6995731,'https://es.wikipedia.org/wiki/Colegiata_de_San_Patricio');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182179,'90629','Parroquia Virgen del Mar','religioso','religioso_osm','La iglesia de Nuestra Señora del Carmen es la parroquia del pueblo de la Caleta del Sebo y de la isla de La Graciosa (Islas Canarias, España). La iglesia está dedicada a la Virgen del Carmen, también llamada localmente Virgen del Mar, la cual es la patrona de la Caleta del Sebo y de toda la isla de La Graciosa.',29.2315678,-13.5022201,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Carmen_(La_Graciosa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182180,'90024','Monestir de Sant Jeroni de la Murtra','religioso','religioso_osm','Sant Jeroni de la Murtra o de Nostra Senyora de la Vall de Betlem és un antic cenobi de l''orde dels jerònims, situat a la vall de Poià o de Betlem, a la serralada de Marina, al barri del Canyet de Badalona (Barcelonès). Va ser declarat monument historicoartístic d''interès nacional el 1975, i posteriorment, el 2014,…',41.4699322,2.2207299,'https://www.lamurtra.cat/','https://ca.wikipedia.org/wiki/Sant_Jeroni_de_la_Murtra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182181,'35024','Iglesia de Nuestra Señora de Guadalupe','religioso','religioso_osm','La Iglesia de Nuestra Señora de Guadalupe es un edificio religioso en Teguise, isla de Lanzarote, Islas Canarias, España. Es la parroquia matriz de la isla y del municipio de Teguise.',29.0593772,-13.5597312,'https://es.wikipedia.org/wiki/Iglesia_Matriz_de_Nuestra_Señora_de_Guadalupe_(Teguise)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182182,'38052','Ermita de Nuestra Señora de las Nieves','religioso','religioso_osm','La ermita de Nuestra Señora de las Nieves es un pequeño templo católico que se encuentra junto al parador de Las Cañadas del Teide, dentro del parque nacional del Teide en la isla canaria de Tenerife (España). Esta ermita destaca por ser el templo cristiano a más altitud de España y está consagrado a la Virgen de…',28.2238186,-16.6279853,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_las_Nieves_(Las_Cañadas_del_Teide)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182183,'47186','Iglesia de Nuestra Señora del Carmen','religioso','religioso_osm','La iglesia de Nuestra Señora del Carmen es un templo católico ubicado en el barrio de las Delicias de Valladolid. Se encuentra en la Avenida de Segovia, 131.',41.6373551,-4.721077,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Carmen_(Valladolid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182184,'10203','Iglesia de Nuestra Señora de Rocamador','religioso','religioso_osm','La iglesia de Nuestra Señora de Rocamador es un templo católico ubicado en la localidad española de Valencia de Alcántara, en la provincia de Cáceres. Es de estilo gótico y data del siglo XVI con portada del siglo XVIII. Fue declarada Monumento histórico-artístico en 1981.',39.4126267,-7.2401998,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Rocamador_(Valencia_de_Alcántara)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182185,'46250','Basílica de la Mare de Déu dels Desemparats','religioso','religioso_osm','La Basílica de la Mare de Déu dels Desemparats de la ciutat de València alberga la imatge de la Mare de Déu del mateix nom, la més venerada pels valencians. El 1652 va començar la construcció de la capella adequada al creixent culte tributat a la imatge de la confraria de «Nostra Dona Sancta Maria dels Ignocents»,…',39.4762535,-0.374809,'https://ca.wikipedia.org/wiki/Basílica_de_la_Mare_de_Déu_dels_Desemparats');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182186,'46250','Catedral de València','religioso','religioso_osm','La iglesia catedral-basílica metropolitana de la Asunción de Nuestra Señora de Valencia, llamada popularmente la Seu en valenciano, es sede del arzobispado de Valencia y está dedicada por deseo de Jaime I —siguiendo la tradición del siglo XIII— a la Asunción de María. Fue consagrada el año 1238 por el primer obispo…',39.4755689,-0.3751044,'https://es.wikipedia.org/wiki/Catedral_de_Santa_María_(Valencia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182187,'17180','Mare de Déu de Farners','religioso','religioso_osm','L''església de la Mare de Déu de Farners és una ermita construïda als peus del castell de Farners, a 5 quilòmetres de Santa Coloma de Farners. El seu estil és una barreja de romànic i barroc, a causa de l''ampliació que va patir l''ermita a posterior.',41.8600506,2.6328741,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Farners');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182188,'38011','Iglesia de Nuestra Señora de la Peña de Francia','religioso','religioso_osm','La parroquia matriz de Nuestra Señora de la Peña de Francia es un templo católico sito en la ciudad española de Puerto de la Cruz (Tenerife, Canarias). En este templo se encuentran algunas de las imágenes más veneradas en Tenerife, como son la Virgen del Carmen de Puerto de la Cruz y el Gran Poder de Dios.',28.4169292,-16.5482763,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Peña_de_Francia_(Puerto_de_la_Cruz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182189,'08003','Santuari de la Mare de Déu del Mont Carmel','religioso','religioso_osm','El Santuari de la Mare de Déu del Mont Carmel és un edifici religiós situat al barri del Carmel del districte d''Horta-Guinardó de Barcelona.',41.4189285,2.156884,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_del_Mont_Carmel');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182190,'35014','Iglesia de Nuestra Señora de la Candelaria','religioso','religioso_osm','La iglesia de Nuestra Señora de la Candelaria está ubicada en el municipio de La Oliva, isla de Fuerteventura (Canarias, España).',28.6111907,-13.9278651,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Candelaria_(La_Oliva)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182191,'32054','Catedral de San Martiño de Ourense','religioso','religioso_osm','A catedral de Ourense, baixo a advocación de san Martiño, é un templo católico situado na cidade de Ourense, sede da diocese do mesmo nome. É de estilo románico de transición con influencias cistercienses nalgúns aspectos arquitectónicos e mateanos no eido escultural, pero no que se realizaron numerosas…',42.3364155,-7.863175,'https://gl.wikipedia.org/wiki/Catedral_de_Ourense');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182192,'08279','Catedral del Sant Esperit','religioso','religioso_osm','La catedral de Terrassa o basílica del Sant Esperit és un edifici religiós situat a la plaça Vella de Terrassa i dedicat al Sant Esperit. L''any 2004 el Vaticà va crear el nou bisbat de Terrassa, com a segregació del bisbat de Barcelona, i va decidir fer servir la basílica del Sant Esperit com a nova catedral.',41.5621292,2.0119501,'https://ca.wikipedia.org/wiki/Catedral_de_Terrassa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182193,'47175','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia parroquial de la Asunción es un templo católico ubicado en la localidad de Tudela de Duero, provincia de Valladolid (Castilla y León, España).',41.5839813,-4.5798082,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Tudela_de_Duero)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182194,'38011','Iglesia de Nuestra Señora de la Concepción','religioso','religioso_osm','La parroquia matriz de Nuestra Señora de la Concepción es la mejor muestra del barroco en Canarias​ (España). Se encuentra en la Villa de La Orotava, en la isla de Tenerife.',28.3899233,-16.5256107,'https://es.wikipedia.org/wiki/Iglesia_de_la_Concepción_(La_Orotava)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182195,'25120','Catedral Nova','religioso','religioso_osm','La Catedral Nova de Lleida o Seu Nova és l''actual seu del Bisbat de Lleida. Se situa al bell mig de la ciutat, davant de l’Antic Hospital de Santa Maria, actual seu de l''Institut d''Estudis Ilerdencs.',41.6132316,0.6229413,'https://ca.wikipedia.org/wiki/Catedral_Nova_de_Lleida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182196,'28514','Templo de Madrid de la Iglesia de Jesucristo de los Santos de los Últimos Días','religioso','religioso_osm','El Templo de Madrid es uno de los templos construidos y operados por la Iglesia de Jesucristo de los Santos de los Últimos Días. Fue el 56.º templo construido por esta organización, y el primero de España, ubicado en su capital, Madrid.',40.40012,-3.6315382,'https://www.churchofjesuschrist.org/temples/details/madrid-spain-temple?lang=spa','https://es.wikipedia.org/wiki/Templo_de_Madrid_(España)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182197,'38024','Nuestra Señora de las Angustias','religioso','religioso_osm','Nuestra Señora de las Angustias, es una advocación mariana católica que se venera en el Santuario de Nuestra Señora de las Angustias, situado en el término municipal de Los Llanos de Aridane en la isla canaria de La Palma (España). Es la alcaldesa Honoraria del municipio de Los Llanos de Aridane y una de las…',28.6615758,-17.9350012,'https://es.wikipedia.org/wiki/Nuestra_Señora_de_las_Angustias_(Los_Llanos_de_Aridane)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182198,'25232','Església Mare de Déu de l''Assumpció','religioso','religioso_osm','La Mare de Déu de l''Assumpció d''Alcarràs és una església parroquial del municipi d''Alcarràs (Segrià) protegida com a bé cultural d''interès local.',41.5633367,0.524303,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_l''Assumpció_d''Alcarràs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182199,'27066','Igrexa do Convento de San Francisco','religioso','religioso_osm','A igrexa do Convento de San Francisco é o templo católico da parroquia de Santiago de Viveiro (concello de Viveiro). É unha construción erixida no século XIV, con nave única.',43.6631394,-7.5941203,'https://gl.wikipedia.org/wiki/Igrexa_de_San_Francisco_de_Viveiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182200,'39032','Ermita de la Virgen del Abra','religioso','religioso_osm','La Virgen del Abra, Nuestra Señora la Virgen de Labra, o la Virgen de Labra es una advocación mariana de la Virgen María. Es la patrona del Valle de Campoo y se venera en la ermita de San Miguel de Soma Celada, en la vega del Híjar.',43.012243,-4.2605695,'https://es.wikipedia.org/wiki/Virgen_de_Labra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182201,'16009','Iglesia de Nuestra Señora del Carmen','religioso','religioso_osm','La Iglesia del Carmen que se encuentra en la Alameda Marqués de Comillas, en la ciudad de Cádiz (Andalucía, España) es un templo católico de estilo barroco. Su advocación completa es Nuestra Señora del Carmen y Santa Teresa.',36.5371534,-6.2998097,'https://es.wikipedia.org/wiki/Iglesia_del_Carmen_(Cádiz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182202,'16009','Iglesia y Convento de San Francisco','religioso','religioso_osm','El Convento de San Francisco de Cádiz es un antiguo convento franciscano situado en el interior del casco antiguo de la ciudad, en la céntrica plaza de su mismo nombre. Del complejo original solo restan el claustro y la iglesia.',36.5347947,-6.2959078,'https://es.wikipedia.org/wiki/Convento_de_San_Francisco_(Cádiz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182203,'27019','Basílica de San Martiño de Mondoñedo','religioso','religioso_osm','Non confundir coa Catedral de Mondoñedo. A basílica de San Martiño de Mondoñedo é un templo de orixe prerrománica situado na Mariña Lucense, sé do bispado de Mondoñedo durante moitos anos, que se atopa en bo estado de conservación.',43.5610659,-7.3033455,'https://gl.wikipedia.org/wiki/Basílica_de_San_Martiño_de_Mondoñedo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182204,'30042','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción en Villanueva del Río Segura (Región de Murcia) fue construida a principios del siglo XIX en estilo neoclásico. Sus trazas se deben al arquitecto Juan de Villanueva.',38.1374639,-1.3241842,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Villanueva_del_Río_Segura)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182205,'37350','Ermita de la Virgen del Castillo','religioso','religioso_osm','La ermita de la Virgen del Castillo de Vilvestre es una pequeña ermita de estilo barroco, y se sitúa junto a las ruinas del castillo, del pueblo de Vilvestre, en la provincia de Salamanca.',41.1043204,-6.7304372,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_del_Castillo_(Vilvestre)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182206,'20077','Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Santa María de la Asunción es un inmueble de la localidad española de Zumárraga, en la provincia de Guipúzcoa.',43.0888543,-2.3134172,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_de_la_Asunción_(Zumárraga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182207,'08177','Mare de Déu de la Quar','religioso','religioso_osm','Santa Maria de la Quar és una església que hi ha al municipi de la Quar, al Berguedà. Ha estat catalogada com a patrimoni immoble al mapa de patrimoni de la Generalitat de Catalunya amb el número 3528.',42.1057706,1.973643,'https://ca.wikipedia.org/wiki/Santa_Maria_de_la_Quar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182208,'36011','Real Basílica de Santa María a Maior','religioso','religioso_osm','A basílica de Santa María a Maior de Pontevedra é un templo católico do século XVI, consagrado como basílica o 10 de xaneiro de 1962 por decreto do Papa Xoán XXIII. Actualmente ten a consideración de BIC (Ben de Interese Cultural de España, con número de identificación RI-51-0000828). Foi declarada monumento…',42.4337758,-8.6475775,'https://gl.wikipedia.org/wiki/Basílica_de_Santa_María_a_Maior_de_Pontevedra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182209,'04052','Convento de Santa Clara','religioso','religioso_osm','La iglesia y el convento de Santa Clara, de la ciudad española de Almería (Andalucía), comprenden un amplio rectángulo situado entre las calles de Jovellanos, Mariana, Marín y plaza de la Constitución.',36.8404671,-2.4668511,'https://es.wikipedia.org/wiki/Convento_de_las_Claras_(Almería)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182210,'17227','Monestir de Sant Quirze de Colera','religioso','religioso_osm','El monestir de Sant Quirze de Colera és una abadia benedictina de l''antic comtat d''Empúries, dins els límits del bisbat de Girona, situada a l''actual terme municipal de Rabós (Alt Empordà). És un conjunt arquitectònic format per la basílica de Sant Quirze, diverses dependències monàstiques organitzades al voltant…',42.4162761,3.0588853,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Quirze_de_Colera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182211,'02046','Asunción de Nuestra Señora','religioso','religioso_osm','La Iglesia de Nuestra Señora de la Asunción Mahora, es un templo católico de la citada población de la Manchuela albaceteña, que está catalogado como Bien de Interés Cultural desde el 22 de diciembre de 1992 y tiene como identificador del bien otorgado por el Ministerio de Cultura de España: RI-51-0007366.​',39.2130726,-1.7246323,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Mahora)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182212,'90240','Iglesia colegiata de San Miguel','religioso','religioso_osm','La iglesia colegiata de San Miguel en Ampudia (provincia de Palencia, España), es una construcción en estilo gótico-renacentista de finales del siglo XV y principios del XVI.',41.9162718,-4.7806528,'https://es.wikipedia.org/wiki/Colegiata_de_Ampudia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182213,'09114','Abadía de San Quirce','religioso','religioso_osm','La abadía de San Quirce fue una antigua abadía del municipio español de Los Ausines, en la provincia de Burgos. Se conserva su iglesia.',42.191038,-3.5969465,'https://es.wikipedia.org/wiki/Abadía_de_San_Quirce');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182214,'34023','Basílica de San Juan de Baños','religioso','religioso_osm','La iglesia basílica de San Juan Bautista es un monumento visigodo situado en la localidad de Baños de Cerrato (antigua Balneos) a tan sólo 7 km de la capital palentina.',41.920808,-4.4722539,'https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_(Baños_de_Cerrato)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182215,'17107','Mare de Déu de les Neus','religioso','religioso_osm','Mare de Déu de les Neus d''Espinavell és una obra del poble d''Espinavell, al municipi de Molló (Ripollès) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.378048,2.3992385,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Neus_de_Molló');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182216,'09013','Colegiata de Santa Ana','religioso','religioso_osm','La excolegiata de Santa Ana es una iglesia de la localidad española de Peñaranda de Duero, en la provincia de Burgos.',41.6885398,-3.4794228,'https://es.wikipedia.org/wiki/Colegiata_de_Santa_Ana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182217,'02009','Santuario de la Virgen de Gracia','religioso','religioso_osm','El Santuario de la Virgen de Gracia sito en la localidad de Caudete (provincia de Albacete, España) se encuentra sobre lo que según la tradición local en época visigoda fue un monasterio benedictino del que no se han hallado restos. El origen de la actual construcción data del siglo XV aunque la mayor ampliación…',38.7001361,-0.9726455,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_de_Gracia_(Caudete)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182218,'17091','Monestir de Sant Pere de Camprodon','religioso','religioso_osm','Sant Pere de Camprodon és un monestir benedictí situat a l''actual vila de Camprodon, al Ripollès.',42.314315,2.3695932,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Camprodon');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182219,'90378','Santuari de la Mare de Déu d''Agres','religioso','religioso_osm','El santuario de la Virgen de Agres o de la Virgen del Castillo (en valenciano Santuari de la Mare de Deu d''Agres) en el término municipal de Agres (Alicante) está construido sobre los restos de un antiguo castillo al sur de la población en un emplazamiento prostis natural entre torrenteras y bosques de frondoso…',38.7758946,-0.5151253,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_(Agres)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182220,'18008','Mare de Déu dels Àngels','religioso','religioso_osm','L''església de la Mare de Déu dels Àngels de Llívia és una obra del municipi de Llívia (Cerdanya) que s''aixecà els segles xvi i xvii sobre d''una altra d''anterior, aprofitant-ne els materials. Ambdós edificis estan inventariats de manera separada: l''església forma part de l''Inventari del Patrimoni Arquitectònic de…',42.4652591,1.9821182,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Àngels_de_Llívia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182221,'17196','Santuari de la Mare de Déu de la Salut','religioso','religioso_osm','Santuari de la Mare de Déu de la Salut és una església del municipi de Terrades (Alt Empordà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3253313,2.8342872,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_la_Salut_(Terrades)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182222,'07026','Catedral d''Eivissa','religioso','religioso_osm','La catedral de la Virgen de las Nieves de Ibiza está situada en el Dalt Vila en la ciudad de Ibiza (Islas Baleares, España). Fue construida sobre la antigua mezquita de Yebisah.',38.9066588,1.436696,'https://www.obispadodeibiza.es/es/index.php','https://es.wikipedia.org/wiki/Catedral_de_Ibiza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182223,'43176','Reial Monestir de Santa Maria de Poblet','religioso','religioso_osm','El Reial Monestir de Santa Maria de Poblet és un monestir de l''orde del Cister fundat l''any 1150. Està situat al peu de les muntanyes de Prades, a la comarca de la Conca de Barberà.',41.3810774,1.0827355,'https://www.poblet.cat/','https://ca.wikipedia.org/wiki/Reial_Monestir_de_Santa_Maria_de_Poblet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182224,'08254','Santuari de la Mare de Déu de Cabrera','religioso','religioso_osm','Santa Maria de Cabrera és una església del municipi de l''Esquirol (Osona), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. És al cim de la muntanya de Cabrera, al lloc que havia ocupat el castell de Cabrera, del qual queden escasses restes.',42.0733333,2.4078104,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Cabrera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182225,'17080','Mare de Déu de Montgrony','religioso','religioso_osm','El santuari o capella de Santa Maria de Montgrony és un santuari marià del bisbat de Vic, situat al Montgrony. Es troba en el cingle de la serra de Sant Pere, a uns 1370 metres sobre el nivell del mar, en el municipi de Gombrèn, a la comarca catalana del Ripollès.',42.265654,2.0856468,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Montgrony');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182226,'90595','Mare de Déu de les Agulles','religioso','religioso_osm','L''Església de Nostra Senyora de les Agulles és una església del municipi de Montagut i Oix (Garrotxa) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3059082,2.6222472,'https://ca.wikipedia.org/wiki/Església_de_Nostra_Senyora_de_les_Agulles_(Montagut_i_Oix)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182227,'17109','Mare de Déu del Cós','religioso','religioso_osm','Mare de Déu del Cós és una capella del municipi de Montagut i Oix (Garrotxa) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. Està situada a la muntanya del Cós dintre el recinte de l''antic Castell de Montagut.',42.2307481,2.5724641,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Cós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182228,'08201','Mare de Déu dels Munts','religioso','religioso_osm','El Santuari de la Mare de Déu dels Munts és una església barroca de Sant Agustí de Lluçanès (Osona) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0784771,2.1523908,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_dels_Munts');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182229,'08152','Mare de Déu de Collbàs','religioso','religioso_osm','Mare de Déu de Collbàs o Santuari de Collbàs és una ermita dalt d''un turó de la Serra de Collbàs. Inicialment depenia de Santa Maria del castell de Claramunt, i des de 1779 va quedar vinculada a la parròquia de Sant Marti de Carme, terme municipal al qual pertany.',41.544271,1.6084173,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Collbàs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182230,'17208','Ermita de la Mare de Déu dels Àngels','religioso','religioso_osm','Santa Maria de Llongarriu també denominada Santa Maria de Sacot, Santa Maria del Cot, Mare de Déu dels Àngels de Llongarriu és una ermita romànica situada al nucli de població de la Vall del Bac del municipi de la Vall de Bianya dins a la comarca de la Garrotxa. Es troba a 740 m d''altitud dominant la riera d''Oix,…',42.2582728,2.4509367,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Llongarriu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182231,'30012','Iglesial Nuestra Señora del Rosario','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora del Rosario está ubicada en el municipio de Bullas perteneciente a la Región de Murcia, España.',38.0494666,-1.6701422,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Rosario_(Bullas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182232,'21065','Iglesia de Nuestra Señora de las Flores','religioso','religioso_osm','La Parroquia de Nuestra Señora de las Flores es un templo católico situado en la localidad de Sanlúcar de Guadiana.',37.4725427,-7.4667069,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_las_Flores_(Sanlúcar_de_Guadiana)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182233,'90457','Iglesia de Nuestra Señora de Gracia','religioso','religioso_osm','La Parroquia de Nuestra Señora de Gracia es un templo católico situado en la localidad de Alosno, en la provincia de Huelva (España).',37.5496054,-7.1147177,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Gracia_(Alosno)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182234,'46051','Ermita de la Mare de Déu de Montiel','religioso','religioso_osm','L''Ermita de la Mare de Déu de Montiel és un santuari ubicat al terme municipal de Benaguasil, al Camp de Túria (Comunitat Valenciana). Està situada a un tossal (250 m) des d''on es domina la vila i la comarca.',39.5924567,-0.5975726,'https://ca.wikipedia.org/wiki/Ermita_de_la_Mare_de_Déu_de_Montiel');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182235,'15090','Mosteiro de Santa María de Mezonzo','religioso','religioso_osm','O mosteiro de Santa María de Mezonzo é unha edificación relixiosa da que practicamente só queda a igrexa de estilo románico no lugar do Priorato, da parroquia de Santa María de Mezonzo, no concello de Vilasantar, no extremo sur da comarca de Betanzos, na provincia da Coruña. Foi declarada Monumento…',43.0603205,-8.1346984,'https://gl.wikipedia.org/wiki/Mosteiro_de_Santa_María_de_Mezonzo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182236,'10148','Catedral de Plasencia','religioso','religioso_osm','La catedral de Plasencia o catedral de Santa María es el nombre común que recibe la sede episcopal de la diócesis de Plasencia, una diócesis de la Iglesia católica que extiende su jurisdicción en partes de tres provincias del oeste de España. No es una catedral propiamente dicha en el sentido de un único templo…',40.0277791,-6.0908495,'https://catedralesplasencia.com/','https://es.wikipedia.org/wiki/Catedral_de_Plasencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182237,'43117','Mare de Déu de la Fontcalda','religioso','religioso_osm','El Santuari de la Fontcalda és una església del municipi de Gandesa (Terra Alta) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.00103,0.428711,'https://ca.wikipedia.org/wiki/Santuari_de_Fontcalda_(Gandesa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182238,'08166','Mare de Déu de Falgars','religioso','religioso_osm','Santuari de Falgars és un santuari marià del municipi de la Pobla de Lillet (Berguedà) protegit com a bé cultural d''interès local. Situat a la serra de Falgars, s''hi pot arribar per la carretera asfaltada de la Guardiola, 2 km abans d''arribar a la Pobla de Lillet, ran de la casa de Cal Roger, kilòmetre 71.',42.2274122,1.945649,'https://ca.wikipedia.org/wiki/Santuari_de_Falgars');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182239,'08142','Mare de Déu de Lurda','religioso','religioso_osm','El Santuari de Lurda de la Nou és una església del municipi de la Nou de Berguedà (Berguedà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. És dedicat a la Mare de Déu de Lorda, essent un dels molts testimonis de l''extraordinària popularitat que assolí aquesta devoció a la Mare de Deu arreu del…',42.1629457,1.8845931,'https://ca.wikipedia.org/wiki/Santuari_de_Lurda_de_la_Nou');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182240,'09442','Colegiata de San Pedro','religioso','religioso_osm','Para ver otras colegiatas bajo la misma advocación, véase Colegiata de San Pedro. La Colegiata de San Pedro está situada en la Plaza de San Pedro de la localidad de Lerma (provincia de Burgos, comunidad autónoma de Castilla y León, España).',42.0271451,-3.7588066,'https://es.wikipedia.org/wiki/Colegiata_de_San_Pedro_(Lerma)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182241,'34184','Iglesia de Nuestra Señora del Castillo','religioso','religioso_osm','La iglesia de Santa María del Castillo es un templo de culto católico situado en la pequeña localidad palentina de Torremormojón, en España. Hasta los trabajos de restauración de 1986 el edificio se consideraba como obra del siglo XVI con yeserías renacentistas y otros enmascaramientos.',41.9616581,-4.7770468,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_del_Castillo_(Torremormojón)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182242,'22006','Parroquia de Nuestra Señora de las Angustias','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de las Angustias situada en la barriada de la ribera de Ayamonte, casi al pie del río Guadiana, de la localidad de Ayamonte (provincia de Huelva, Andalucía, España) es un templo católico construido en el siglo XVI, además de ser la parroquia mayor de la ciudad de Ayamonte.',37.2134429,-7.4092335,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_las_Angustias_(Ayamonte)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182243,'25111','Mare de Déu de Puig-aguilar','religioso','religioso_osm','El santuari de la Mare de Déu de Puig-aguilar és un santuari que s''aixeca dalt d''un esperó meridional del Puig Aguilar al terme de la Corriu, pertanyent al municipi de Guixers, a la comarca del Solsonès. És un monument protegit com a Bé Cultural d''Interès Local S''hi accedeix fàcilment per la carretera secundària,…',42.1554795,1.660178,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_Puig-aguilar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182244,'36052','Mosteiro de San Lourenzo de Carboeiro','religioso','religioso_osm','O mosteiro de San Lourenzo de Carboeiro é unha das obras arquitectónicas do románico serodio, de transición ao gótico, máis destacables de Galicia.',42.7555156,-8.2461747,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Lourenzo_de_Carboeiro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182245,'21042','Ermita de Nuestra Señora del Carmen','religioso','religioso_osm','La capilla de Nuestra Sra. del Carmen, o capilla del Carmen, está situada en la Barriada de Canela, en Ayamonte, a escasos 1500 metros del centro de la barriada, de construcción rectangular, alberga en su interior una imagen de la Virgen de su misma advocación Cada año el 16 de julio, la imagen de la Virgen del…',37.197593,-7.4038215,'https://es.wikipedia.org/wiki/Capilla_de_Nuestra_Señora_del_Carmen_(Ayamonte)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182246,'27015','Mare de Déu de Pedra','religioso','religioso_osm','Mare de Déu de Pedra és una església romànica situada als contraforts del Montsec d''Ares al municipi d''Àger (Noguera). La primera documentació és de l''any 1042 i fa referència a l''antic castell de Pedra.',42.0278001,0.7597113,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Pedra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182247,'27015','Mare de Déu de Colobor','religioso','religioso_osm','El santuari de la mare de Déu de Colobor és una ermita situada a la serra del Montsec d''Ares, al municipi d''Àger. Aquest santuari era propietat de l''antic Castell de Colobor i es va construir a sobre l''arbre on es va trobar la imatge de la verge.',42.0327059,0.7886789,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Colobor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182248,'27029','Mosteiro de Santa María de Meira','religioso','religioso_osm','O mosteiro de Santa María de Meira é un mosteiro medieval fundado no século XII, do que se conserva a igrexa e parte das edificacións monásticas, situado na parroquia de Meira, pertencente ao concello do mesmo nome. É un Ben de Interese Cultural.',43.213041,-7.2913075,'https://gl.wikipedia.org/wiki/Mosteiro_de_Santa_María_de_Meira');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182249,'22005','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción de Aroche (Provincia de Huelva, España) es un interesante templo parroquial con un dilatado proceso constructivo que va desde avanzado el siglo XIV hasta el siglo XVII, y recoge por tanto elementos de los distintos estilos arquitectónicos de estas épocas, como son el…',37.9452751,-6.9539936,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Aroche)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182250,'25156','Mare de Déu de Cérvoles','religioso','religioso_osm','La Mare de Déu de Cérvoles és un santuari al terme municipal d''Os de Balaguer (Noguera) catalogat a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''església és d''una sola nau construïda en pedra.',41.8829531,0.6594365,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Cérvoles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182251,'25140','Mare de Déu de la Trobada','religioso','religioso_osm','La Mare de Déu de la Trobada és una ermita del poble de Montferrer, del municipi Montferrer i Castellbò (Alt Urgell). Està situada a la vora del riu del seu mateix nom.',42.346698,1.424074,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Trobada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182252,'25140','Mare de Déu del Remei','religioso','religioso_osm','La Mare de Déu del Remei de Castellbò és una capella de Castellbò, en el municipi de Montferrer i Castellbò (Alt Urgell), inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3735368,1.3636329,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Remei_de_Castellbò');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182253,'03903','Parroquia Virgen del Pilar','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora del Pilar en Los Montesinos (Provincia de Alicante, España), fue construida en 1886, hecho que evidencia la consolidación del asentamiento humano surgido espontáneamente en las inmediaciones de la laguna de Torrevieja, mediante la apropiación de un espacio público, ocupado…',38.0269103,-0.7433032,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Pilar_(Los_Montesinos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182254,'08138','Mare de Déu de la Tosca','religioso','religioso_osm','La Mare de Déu de la Tosca és un santuari del terme municipal de Castellcir, a la comarca del Moianès. És a l''enclavament de la vall de Marfà.',41.7795493,2.0767714,'https://ca.wikipedia.org/wiki/La_Mare_de_Déu_de_la_Tosca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182255,'49189','Santuario de Nuestra Señora de La Alcobilla','religioso','religioso_osm','El santuario de la Virgen de "La Alcobilla" se encuentra dentro del término municipal de San Justo, en la tierra zamorana de Sanabria (España).',42.1406972,-6.6177169,'https://es.wikipedia.org/wiki/La_Alcobilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182256,'47050','Emita Nuestra Señora Virgen de Viloria','religioso','religioso_osm','La Ermita de Nuestra Señora de Viloria se encuentra en el pago de Viloria, entre los antiguos arroyos de Cañuelo y Escarafuelles,​ en el municipio de Cigales, a 1,2 km de su casco urbano siguiendo un camino que antiguamente se llamaba Camino de los Mártires porque era el que seguían los monjes de la orden de San…',41.763317,-4.7147522,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Viloria_(Cigales)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182257,'47186','Iglesia de Nuestra Señora de La Victoria','religioso','religioso_osm','La iglesia de Nuestra Señora de la Victoria es un templo católico de estilo moderno ubicado en la ciudad española de Valladolid.',41.6633682,-4.7339417,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Victoria_(Valladolid)');
