INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182259,'90063','Ermita de la Mare de déu de les Fonts','religioso','religioso_osm','Mare de Déu de les Fonts és una capella del poble de Salitja, en el municipi de Vilobí d''Onyar (Selva), situada en un bonic paratge prop del volcà de la Crosa de Sant Dalmai, al costat de Can Joher i can Bora (o Borra). És un edifici que forma part de l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9159025,2.7468242,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Fonts');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182260,'09010','Iglesia de Nuestra Señora de los Ángeles','religioso','religioso_osm','La iglesia de Nuestra Señora de los Ángeles de Miranda de Ebro (Burgos, Castilla y León, España) es un templo parroquial de culto católico construido para dar servicio religioso a los habitantes de la barriada mirandesa de Los Ángeles, separada del núcleo urbano por el río Bayas, en la carretera de Logroño. Su…',42.6839832,-2.9182856,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_los_Ángeles_(Miranda_de_Ebro)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182261,'42016','Mare de Déu de la Pineda','religioso','religioso_osm','Mare de Déu de la Pineda és una ermita del municipi de Vila-seca (Tarragonès) declarada bé cultural d''interès nacional.',41.0961351,1.1705283,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Pineda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182262,'25035','Mare de Déu de la Guardiola','religioso','religioso_osm','L''ermita de la Mare de Déu de la Guardiola és una església de la Sentiu de Sió (Noguera) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8032907,0.8834985,'https://ca.wikipedia.org/wiki/Ermita_de_la_Mare_de_Déu_de_la_Guardiola');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182263,'38018','Ermita de Nuestra Señora del Coromoto','religioso','religioso_osm','La ermita de Nuestra Señora de Coromoto está situada en el municipio de La Guancha en la isla de Tenerife (Islas Canarias, España). Dicho templo está consagrado a Nuestra Señora de Coromoto, patrona de Venezuela y se encuentra en el barrio de La Guancha de Abajo.',28.3790304,-16.6543556,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Coromoto_(La_Guancha)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182264,'38010','Iglesia Nuestra Señora del Carmen','religioso','religioso_osm','La parroquia matriz del Apóstol Santiago está ubicada en el casco de Realejo Alto, en el término municipal de Los Realejos, isla de Tenerife (Canarias, España). Su templo fue declarado Monumento Histórico Artístico de carácter Nacional por Real Decreto 598/1983 de 2 de febrero, (B.O.E. N.º 69).',28.387937,-16.5859954,'https://es.wikipedia.org/wiki/Parroquia_Matriz_del_Apóstol_Santiago');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182265,'08058','Mare de Déu de Montserrat','religioso','religioso_osm','La Mare de Déu de Montserrat és un temple al nucli urbà de Clariana (Alt Penedès) protegit com a bé cultural d''interès local. L''església de Clariana és un edifici aïllat de planta irregular.',41.2449759,1.618454,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montserrat_(Clariana)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182266,'38023','Parroquia de Nuestra Señora de Gracia','religioso','religioso_osm','La parroquia de Nuestra Señora de Gracia, antiguamente "ermita de Nuestra Señora de Gracia", es un templo situado en el barrio de Santa María de Gracia, en el término municipal de San Cristóbal de La Laguna, isla de Tenerife (Canarias, España). La parroquia y su advocación titular proviene de la época de la…',28.4750575,-16.3051857,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Gracia_(San_Cristóbal_de_La_Laguna)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182267,'90625','Mare de Déu de la Soledat','religioso','religioso_osm','Mare de Déu de la Soledat de Selvanera és una ermita de Selvanera, al municipi de Torrefeta i Florejacs (Segarra), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8257268,1.2750069,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Soledat_de_Selvanera');
