INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182269,'25219','Mare de Déu de Santesmasses','religioso','religioso_osm','Santes Masses de Sedó és una ermita de Sedó, al municipi de Torrefeta i Florejacs (Segarra) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7388031,1.2713687,'https://ca.wikipedia.org/wiki/Santes_Masses_de_Sedó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182270,'25219','Mare de Déu de la Llet','religioso','religioso_osm','Santa Maria de Castellmeià, també coneguda com la Mare de Déu de la Llet, forma part del conjunt de construccions disperses del llogarret de Castellmeià (entitat de població de Torrefeta i Florejacs), dit antigament Meià, situat a migdia del poble de Llor. És situada prop del castell que l''hi dona el nom.',41.7350682,1.3024904,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Castellmeià');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182271,'25062','Mare de Déu del castell de Sant Llorenç','religioso','religioso_osm','Mare de Déu del castell de Sant Llorenç és una església a l''est de les ruïnes del castell andalusí, en un carener que sobresurt de la serra de Sant Cristòfol a la riba dreta del Segre, i en terrenys de Sant Llorenç de Montgai.',41.8709412,0.8308737,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_castell_de_Sant_Llorenç');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182272,'27015','Mare de Déu de la Pertusa','religioso','religioso_osm','El Castell i capella de la Mare de Déu de la Pertusa és un conjunt arquitectònic de Corçà, al municipi d''Àger, inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya. Està situat a l''aresta de la roca que, des del collet de la Pertusa, s''endinsa damunt de la Noguera Ribagorçana, en el seu vessant esquerre, a…',42.0441807,0.6726165,'https://ca.wikipedia.org/wiki/Castell_i_capella_de_la_Mare_de_Déu_de_la_Pertusa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182273,'25245','Mare de Déu de Riupedrós','religioso','religioso_osm','El Santuari de la Mare de Déu de Riupedrós és una obra de Vilaller (Alta Ribagorça) protegida com a Bé Cultural d''Interès Local.',42.4840619,0.715485,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_Riupedrós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182274,'21029','Ermita de Nuestra Señora del Amparo','religioso','religioso_osm','La ermita de Nuestra Señora del Amparo de Cumbres Mayores (provincia de Huelva, España) fue construida en honor de san Sebastián, como agradecimiento por haber librado al pueblo de una epidemia, en el siglo XIV. En ella se da culto al titular hasta que en 1736 se traslada a esta ermita la Hermandad de Nuestra…',38.0652829,-6.6435411,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Amparo_(Cumbres_Mayores)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182275,'12042','Ermita de la Mare de Déu de l''Avellà','religioso','religioso_osm','L''Ermita de la Mare de Déu de l''Avellà de Catí, també coneguda com el Santuari de la Mare de Déu de la Font de l''Avellà, l''Ermitori de la Mare de Déu de la Misericòrdia de l''Avellà o simplement l''Ermita de l''Avellà, és una construcció religiosa a 5 quilòmetres de distància del municipi, en el llogaret de l''Avellà,…',40.5016445,0.0011156,'https://ca.wikipedia.org/wiki/Ermita_de_la_Mare_de_Déu_de_l''Avellà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182276,'29001','Ermita de la Virgen del Val','religioso','religioso_osm','La ermita de Nuestra Señora de El Val es un pequeño templo católico dedicado a la Virgen de El Val, patrona de Alcalá de Henares. Está situada al final de la avenida homónima.',40.4842109,-3.3400145,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Val_(Alcalá_de_Henares)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182277,'49275','Iglesia y Convento del Tránsito','religioso','religioso_osm','El convento del Corpus Christi, también llamado del Tránsito, de Clarisas Descalzas en Zamora (España) fue construido a principios del siglo XVI, como casa de doña Ana de Osorio y don Juan de Carbajal, siendo doña Ana de Osorio quien en su testamento ordenó donar «las casas de su morada y toda su hacienda, para que…',41.5008768,-5.7497257,'https://es.wikipedia.org/wiki/Convento_del_Corpus_Christi_(Zamora)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182278,'28079','Iglesia de Nuestra Señora de Montserrat','religioso','religioso_osm','La iglesia de Nuestra Señora de Montserrat es una iglesia de España de estilo barroco localizada en la calle de San Bernardo de Madrid.',40.4276725,-3.7067375,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Montserrat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182279,'38041','Ermita de Nuestra Señora de Los Ángeles','religioso','religioso_osm','La ermita de Nuestra Señora de los Ángeles y del Mar​ más conocida simplemente como Ermita de Nuestra Señora de los Ángeles, es un templo católico situado en el municipio de El Sauzal en el norte de la isla de Tenerife (Islas Canarias, España). El templo está dedicado a la Virgen de los Ángeles, la cual es la…',28.4741262,-16.439971,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_los_Ángeles_(El_Sauzal)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182280,'90024','Mare de Déu de Montserrat','religioso','religioso_osm','L''església de la Mare de Déu de Montserrat és un temple parroquial catòlic de la ciutat de Badalona. Està situada a la plaça de Cuba, al barri de Sant Crist de Can Cabanyes.',41.4512746,2.2374105,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_de_Montserrat_(Badalona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182281,'31230','Santuario de Codés','religioso','religioso_osm','Kodesko Ama Birjinaren santutegia Nafarroa Garaiko izen bereko mendatean (814 m) dagoen tenplu handia da, Kodesko mendilerroari izena ematen diona. XII. mendeko Andre Mariaren irudi bat dago barruan.',42.6237728,-2.3358329,'https://eu.wikipedia.org/wiki/Kodesko_santutegia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182282,'21055','Monasterio de la Rábida','religioso','religioso_osm','El monasterio de Santa María de La Rábida, comúnmente denominado monasterio de La Rábida, es en realidad un convento perteneciente a los franciscanos. Se encuentra en el término municipal de Palos de la Frontera, en la provincia andaluza de Huelva (Andalucía, España).​ Fue erigido entre los siglos XIV-XV. Destacan,…',37.2075606,-6.9261384,'http://www.monasteriodelarabida.com/','https://es.wikipedia.org/wiki/Monasterio_de_La_Rábida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182283,'24130','Iglesia de Nuestra Señora','religioso','religioso_osm','La iglesia de Nuestra Señora del Rosario es un templo católico situado desde 1987 en la localidad de Riaño, provincia de León, Castilla y León, España. Originalmente, la iglesia se encontraba en el pueblo de La Puerta, anegado por la construcción del embalse de Riaño.',42.9750768,-5.0123201,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Rosario_(Riaño)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182284,'24180','Monasterio de San Miguel de Escalada','religioso','religioso_osm','El monasterio de San Miguel de Escalada es un templo mozárabe ubicado cerca del pueblo homónimo, en el municipio de Gradefes, provincia de León, España. Situado en el Camino de Santiago, a 27 kilómetros de la ciudad de León, formaba parte de un antiguo monasterio del que hoy sólo se conserva el templo.',42.5712908,-5.3027667,'https://es.wikipedia.org/wiki/Monasterio_de_San_Miguel_de_Escalada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182285,'08206','Mare de Déu de Llinda','religioso','religioso_osm','La Mare de Déu de la Llinda és una església romànica del municipi d''Avinyonet del Penedès (Alt Penedès) protegida com a bé cultural d''interès local.',41.3844223,1.7563289,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Llinda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182286,'05038','Colegiata de San Martín de Tours','religioso','religioso_osm','La iglesia colegiata de San Martín es una iglesia católica situada en la localidad española de Bonilla de la Sierra, en la provincia de Ávila, comunidad autónoma de Castilla y León.',40.5308471,-5.2647918,'https://es.wikipedia.org/wiki/Iglesia_de_San_Martín_(Bonilla_de_la_Sierra)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182287,'30005','Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de la Asunción de la localidad de Alcantarilla (provincia de Murcia, España) es un templo católico de estilo neobarroco, construido a mediados del siglo XX.​ El alcalde Don Fulgencio Pérez Almagro proporciona en 1951, licencia para iniciar la construcción de la iglesia​ que…',37.9679278,-1.2205179,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Alcantarilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182288,'25190','Mare de Déu de la Pietat','religioso','religioso_osm','La Mare de Déu de la Pietat és l''antiga capella del castell d''Orcau. És romànica, i està profusament decorada a l''estil de les esglésies del segle xi, amb decoració llombarda.',42.1662512,0.9828465,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Pietat_del_Castell_d''Orcau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182289,'25523','Mare de Déu de Bonrepòs','religioso','religioso_osm','El santuari de la Mare de Déu de Bonrepòs està situat dins del terme de Gavet de la Conca. Pertanyia a l''antic terme de Sant Salvador de Toló, i és al vessant nord d''una carena que enllaça la Serra de Comiols amb el Montsec de Rúbies, a l''extrem nord de la serra denominada lo Tamany, prop del límit sud dels termes…',42.0386936,1.0520901,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Bonrepòs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182290,'25250','Mare de Déu del Puig de Meià','religioso','religioso_osm','La Mare de Déu del Puig de Meià o Sant Cristòfol del Puig de Meià és una església del municipi de Vilanova de Meià (Noguera) protegida com a bé cultural d''interès local. L''església és al cim del turó sobre el poble de Vilanova de Meià, on es conserven les restes del castell de Meià i d''altres construccions…',42.0028243,1.0182274,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Puig_de_Meià');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182291,'12073','Iglesia de la Natividad de Nuestra Señora','religioso','religioso_osm','La iglesia parroquial de la Natividad de Nuestra Señora de Ludiente, en la comarca del Alto Mijares, no debe confundirse con la Iglesia de la Natividad, que es el otro nombre con el que se conoce a la antigua Iglesia del pueblo, que es una iglesia fortificada del siglo XV y que está catalogada como Bien de Interés…',40.086381,-0.3721498,'https://es.wikipedia.org/wiki/Iglesia_de_la_Natividad_de_Nuestra_Señora_(Ludiente)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182292,'06025','Basílica de Santa Eulalia','religioso','religioso_osm','La basílica martirial de Santa Eulalia de Mérida es un edificio religioso que se encuentra en la ciudad de Mérida (España). Se considera un núcleo muy importante del nacimiento del cristianismo en la península ibérica.',38.9207559,-6.3419809,'https://es.wikipedia.org/wiki/Basílica_de_Santa_Eulalia_(Mérida)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182293,'17180','Mare de Déu d''Argimon','religioso','religioso_osm','La Mare de Déu d''Argimon és una petita capella romànica que fou afegida al castell d''Argimon segurament ja al segle x. La primera referència, el 1050, esmenta la fortificació propietat de Ponç Guerau de Cabrera; Ramon Berenguer III, comte de Barcelona, va cedir a Guerau Ponç, vescomte de Cabrera, el territori que…',41.8305749,2.6359214,'https://ca.wikipedia.org/wiki/Mare_de_Déu_d''Argimon');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182294,'22125','Iglesia Catedral de la Transfiguración del Señor','religioso','religioso_osm','La catedral de Huesca, construida en estilo gótico, fue iniciada a finales del siglo XIII y concluida a principios del siglo XVI. Originariamente estuvo dedicada a Jesús Nazareno pero es conocida popularmente como catedral de Santa María.​',42.1404457,-0.4081212,'https://es.wikipedia.org/wiki/Catedral_de_Santa_María_de_Huesca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182295,'22125','Basílica Real y Parroquial de San Lorenzo','religioso','religioso_osm','La iglesia-basílica de San Lorenzo es un templo barroco de la ciudad de Huesca construido entre 1608 y 1703. Fue edificada sobre un antiguo templo románico, que fue posteriormente ampliado en el siglo XIV en estilo gótico durante el reinado de Jaime II de Aragón.',42.136907,-0.4059896,'https://es.wikipedia.org/wiki/Iglesia_de_San_Lorenzo_(Huesca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182296,'15052','Santuario de Nosa Señora da Barca','religioso','religioso_osm','O Santuario da Virxe da Barca é un templo católico situado no concello de Muxía. A súa situación na punta da península onde se asenta Muxía, fronte do mar, os ritos relixiosos asociados ao mesmo e a súa arquitectura e imaxinería fan del un dos máis singulares de Galicia.',43.1120047,-9.2196382,'https://gl.wikipedia.org/wiki/Santuario_da_Virxe_da_Barca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182297,'30043','Basílica de la Purísima','religioso','religioso_osm','La basílica de la Purísima Concepción es el templo principal de la ciudad de Yecla, en la Región de Murcia (España). Tiene rango de arciprestal y está dedicado a la Purísima Concepción de Nuestra Señora, patrona de la localidad (popularmente conocida como Virgen del Castillo).',38.6133679,-1.1153069,'https://basilicadelapurisima.com/','https://es.wikipedia.org/wiki/Basílica_de_la_Purísima_(Yecla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182298,'28160','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es una iglesia parroquial católica que se encuentra situada en el municipio madrileño de Valdemorillo. Es el templo principal de la parroquia de Valdemorillo.',40.5022318,-4.0668674,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Valdemorillo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182299,'17095','Mare de Déu de les Alegries','religioso','religioso_osm','El Santuari de la Mare de Déu de les Alegries va ser la primera parròquia de la vila de Lloret de Mar. Va ser parròquia de la vila des que va ser consagrada, el 1079, fins al 1522, quan es va inaugurar una nova parròquia a prop de la platja.',41.7175424,2.8295507,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Alegries');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182300,'09328','Ermita de la Virgen de la Oliva','religioso','religioso_osm','La ermita de Nuestra Señora de la Oliva se encuentra en la localidad española de Escóbados de Abajo, en el municipio de Los Altos situado en la provincia de Burgos, Castilla y León.',42.7418209,-3.5810503,'https://turismoburgos.org/ermita-de-la-virgen-de-la-oliva-de-escobados-de-abajo/','https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_la_Oliva_(Escóbados_de_Abajo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182301,'06025','Concatedral de Santa María la Mayor','religioso','religioso_osm','La Santa Iglesia Concatedral Metropolitana de Santa María la Mayor es un templo católico de Mérida que se levanta en pleno corazón histórico de la capital extremeña. Junto a la Catedral de Badajoz, es sede de la archidiócesis de Mérida-Badajoz.',38.9165654,-6.347181,'https://es.wikipedia.org/wiki/Concatedral_de_Mérida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182302,'25043','Nativitat de la Mare de Déu de Durro','religioso','religioso_osm','La Nativitat de la Mare de Déu és l''església parroquial romànica del poble de Durro que va ser declarada monument historicoartístic l''any 1980. Pertany al terme municipal de la Vall de Boí, dins de l''antic terme de Durro, sempre a l''Alta Ribagorça.',42.4981787,0.8206828,'https://ca.wikipedia.org/wiki/La_Nativitat_de_Durro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182303,'50037','Santuario de Nuestra Señora de Angosto','religioso','religioso_osm','Nuestra Señora de Angosto o Virgen de Angosto es una advocación mariana de la religión católica. Tiene su origen en el lugar de Angosto (Álava) donde según la tradición el pastor Hernando Martín encontró una imagen de la Virgen María flotando en el río después de una riada.',42.8464885,-3.0703382,'https://www.valdegovia.com/ver_angosto.asp','https://es.wikipedia.org/wiki/Virgen_de_Angosto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182304,'08113','Mare de Déu del Remei','religioso','religioso_osm','La Capella del Remei és una petita capella barroca del primer quart del s.XVII que es troba al municipi de Manresa (Bages). Està protegida com a bé cultural d''interès local.',41.7270961,1.8317041,'https://ca.wikipedia.org/wiki/Capella_del_Remei_(Manresa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182305,'17192','Mare de Déu del Catllar','religioso','religioso_osm','L''ermita de Santa Maria del Catllar (o Nostra Senyora del Catllar) és una capella romànica d''una sola nau amb absis i volta de canó situada al municipi de Vilallonga de Ter (Ripollès), en un turó on hi hagué abans el castell del Catllar o «Castellario», del qual no se''n conserven restes, i que donà nom al llinatge…',42.3587276,2.2920144,'https://ca.wikipedia.org/wiki/Ermita_de_Santa_Maria_del_Catllar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182306,'50288','Iglesia de Nuestra Señora de los Ángeles','religioso','religioso_osm','La iglesia de Nuestra Señora del Coro de los Ángeles en el barrio rural de Peñaflor de Gállego de Zaragoza (España) es una iglesia mudéjar de mediados del siglo XVI con nave única de cuatro tramos, cubierta con bóvedas de crucería sencilla, y ábside poligonal. En el siglo XX esta construcción sufrió una reforma en…',41.7605719,-0.7984068,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_los_Ángeles_(Zaragoza)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182307,'40195','Iglesia de Nuestra Señora de La Peña','religioso','religioso_osm','La iglesia o santuario de la Virgen de la Peña es un templo de la localidad española de Sepúlveda, en la provincia de Segovia.',41.3021104,-3.750525,'https://es.wikipedia.org/wiki/Iglesia_de_la_Virgen_de_la_Peña_(Sepúlveda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182308,'90488','Basílica de Santa Teresa','religioso','religioso_osm','La basílica de Santa Teresa de Jesús es un templo religioso de la villa ducal de Alba de Tormes, (Salamanca).',40.8262529,-5.5153864,'https://es.wikipedia.org/wiki/Basílica_de_Santa_Teresa_(Alba_de_Tormes)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182309,'35001','Colegiata de San Miguel','religioso','religioso_osm','Para ver otras colegiatas bajo la misma advocación, véase Colegiata de San Miguel. La colegiata de san Miguel Arcángel es un templo parroquial de estilo predominantemente gótico, situado en el perímetro de la plaza de España de Aguilar de Campoo, provincia de Palencia, comunidad de Castilla y León, España.',42.792638,-4.2596161,'https://es.wikipedia.org/wiki/Colegiata_de_San_Miguel_(Aguilar_de_Campoo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182310,'20902','Convento de las Brígidas','religioso','religioso_osm','El convento de Las Brígidas en Lasarte-Oria (provincia de Guipúzcoa, España) queda constituido por la capilla y dos cuerpos en línea recta NE a SO. En estos cuerpos de planta baja y una altura, se instalaron las celdas y los servicios. El lado NE se cierra con otro pabellón, mientras que en el otro extremo se sitúa…',43.2679742,-2.0209928,'https://es.wikipedia.org/wiki/Convento_de_Las_Brígidas_(Lasarte-Oria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182311,'31135','Basílica de San Francisco Javier','religioso','religioso_osm','La Basílica de San Francisco Javier (Javier, Navarra) es una iglesia adyacente al Castillo de Javier realizada a finales del siglo XIX y principios del XX en estilo ecléctico sobre parte del palacio donde vivió la familia Jaso-Azpilicueta.',42.5941934,-1.2160592,'https://www.castillodejavier.es/basilica','https://es.wikipedia.org/wiki/Basílica_de_Javier');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182312,'43131','Ermita Mare de Déu de Berà','religioso','religioso_osm','La Mare de Déu de Berà és una ermita barroca de Roda de Berà (Tarragonès) protegida com a Bé Cultural d''Interès Local.',41.1666338,1.4723198,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Berà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182313,'25126','Mare de Déu de Biuse','religioso','religioso_osm','La Mare de Déu de Biuse és una ermita de l''antic poble de Biuse, ara Bordes de Biuse, en el terme municipal de Llavorsí, a la comarca del Pallars Sobirà. Està situada a força alçada a l''esquerra de la Noguera Pallaresa, al nord-oest de la Torre de Biuse, restes del Castell de Biuse.',42.4755861,1.2128902,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Biuse');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182314,'08903','Mare de Déu de les Esposes','religioso','religioso_osm','Santa Maria de les Esposes és un santuari que està situat al terme municipal de Sant Julià de Cerdanyola, a l''Alt Berguedà. Està inventariat com a patrimoni immoble pel catàleg de patrimoni de la Generalitat de Catalunya amb el número de fitxa IPAC-3423.',42.2266436,1.8852372,'https://ca.wikipedia.org/wiki/Santa_Maria_de_les_Esposes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182315,'44216','Catedral de Santa María','religioso','religioso_osm','La catedral de Santa María de Mediavilla de Teruel es una de las construcciones más importantes del mudéjar en España, y una de las dos únicas catedrales españolas, junto con la de Tarazona, construida en este estilo. Actualmente, la catedral está considerada bien de interés cultural (BIC).',40.3438549,-1.1072595,'https://es.wikipedia.org/wiki/Catedral_de_Teruel');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182316,'08026','Catedral de Vic','religioso','religioso_osm','La catedral de Sant Pere Apòstol o catedral de Vic, enclavada al centre del recinte històric de la ciutat, és la seu de la diòcesi de Vic. Presenta una mescla d''estils que van des del romànic fins al neoclàssic.',41.9280307,2.2556151,'https://ca.wikipedia.org/wiki/Catedral_de_Vic');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182317,'09224','Ermita de Nuestra Señora del Valle','religioso','religioso_osm','La ermita de Nuestra Señora del Valle es un templo religioso de estilo románico ojival de influencia bizantina​ en España. Localizado en el municipio burgalés de Monasterio de Rodilla (comarca de La Bureba), se levanta sobre las ruinas del desaparecido monasterio que lo da nombre.​​ Se trata de un cenobio…',42.4594304,-3.4844869,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Valle');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182318,'38052','Santuario del Santo Hermano Pedro','religioso','religioso_osm','El santuario del Santo Hermano Pedro es un templo de peregrinación que se encuentra en el municipio de Vilaflor, en el sur de la isla de Tenerife (Islas Canarias, España). El Santuario está dedicado a San Pedro de San José Betancur, Primer Santo Canario.',28.1601286,-16.6367067,'https://es.wikipedia.org/wiki/Santuario_del_Santo_Hermano_Pedro_(Vilaflor)');
