INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182320,'09091','Excolegiata de Santa María del Manzano','religioso','religioso_osm','La colegiata de Santa María del Manzano de Castrojeriz es un templo católico situado en el municipio de Castrojeriz, en la provincia de Burgos. El edificio actual comenzó a construirse en el año 1214, por voluntad de la reina Berenguela de Castilla, hija de Alfonso VIII de Castilla y madre de Fernando III el Santo.',42.2926979,-4.1278442,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Manzano_(Castrojeriz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182321,'32002','Real Colegiata de Santa María la Mayor','religioso','religioso_osm','La Real Colegiata de Santa María La Mayor es una colegiata situada en Antequera, en la provincia de Málaga, España. Fue fundada por iniciativa del obispo Diego Ramírez de Villaescusa, al cargo por entonces la diócesis de Málaga; quien, considerando el numeroso vecindario que había alcanzado la ciudad obtiene del…',37.0144522,-4.5561755,'https://es.wikipedia.org/wiki/Real_Colegiata_de_Santa_María_la_Mayor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182322,'34022','Ermita de Nuestra Señora de Revilla','religioso','religioso_osm','La ermita de Nuestra Señora de Revilla es una Ermita patronal católica dedicada a la Virgen de Revilla. Está ubicada en la localidad de Baltanás (provincia de Palencia, Castilla y León, España).',41.934678,-4.248928,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Revilla_(Baltanás)');
