INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182327,'15043','Igrexa do Mosteiro de Santiago de Mens','religioso','religioso_osm','A igrexa de Santiago de Mens é un edificio relixioso, parte dun antigo mosteiro, con significativos restos románicos. Atópase na parroquia de Mens, no concello de Malpica de Bergantiños, na comarca coruñesa de Bergantiños.',43.2977204,-8.8681858,'https://gl.wikipedia.org/wiki/Mosteiro_de_Santiago_de_Mens');
