INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182336,'08003','Mare de Déu del Carme','religioso','religioso_osm','L''església del Carme és un conjunt arquitectònic del barri del Raval de Barcelona, catalogat com a bé cultural d''interès local. L''accés principal es troba al carrer del Bisbe Laguarda, mentre que el del centre parroquial es produeix des del de Sant Antoni Abat.',41.3796006,2.1650243,'https://ca.wikipedia.org/wiki/Església_del_Carme_de_Barcelona');
