INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182342,'38023','Convento de Santa Catalina de Siena','religioso','religioso_osm','El convento o monasterio de Santa Catalina de Siena está situado en San Cristóbal de La Laguna, ciudad de la isla de Tenerife en la comunidad autónoma de las Islas Canarias (España).',28.4877355,-16.3143414,'https://es.wikipedia.org/wiki/Convento_de_Santa_Catalina_de_Siena_(San_Cristóbal_de_La_Laguna)');
