INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182345,'25549','Mare de Déu de les Ares','religioso','religioso_osm','La Mare de Déu de les Ares és un santuari del terme municipal d''Alt Àneu, a la comarca del Pallars Sobirà. Pertanyia a l''antic terme de la Mancomunitat dels Quatre Pobles.',42.6477425,1.0073309,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Ares');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182346,'35026','Basílica de San Juan Bautista','religioso','religioso_osm','La Basílica de San Juan Bautista y Santuario del Santísimo Cristo de Telde se encuentra en el municipio de Telde, en la isla de Gran Canaria (España). Está ubicada en la plaza de san Juan, en uno de los núcleos fundacionales de la ciudad de Telde, próxima al histórico barrio de san Francisco, y en frente del…',28.0032689,-15.4138423,'https://es.wikipedia.org/wiki/Basílica_de_San_Juan_Bautista_(Telde)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182347,'42162','Iglesia de Nuestra Señora del Rivero','religioso','religioso_osm','La iglesia de Nuestra Señora del Rivero, de la Virgen del Rivero o, simplemente, el Rivero, es obra románica del siglo XII, se localiza dentro del núcleo urbano de San Esteban de Gormaz (Provincia de Soria, España), sobre un altozano, en un espléndido emplazamiento, rodeada por el antiguo cementerio, totalmente…',41.5752188,-3.2084328,'https://es.wikipedia.org/wiki/Iglesia_de_la_Virgen_del_Rivero');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182348,'41011','Basílica de Nuestra Señora de los Milagros','religioso','religioso_osm','La basílica de Nuestra Señora de los Milagros es un templo religioso de culto católico y puesto bajo la advocación mariana de la Virgen de los Milagros sito en la localidad española de Ágreda, en la provincia de Soria, comunidad autónoma de Castilla y León. Se trata de un templo de grandes proporciones construido…',41.8553268,-1.9192593,'https://es.wikipedia.org/wiki/Basílica_de_Nuestra_Señora_de_los_Milagros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182349,'41011','Iglesia de Nuestra Señora de Magaña','religioso','religioso_osm','La iglesia de la Virgen de Magaña está situada en la localidad de Ágreda, en la provincia de Soria, comunidad autónoma de Castilla y León, en España.',41.8559387,-1.9196794,'https://es.wikipedia.org/wiki/Iglesia_de_la_Virgen_de_Magaña_(Ágreda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182350,'41011','Iglesia de Nuestra Señora de Yanguas','religioso','religioso_osm','Las ruinas de la iglesia de Nuestra Señora de Yanguas forman parte de una iglesia de estilo gótico tardío localizada en la plaza de Castejón en la villa de Ágreda, provincia de Soria, Castilla y León, España. De esta iglesia, construida en el siglo XVI se conserva el ábside cubierto con bóveda de crucería.',41.8537429,-1.9200685,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Yanguas_(Ágreda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182351,'41011','Iglesia de Nuestra Señora de la Peña','religioso','religioso_osm','La iglesia de la Virgen de la Peña en la villa de Ágreda (provincia de Soria, Castilla y León, España) es un templo católico que data del siglo XII, el más antiguo de la localidad.',41.853802,-1.9192421,'https://es.wikipedia.org/wiki/Iglesia_de_la_Virgen_de_la_Peña_(Ágreda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182352,'28079','Parroquia Concepción de Nuestra Señora','religioso','religioso_osm','La basílica de la Concepción de Nuestra Señora es un templo católico de estilo neogótico​​ ubicado en la ciudad española de Madrid.',40.4246073,-3.6824533,'https://es.wikipedia.org/wiki/Basílica_de_la_Concepción_de_Nuestra_Señora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182353,'27015','Mare de Déu del Remei','religioso','religioso_osm','Mare de Déu del Remei d''Oroners és un temple troglodític del despoblat d''Oroners al municipi de Camarasa (Noguera) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya. Està adossat pel costat nord a l''escarpat rocós de la Penya de la Mare de Déu, que li fa de mur, a llevant de la Serra de Montclús i a la…',41.9914197,0.8390669,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Remei_d''Oroners');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182354,'40194','Santuario de la Fuencisla','religioso','religioso_osm','El Santuario de Nuestra Señora de la Fuencisla es una iglesia católica ubicada en las afueras de la ciudad española de Segovia, que alberga a la patrona de la ciudad, la Virgen de la Fuencisla.',40.9566515,-4.1353553,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_la_Fuencisla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182355,'47139','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Santa María de la Asunción es una iglesia localizada en el municipio español de Rueda, en la provincia de Valladolid, comunidad autónoma de Castilla y León.',41.413583,-4.9607181,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Rueda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182356,'25207','Catedral de Solsona','religioso','religioso_osm','La catedral de Santa Maria de Solsona és un complex d''edificis que daten des del final del segle xii fins al xviii, d''estils romànic, gòtic i barroc, situat a la capital del Solsonès. Està declarada bé cultural d''interès nacional.',41.9943676,1.5194488,'https://ca.wikipedia.org/wiki/Catedral_de_Solsona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182357,'34155','Monasterio de Santa Cruz de Ribas','religioso','religioso_osm','El monasterio de Santa Cruz de Ribas, también llamado de Santa Cruz de la Zarza, es un antiguo cenobio de la orden Premonstratense y de estilo cisterciense-protogótico, ya exclaustrado y actualmente en proceso de restauración, situado en la vega baja del río Carrión, entre las poblaciones de Ribas de Campos y…',42.1430916,-4.5004619,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_Cruz_(Ribas_de_Campos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182358,'08206','Monestir de Sant Sebastià dels Gorgs','religioso','religioso_osm','El monestir de Sant Sebastià dels Gorgs és un antic cenobi benedictí que es troba a la localitat de Sant Sebastià dels Gorgs al municipi d''Avinyonet del Penedès. L''any 2000 la Generalitat de Catalunya el va declarar bé cultural d''interès nacional.',41.380646,1.765767,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Sebastià_dels_Gorgs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182359,'28079','Iglesia de Nuestra Señora de la Paz','religioso','religioso_osm','La iglesia de Nuestra Señora de la Paz es un templo católico de estilo neogótico ubicado en Madrid (España). Está situada en la calle Doctor Esquerdo esquina con O''Donell, relativamente cercana al Hospital Gregorio Marañón.',40.420989,-3.6694505,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Paz_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182360,'42120','Ermita de la Virgen del Val','religioso','religioso_osm','La ermita de la Virgen del Val se encuentra situada a unos 200 metros al noroeste de la localidad de Pedro, a los pies de la sierra de Grado, en el término municipal de Montejo de Tiermes, al sur de la provincia de Soria (España). La ermita consta de una sola nave con ábside rectangular y pórtico al sur, formado…',41.3190789,-3.1943613,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_del_Val_(Pedro)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182361,'49224','Monasterio de San Martín de Castañeda','religioso','religioso_osm','El monasterio de San Martín de Castañeda es un monumento histórico-artístico nacional desde 1931 que se encuentra situado en la localidad de San Martín de Castañeda del municipio de Galende, en la comarca de Sanabria, provincia de Zamora (España). Como monumento artístico es un exquisito ejemplo más del románico…',42.1351849,-6.7199573,'https://es.wikipedia.org/wiki/Monasterio_de_San_Martín_de_Castañeda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182362,'30036','Iglesia de Nuestra Señora del Loreto','religioso','religioso_osm','La parroquia castrense de Nuestra Señora de Loreto, también conocida como iglesia de Nuestra Señora de Loreto es un templo católico situado en Santiago de la Ribera (San Javier, Región de Murcia, España). Ésta se encuentra en la Calle de la Iglesia, justo al lado del Centro de Educación Infantil y Primaria Nuestra Sra.',37.8130036,-0.7979195,'https://es.wikipedia.org/wiki/Parroquia_castrense_de_Nuestra_Señora_de_Loreto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182363,'03902','Nuestra Señora del Pilar','religioso','religioso_osm','La Iglesia de Nuestra Señora del Pilar, es un templo religioso de culto católico bajo la advocación de Nuestra Señora Santa Pilar. Se encuentra ubicado en el núcleo urbano de Pilar de la Horadada, al sur de la Comunidad Valenciana, y constituye la única iglesia católica de este.',37.865204,-0.7935002,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Pilar_(Pilar_de_la_Horadada)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182364,'45114','Iglesia Parroquial de Nuestra Señora de la Nava','religioso','religioso_osm','La iglesia parroquial de Santa María de la Nava es un templo católico situado en la localidad española de Navamorcuende, perteneciente a la provincia de Toledo, en la comunidad autónoma de Castilla-La Mancha.',40.1577283,-4.7847503,'https://es.wikipedia.org/wiki/Iglesia_de_Santa_María_de_la_Nava');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182365,'37018','Monasterio de Nuestra Señora de Porta Coeli','religioso','religioso_osm','El monasterio de monjas franciscanas de la Tercera Orden Regular de El Zarzoso se encuentra enclavado en la vertiente sur de una de las estribaciones montañosas del norte de la sierra de Francia, en el término municipal español de El Cabaco, en la provincia de Salamanca.',40.606624,-6.1280308,'https://es.wikipedia.org/wiki/Convento_de_El_Zarzoso');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182366,'17077','Mare de Deu del Camp','religioso','religioso_osm','Mare de Déu del Camp és un edifici religiós del municipi de Garriguella comarca de l''Alt Empordà inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3517923,3.066212,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Camp_(Garriguella)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182367,'03005','Basílica Nuestra Señora del Socorro','religioso','religioso_osm','La Basílica de Nostra Senyora del Socors se situa en la localitat valenciana d''Asp en la comarca del Vinalopó Mitjà. Un magnífic edifici d''estil Barroc Valencià que va començar la seua construcció en 1650 i que per a molts és "la joia de la diòcesi d''Oriola".',38.3460015,-0.7682238,'https://ca.wikipedia.org/wiki/Basílica_de_Nostra_Senyora_del_Socors');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182368,'45166','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo católico del siglo XVI que combina los estilos gótico y renacentista. Está situado en el municipio español de Tembleque, en la provincia de Toledo.',39.6970224,-3.5031032,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Tembleque)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182369,'36011','Convento de Santa Clara','religioso','religioso_osm','O convento de Santa Clara é un antigo convento da Orde das Clarisas, situado no centro da cidade de Pontevedra, na rúa Santa Clara, xunto á antiga Porta de Santa Clara da antiga muralla.',42.4321989,-8.6401639,'https://gl.wikipedia.org/wiki/Convento_de_Santa_Clara_de_Pontevedra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182370,'43170','Monestir de Santes Creus','religioso','religioso_osm','El Monestir de Santes Creus o Reial Monestir de Santa Maria de Santes Creus és una de les joies de l''art medieval català i està situat al poble de Santes Creus, Aiguamúrcia (Alt Camp, Tarragona). Actualment és l''únic monestir de la Ruta del Cister que no té vida monàstica.',41.346258,1.3643819,'https://patrimoni.gencat.cat/ca/monuments/monumentos/reial-monestir-de-santes-creus','https://ca.wikipedia.org/wiki/Reial_Monestir_de_Santa_Maria_de_Santes_Creus');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182371,'48912','Ermita de Nuestra Señora de la Guía','religioso','religioso_osm','Gidako Ama Birjina baseliza Alonsotegiko Arbuio auzoan dagoen baseliza da. 1933an eraiki zuen Justino Basterrak Rica enpresarako langileentzat Oinplano angeluzuzena du, eta burua zuzena du.',43.2355096,-3.009975,'https://eu.wikipedia.org/wiki/Gidako_Ama_Birjina_baseliza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182372,'46252','Iglesia de Nuestra Señora de los Ángeles','religioso','religioso_osm','L''església parroquial Nostra Senyora dels Àngels de Vallanca es troba entre les més antigues del Racó d''Ademús, documentant-se la seua existència ja en el primer terç del segle xiii. No obstant això, el temple que avui podem contemplar, que va venir a substituir l''antic de l''Edat Mitjana, va prendre el seu aspecte…',40.0631732,-1.3387301,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_dels_Àngels_de_Vallanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182373,'36011','Mosteiro de San Salvador de Lérez','religioso','religioso_osm','O mosteiro de San Salvador de Lérez foi un convento construído na Idade Media na parroquia de Lérez, en Pontevedra. Nel celébrase cada 11 de xullo (día de san Bieito) a romaría de San Benitiño de Lérez.',42.4492707,-8.6321733,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Salvador_de_Lérez');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182374,'43089','Mare de Déu de Montserrat','religioso','religioso_osm','El santuari de la Mare de Déu de Montserrat de Montferri és un monument protegit com a bé cultural d''interès local del municipi de Montferri (Alt Camp). De propietat municipal, està adscrit a la parròquia de Sant Bartomeu de Montferri.',41.2686353,1.3696985,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montserrat_de_Montferri');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182375,'25167','Monestir de Cellers','religioso','religioso_osm','Sant Celdoni i Sant Ermenter de Cellers més conegut a la comarca com Monestir de Cellers és un monument del municipi de Torà (Solsonès) declarat bé cultural d''interès nacional.',41.8152473,1.4879951,'https://ca.wikipedia.org/wiki/Sant_Celdoni_i_Sant_Ermenter_de_Cellers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182376,'35016','Parroquia Nuestra Señora de La Luz','religioso','religioso_osm','La Parroquia de Nuestra Señora de la Luz se ubica en el barrio de La Isleta de la ciudad de Las Palmas de Gran Canaria (España). Está consagrada a Nuestra Señora la Virgen de la Luz (Alcaldesa Honoraria de la ciudad y patrona del Puerto de la Luz).',28.1486668,-15.4264391,'https://es.wikipedia.org/wiki/Parroquia_de_Nuestra_Señora_de_la_Luz_(La_Isleta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182377,'17164','Mare de Déu del Pedró','religioso','religioso_osm','El Santuari de la Mare de Déu del Padró és una església de Sant Hilari Sacalm (Selva) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8977948,2.5654573,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_del_Padró');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182378,'24901','Colegiata de Santa María de Arbas','religioso','religioso_osm','La colegiata de Santa María es una iglesia que se encuentra situada al norte de León (España), en Arbas del Puerto, en la vertiente sur del puerto de Pajares, a tan solo un kilómetro del Alto de Pajares. Pertenece al municipio de Villamanín.',42.9932858,-5.7446107,'https://es.wikipedia.org/wiki/Colegiata_de_Santa_María_de_Arbas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182379,'28079','Iglesia de Nuestra Señora de las Maravillas','religioso','religioso_osm','La iglesia de Nuestra Señora de las Maravillas es un templo de culto católico en Madrid, España.​ Con pórtico a la calle de la Palma, un costado a la calle del Dos de Mayo, y la parte más antigua del recinto del monasterio de san Antón dando a la plaza del Dos de Mayo.​',40.4265446,-3.7043675,'https://es.wikipedia.org/wiki/Iglesia_de_los_Santos_Justo_y_Pastor_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182380,'90061','Mare de Déu de Carrànima','religioso','religioso_osm','La Mare de Déu de Carrànima o de Carràmia és un santuari situat a 1.624 m d''altitud, al cim de la serra de Carrànima, que separa les valls d''accés a Bóixols i del riu d''Abella. Pertany al terme municipal d''Abella de la Conca, del Pallars Jussà.',42.1661577,1.1433573,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Carrànima');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182381,'08045','Santuari de la Mare de Déu dels Tossals','religioso','religioso_osm','El Santuari dels Tossals és una església abandonada del municipi de Capolat a la comarca del Berguedà inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. Situat enmig de la vall de Capolat i el coll de Joanet, el santuari dels tossals ja existia al segle xiii.',42.0885202,1.7538714,'https://ca.wikipedia.org/wiki/Santuari_dels_Tossals');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182382,'08050','Mare de Déu de la Mata','religioso','religioso_osm','Mare de Déu de la Mata és una església de Castellar del Riu (Berguedà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.1284677,1.7126963,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Mata');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182383,'43082','Mare de Déu de les Pinyeres','religioso','religioso_osm','La Mare de Déu de les Pinyeres és una ermita romànica reconstruïda en època barroca situada als termes municipals del Masroig i Bellmunt del Priorat (Priorat) protegida com a bé cultural d''interès local. Tots dos municipis hi fan romeria el dia de la festivitat, el dissabte després de Dilluns de Pasqua.',41.1443468,0.7297021,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Pinyeres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182384,'31141','iglesia de la Natividad de Nuestra Señora','religioso','religioso_osm','La iglesia de la Natividad de Nuestra Señora es un edificio situado en el concejo español de Bernedo, en la provincia de Álava.',42.6268499,-2.4980722,'https://es.wikipedia.org/wiki/Iglesia_de_la_Natividad_de_Nuestra_Señora_(Bernedo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182385,'33024','Basílica del Sagrado Corazón','religioso','religioso_osm','La Basílica-Santuario del Sagrado Corazón de Jesús en un templo de la ciudad asturiana de Gijón (España) conocida popularmente como La Iglesiona y situada frente al Real Instituto Jovellanos. Fue construida en 1918 bajo estilo neogótico y modernista, y fue utilizada como prisión​ durante la Guerra Civil española.',43.5417519,-5.6625438,'https://es.wikipedia.org/wiki/Basílica_del_Sagrado_Corazón_(Gijón)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182386,'46250','Convento de Santa Clara','religioso','religioso_osm','El convento de Santa Clara de Valencia se encuentra ubicado en la avenida Pérez Galdós número 119 de la ciudad de Valencia, España. Es un convento de clausura fundado en el 1911 y habitado por monjas de la Orden de las Clarisas coletinas.',39.4724859,-0.3944509,'https://es.wikipedia.org/wiki/Convento_de_Santa_Clara_(Valencia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182387,'47001','Convento de Santa Clara','religioso','religioso_osm','Santa Klara komentua Balmasedan dagoen monasterio ohia da, klaratarrek erabilia. Egun, jatetxea da.',43.192768,-3.1975726,'https://eu.wikipedia.org/wiki/Santa_Klara_komentua_(Balmaseda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182388,'51025','Iglesia de Nuestra Señora de las Vacas','religioso','religioso_osm','La ermita de Nuestra Señora de las Vacas es un edificio religioso de la ciudad española de Ávila, en Castilla y León. Está situada en la plaza de las Vacas, zona sur, extramuros de la ciudad,​ y cuenta con la categoría de Bien de Interés Cultural, desde el 9 de abril de 1992.​​ Según algunos autores su origen…',40.6526202,-4.6934785,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_las_Vacas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182389,'40046','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de la Asunción es una iglesia de la localidad española de Castillejo de Mesleón, en la provincia de Segovia. Cuenta con el estatus de Bien de Interés Cultural.',41.283945,-3.6031262,'https://es.wikipedia.org/wiki/Iglesia_de_la_Asunción_(Castillejo_de_Mesleón)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182390,'13009','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de la Asunción es un edificio arquitectónico, predominantemente de estilo renacentista castellano, ubicado en la localidad española de Manzanares, en la provincia de Ciudad Real.',38.9965525,-3.3725142,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Manzanares)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182391,'28079','Basílica de Jesús de Medinaceli','religioso','religioso_osm','La basílica de Nuestro Padre Jesús de Medinaceli es una iglesia de culto católico que se encuentra en la plaza de Jesús de Madrid (España). El templo se levanta sobre el antiguo Convento de trinitarios descalzos de Nuestra Señora de la Encarnación.',40.4143228,-3.6953322,'https://es.wikipedia.org/wiki/Basílica_de_Jesús_de_Medinaceli');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182392,'46179','Iglesia Parroquial de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de la Asunción de Nuestra Señora de Navarrés (provincia de Valencia, España) es una iglesia católica reconstruida en el siglo XVIII, de estilo neoclásico y con ornamentación rococó. Esta construcción se encuentra situada en la falda de la montaña, en la parte alta del pueblo, salvando un gran desnivel en…',39.1014375,-0.6931291,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Navarrés)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182393,'40025','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo católico de Duratón (Segovia, España), situado en la orilla derecha del río Duratón. Es una iglesia románica porticada.​ La Iglesia románica porticada de Nuestra Señora de la Asunción data de 1203, se encuadra dentro del denominado taller de Duratón.',41.2881547,-3.6823398,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Duratón)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182394,'29001','Ermita del Cristo de los Doctrinos','religioso','religioso_osm','La Ermita Universitaria del Santísimo Cristo Universitario de los Doctrinos de Alcalá de Henares es arquitectura popular, del más puro barroco castellano. Posee una recoleta capilla, en la que se puede contemplar la talla del Cristo Universitario de los Doctrinos, obra manierista del jesuita Domingo Beltrán y la…',40.4819156,-3.3601459,'https://es.wikipedia.org/wiki/Ermita_del_Cristo_de_los_Doctrinos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182395,'12140','Iglesia Nuestra Señora de Gracia','religioso','religioso_osm','La iglesia parroquial de la Virgen de Gracia y al Arcángel San Miguel de Viver (Provincia de Castellón, España) está situada en la Plaza del Ángel y fue construida a principios del siglo XVII. Si bien cuenta con ampliaciones y reformas posteriores.',39.9211825,-0.5971863,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Gracia_(Viver)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182396,'37011','Catedral Nueva','religioso','religioso_osm','La catedral de la Asunción de la Virgen, llamada popularmente catedral Nueva, es, junto con la Vieja, una de las dos catedrales de la ciudad de Salamanca, en España. Como tal, es la sede de la diócesis de Salamanca.',40.9606168,-5.6660423,'https://es.wikipedia.org/wiki/Catedral_Nueva_de_Salamanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182397,'25171','Mare de Déu de la Ribera','religioso','religioso_osm','La Mare de Déu de la Ribera és una església barroca de la Pobla de Segur (Pallars Jussà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.2476491,0.9681087,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Ribera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182398,'28161','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de la Asunción es el principal edificio religioso del municipio de Valdemoro, situado al sur de la Comunidad de Madrid (España). Se trata de una construcción de estilo barroco que constituye el edificio más representativo del conjunto monumental de la localidad y un destacado…',40.1887648,-3.6791272,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Valdemoro)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182399,'35013','Iglesia Nuestra Señora de Candelaria','religioso','religioso_osm','Templo de larga tradición devocional en Moya (Las Palmas).',28.1108007,-15.58416,'https://en.wikipedia.org/wiki/Iglesia_de_la_Virgen_de_la_Candelaria_(Moya)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182400,'47178','Ermita de Nuestra Señora de la Anunciada','religioso','religioso_osm','La iglesia de Nuestra Señora de la Anunciada, ubicada en las inmediaciones del municipio de Urueña, provincia de Valladolid, Castilla y León, es un destacado ejemplo del arte románico en España. Este edificio, singular por su emplazamiento y sus características arquitectónicas, combina influencias de diferentes…',41.717406,-5.1983097,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Anunciada_(Urueña)');
