INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182402,'52001','Basílica del Cristo Rey','religioso','religioso_osm','La capilla del Cristo Rey es un Bien de Interés Cultural​ que se ubica en la calle comandante médico Fidel Pagés junto al Hospital Universitario de Melilla en el Ensanche Modernista en la ciudad española de Melilla.​',35.2805361,-2.9427142,'https://es.wikipedia.org/wiki/Capilla_del_Cristo_Rey');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182403,'30019','Convento de San Joaquín y San Pascual','religioso','religioso_osm','El convento de Franciscanos Descalzos de San Joaquín y San Pascual, en el municipio de Cieza (Región de Murcia, España), es un antiguo conjunto conventual de finales del siglo XVII. Declarado bien de interés cultural en el año 2000.',38.2372519,-1.4233857,'https://es.wikipedia.org/wiki/Convento_de_San_Joaquín_y_San_Pascual');
