INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182406,'08006','Mare de Déu de l''Esperança','religioso','religioso_osm','Capella de l''Esperança és una capella situada al carrer de l''Esperança del municipi de Blanes (Selva) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6760038,2.7956695,'https://ca.wikipedia.org/wiki/Capella_de_l''Esperança');
