INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182410,'12001','Catedral de la Asunción','religioso','religioso_osm','La catedral de Ceuta se encuentra situada en el espacio conocido desde época portuguesa como «La Ciudad», en un promontorio al sudeste de la zona interfosos y fue construida sobre una mezquita de la época de dominación árabe (711-1415). Durante el sitio de los 30 años fue hospital de sangre.',35.8878148,-5.3165945,'https://es.wikipedia.org/wiki/Catedral_de_la_Asunción_(Ceuta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182411,'07056','Església de la Mare de Déu de la Soledat','religioso','religioso_osm','L''Església de la Mare de Déu de la Soledat a Santa Maria del Camí o també Es Convent és l''església de l''antic Convent de la Soledat de Santa Maria del Camí. Està situada a la barriada dels Hostals confrontant amb el carrer Llarg i la carretera d''Inca.',39.6511247,2.7736245,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_de_la_Soledat');
