INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182415,'41904','Catedral Basílica de Nuestra Madre del Palmar Coronada','religioso','religioso_osm','La Iglesia Cristiana Palmariana de los Carmelitas de la Santa Faz, más conocida como Iglesia palmariana,​ Iglesia cristiana palmariana o Iglesia católica palmariana,​ es una iglesia católica independiente con sede episcopal en El Palmar de Troya, España. Fue fundada en 1978 por Clemente Domínguez, quien se declaró…',37.056093,-5.8089232,'https://es.wikipedia.org/wiki/Iglesia_palmariana');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182416,'08003','Basílica de la Mercè','religioso','religioso_osm','La Basílica de la Mare de Déu de la Mercè, o simplement de la Mercè, és una església situada a la plaça de la Mercè i els carrers Ample i de la Mercè de Barcelona, catalogada com a bé cultural d''interès local. D''estil barroc, va ser construïda entre 1765 i 1775 sota la direcció de l''arquitecte Josep Mas i Dordal en…',41.3795988,2.1797012,'https://ca.wikipedia.org/wiki/Basílica_de_la_Mercè');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182417,'10037','Santuario de la Vigen de la Montaña','religioso','religioso_osm','El santuario de la Montaña es un santuario católico ubicado en el municipio español de Cáceres. En este lugar se venera desde el siglo XVII a la Virgen de la Montaña, patrona de la ciudad de Cáceres.',39.4623448,-6.3517222,'https://es.wikipedia.org/wiki/Santuario_de_la_Montaña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182418,'47054','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo de culto católico ubicado en Cogeces del Monte (Valladolid). Pertenece al periodo del gótico tardío, pues fue levantada en el siglo XVI, se compone de tres naves con bóvedas de arista en yesería y de crucería en la capilla mayor.',41.5112041,-4.3149351,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Cogeces_del_Monte)');
