INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182420,'05168','Convento de Santo Domingo y San Pablo','religioso','religioso_osm','El convento de Santo Domingo y San Pablo es un convento ubicado en la localidad española Las Navas del Marqués, en la provincia de Ávila.',40.6057261,-4.3265114,'https://es.wikipedia.org/wiki/Convento_de_Santo_Domingo_y_San_Pablo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182421,'08003','Monestir de Santa Maria de Valldonzella','religioso','religioso_osm','El monestir de Santa Maria de Valldonzella és un conjunt arquitectònic situat al carrer del Císter, al barri de Sant Gervasi - la Bonanova de Barcelona, catalogat com a bé cultural d''interès local.',41.4117314,2.1305866,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Valldonzella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182422,'47186','Convento de San Quirce y Santa Julita','religioso','religioso_osm','El convento de San Quirce y Santa Julita es un monasterio situado en Valladolid (España). Ubicado en la plaza de la Trinidad y ocupado por monjas cistercienses, es uno de los monasterios más antiguos de la ciudad.',41.6574683,-4.7294955,'https://es.wikipedia.org/wiki/Convento_de_San_Quirce_y_Santa_Julita');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182423,'22188','Mare de Déu de Montserbós','religioso','religioso_osm','La Mare de Déu de Montserbós, altrament dita Santuari de les Capelles és un santuari d''origen romànic situat a 986 m d''altitud, prop del Tossal Gros, a ponent de Montllobar i, per tant, a prop del Pont de Montanyana. És dalt d''un turó que domina la carretera C-1311, que li fa pràcticament tota la volta.',42.1499882,0.7449527,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montserbós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182424,'29094','Ermita de Nuestra Señora de los Remedios','religioso','religioso_osm','La ermita de la Virgen de los Remedios es una ermita del municipio español de Vélez-Málaga, ubicada en el Cerro de San Cristóbal y en ella se encuentra la imagen de la patrona de Vélez, Nuestra Señora de los Remedios.',36.7817685,-4.0980973,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_los_Remedios_(Vélez-Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182425,'15083','Santuario de Santa Comba das Pías','religioso','religioso_osm','O santuario de Santa Columba das Pías é un santuario situado na parroquia de Codesoso pertencente ó concello de Sobrado.',43.0298582,-7.944085,'https://gl.wikipedia.org/wiki/Santuario_de_Santa_Columba_das_Pías');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182426,'08003','Església de la Mare de Déu de Gràcia i de Sant Josep','religioso','religioso_osm','L''església de la Verge de Gràcia i Sant Josep, coneguda popularment com els Josepets de Gràcia, està situada a la plaça de Lesseps i l''avinguda de la República Argentina de Barcelona, i està catalogada com bé cultural d''interès local. Va ser construïda entre el 1658 i el 1687 i projectada per fra Josep de la Concepció.',41.406824,2.1486705,'https://ca.wikipedia.org/wiki/Església_dels_Josepets_de_Gràcia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182427,'90088','Iglesia Parroquial de Nuestra Señora de los Ángeles','religioso','religioso_osm','La iglesia de Nuestra Señora de los Ángeles es el templo parroquial católico del municipio español de Acebo, situado al noroeste de la provincia de Cáceres.',40.2015605,-6.7170444,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_los_Ángeles_(Acebo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182428,'49219','Ermita de Nuestra Señora del Canto','religioso','religioso_osm','La ermita de Nuestra Señora del Canto es un templo religioso ubicado en la ciudad de Toro (Zamora).​ Reside en su interior la imagen de la Virgen del Canto que se trata de una escultura del siglo XII (denominada también “La Dueña”) y es la patrona de la ciudad. Durante la fiesta de la Patrona que se celebra el 8 de…',41.5203664,-5.403043,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Canto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182429,'21041','Catedral de la Merced','religioso','religioso_osm','La catedral de Nuestra Señora de la Merced es un templo católico, sede de la diócesis de Huelva. Creado como convento de padres mercedarios en 1605 sobre la antigua ermita de San Roque, funcionó como capilla del hospital provincial y como parroquia hasta que fue consagrado como catedral el 15 de marzo de 1954 al…',37.2630178,-6.9525248,'https://es.wikipedia.org/wiki/Catedral_de_Nuestra_Señora_de_la_Merced_(Huelva)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182430,'47100','Iglesia de Nuestra Señora del Castillo','religioso','religioso_osm','La iglesia de Nuestra Señora del Castillo, también llamada de la Asunción es un templo católico ubicado en la localidad de Muriel de Zapardiel, Provincia de Valladolid, Castilla y León, España. Construida entre los siglos XI y XII, y cerca de ella la torre, que se encuentra separada de la iglesia.',41.1218669,-4.8421287,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Castillo_(Muriel_de_Zapardiel)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182431,'42100','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es una iglesia-fortaleza románica que se encuentra en Hinojosa del Campo (Provincia de Soria, Castilla y León, España). Destaca por ser una iglesia encastillada con dos torres, una bereber y otra de origen cristiano, de la que queda buena parte de su fábrica románica.',41.7387483,-2.1011412,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Hinojosa_del_Campo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182432,'42039','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo católico de la localidad española de Borobia, en la provincia de Soria (Castilla y León). Se sitúa sobre un promontorio sobre el que domina la entrada por el norte a la localidad.',41.6652463,-1.8964768,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Borobia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182433,'12040','Cocatedral de Santa Maria','religioso','religioso_osm','La cocatedral de Santa Maria, també denominada església de Santa Maria la Major de Castelló de la Plana (Plana Alta) és un temple d''estil gòtic amb posteriors intervencions historicistes i en estil neogòtic. Està situada en la plaça Major, al costat de l''Ajuntament i la torre campanar independent, l''anomenat Fadrí.',39.9860203,-0.0367062,'https://ca.wikipedia.org/wiki/Cocatedral_de_Santa_Maria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182434,'36015','Concatedral de Santa María de Vigo','religioso','religioso_osm','A Concatedral-Basílica de Santa María de Vigo é un templo católico situado na cidade de Vigo, na praza da Igrexa. Desde 1959 ten a consideración de concatedral, compartindo a sé catedralicia da diocese de Tui-Vigo coa catedral de Tui, e, dende 2020, tamén a de basílica.',42.2392998,-8.7259652,'https://gl.wikipedia.org/wiki/Concatedral_de_Santa_María_de_Vigo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182435,'25173','l''Assumpció de la Mare de Déu','religioso','religioso_osm','L''Església Nova del Pont de Suert és l''església parroquial del Pont de Suert (Alta Ribagorça protegida com a bé cultural d''interès local.) S''anomena Església Nova perquè el 1955 va passar a ser l''església parroquial de la població, em substitució de l''Església Vella, que actualment serveix com a museu i custòdia la…',42.408988,0.7407865,'https://ca.wikipedia.org/wiki/Església_Nova_del_Pont_de_Suert');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182436,'43001','Catedral del Salvador','religioso','religioso_osm','La catedral del Salvador de Albarracín es un templo cristiano situado en la localidad de Albarracín, provincia de Teruel, España. Es sede catedralicia de la diócesis de Teruel y Albarracín junto con la catedral de Teruel.',40.4067703,-1.4445832,'https://es.wikipedia.org/wiki/Catedral_de_Albarracín');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182437,'28079','Parroquia Nuestra Señora de Covadonga','religioso','religioso_osm','La iglesia de Nuestra Señora de Covadonga es un templo católico situado en la plaza de Manuel Becerra en Madrid (España).​ La misma alberga una réplica de la Virgen de Covadonga, La Santina, patrona del Principado de Asturias.',40.4288661,-3.6690335,'https://es.wikipedia.org/wiki/Iglesia_de_Covadonga_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182438,'90879','Mare de Déu de Fucimanya','religioso','religioso_osm','El Santuari de la Mare de Déu de Fucimanya (Fussimanya en versió antiga), és una església d''estil romànic del segle xii situada al municipi de Sallent (Bages). És un monument protegit i inventariat dins el Patrimoni Arquitectònic Català.',41.8217506,1.9439188,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_Fucimanya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182439,'49065','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es una iglesia católica situada en la localidad española de Fermoselle, perteneciente a la provincia de Zamora, en la comunidad autónoma de Castilla y León. Fue declarada Bien de Interés Cultural con la categoría de monumento el 26 de septiembre de 2013.',41.3188864,-6.3992933,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Fermoselle)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182440,'47085','Colegiata de San Antolín','religioso','religioso_osm','La colegiata de San Antolín es, junto con el Castillo de La Mota, el edificio histórico más importante de Medina del Campo. Se encuentra situado en la plaza mayor de la localidad y, aunque la parte principal es característica del gótico final, la construcción es compleja, abarcando estilos desde principios del…',41.3076147,-4.9154356,'https://es.wikipedia.org/wiki/Colegiata_de_San_Antolín');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182441,'25190','Mare de Déu del Castell','religioso','religioso_osm','La Mare de Déu del Castell de Rivert és una ermita romànica, antiga capella del castell, del poble de Rivert, pertanyent al municipi de Conca de Dalt, al Pallars Jussà. Fins al 1969 formava part del terme municipal de Toralla i Serradell.',42.2500747,0.8954161,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Castell_de_Rivert');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182442,'25061','Mare de Déu de la Salut','religioso','religioso_osm','Mare de Déu de la Salut de Montanissell és un monument del municipi de Coll de Nargó (Alt Urgell) protegit com a bé cultural d''interès local.',42.1948199,1.2561032,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Salut_de_Montanissell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182443,'25903','Mare de Déu de la Roca','religioso','religioso_osm','La Mare de Déu de la Roca és una ermita romànica del poble d''Escart, en el terme municipal de la Guingueta d''Àneu, a la comarca del Pallars Sobirà. Pertany al territori de l''antic terme d''Escaló.',42.5462454,1.1423461,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Roca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182444,'25209','Mare de Déu de la Candelera','religioso','religioso_osm','La Mare de Déu de la Candelera d''Enviny, actualment dedicada a la Purificació, és l''església parroquial del poble d''Enviny, en el terme municipal de Sort, a la comarca del Pallars Sobirà. Pertanyia a l''antic terme d''Enviny.',42.4009544,1.1037967,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Candelera_d''Enviny');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182445,'25221','Mare de Déu del Roser','religioso','religioso_osm','La Mare de Déu del Roser de Forques és una capella romànica del terme municipal de Tírvia, a la comarca del Pallars Sobirà. Possiblement es tracta de l''església de l''antic poble de Forques, les restes de la qual s''estenen en un pla al nord-oest de la capella.',42.5215646,1.2453265,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_de_Forques');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182446,'25221','Mare de Déu de la Pietat','religioso','religioso_osm','La Mare de Déu de la Pietat de Tírvia és un conjunt de Tírvia (Pallars Sobirà) format per una capella i esteles funeràries medievals, protegit com a Bé Cultural d''Interès Local. Està situada a l''extrem sud-est del nucli de la vila, al cementiri municipal.',42.5145792,1.2451538,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Pietat_de_Tírvia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182447,'15065','Santuario da Nosa Señora da Escravitude','religioso','religioso_osm','O Santuario da Nosa Señora da Escravitude é unha igrexa mariana enclavado na Escravitude, aldea da parroquia de Santa María de Cruces, Padrón. A carón do templo pasa o camiño portugués do Camiño de Santiago.',42.7840037,-8.6496798,'https://gl.wikipedia.org/wiki/Santuario_da_Nosa_Señora_da_Escravitude');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182448,'28079','Parroquia Basílica Virgen Milagrosa','religioso','religioso_osm','La basílica de San Vicente de Paul, o iglesia de la Milagrosa, es un templo católico de la ciudad española de Madrid, ubicado en el distrito de Chamberí.',40.436926,-3.694901,'https://basilicalamilagrosa.es/','https://es.wikipedia.org/wiki/Basílica_de_la_Milagrosa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182449,'28079','Parroquia Nuestra Señora del Rosario de Filipinas','religioso','religioso_osm','La Iglesia de Nuestra Señora del Rosario de Filipinas es una iglesia católica de estilo brutalista.​​ Se encuentra ubicada en el número 40 de la Calle del Conde de Peñalver de Madrid (España).',40.4292506,-3.6748392,'https://www.madrid.es/vgn-ext-templating/v/index.jsp?vgnextchannel=9e4c43db40317010VgnVCM100000dc0ca8c0RCRD&vgnextoid=0801ef4d7f71c010VgnVCM1000000b205a0aRCRD','https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Rosario_de_Filipinas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182450,'25193','Monestir de Sant Llorenç de Morunys','religioso','religioso_osm','Sant Llorenç de Morunys, monestir benedictí, és l''església parroquial de la població de Sant Llorenç de Morunys en la comarca del Solsonès declarada bé cultural d''interès nacional.',42.13738,1.5911663,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Llorenç_de_Morunys');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182451,'90074','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción de la localidad de Adanero ( provincia de Ávila, Castilla y León, España) es un templo católico englobado en un conjunto arquitectónico que responde a las reformas llevadas a cabo en el siglo XVI y en los últimos años del siglo XVII de la primitiva iglesia…',40.9441466,-4.6038386,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Adanero)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182452,'90765','Ermita de la Virgen de la Corona','religioso','religioso_osm','La ermita de La Virgen de la Corona está situada en municipio de Almudévar, provincia de Huesca (Aragón, España) en el cerro del Castillo.',42.0432236,-0.5842248,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_la_Corona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182453,'37350','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción en Vilvestre (Salamanca, España) es un templo parroquial de estilo arquitectónico gótico final, construido en el siglo XVI. Este templo está construido en sillería de granito. La capilla mayor realizada con bóveda de cruceria en su interior, y rematada con ángeles y…',41.104441,-6.7260277,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Vilvestre)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182454,'24189','Basílica de la Virgen del Camino','religioso','religioso_osm','La Basílica Menor y Real Santuario​ de la Virgen del Camino se encuentra en la localidad de La Virgen del Camino, perteneciente al municipio de Valverde de la Virgen, en la provincia de León (España). Está dedicada a la Virgen del Camino, patrona de la región de León y de la ciudad de Pamplona, y se encuentra en la…',42.5800449,-5.6413475,'https://es.wikipedia.org/wiki/Basílica_de_la_Virgen_del_Camino');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182455,'45138','Iglesia del convento de Franciscanos Descalzos','religioso','religioso_osm','La iglesia del convento de Franciscanos Descalzos es un inmueble de la localidad española de El Puente del Arzobispo, en la provincia de Toledo. Único resto del antiguo convento de Franciscanos Descalzos, cuenta con el estatus de bien de interés patrimonial.',39.8059222,-5.1688438,'https://es.wikipedia.org/wiki/Iglesia_del_convento_de_Franciscanos_Descalzos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182456,'23065','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción de la localidad de Orcera (Provincia de Jaén, España) es una construcción del siglo XVI. Su portada-retablo, del último tercio del siglo XVI, pertenecía al desaparecido convento de Santa María de la Peña. La torre del campanario procede de un torreón del castillo que…',38.3177416,-2.6590136,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Orcera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182457,'23017','Iglesia de Nuestra Señora de la Expectación','religioso','religioso_osm','La Iglesia de Nuestra Señora de la Expectación es un templo religioso católico situado en la población de Cabra del Santo Cristo en Jaén en Andalucía con la advocación mariana de la Virgen de la Expectación. Además es el Santuario del Santo Cristo de Burgos.',37.7050046,-3.2854808,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Expectación');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182458,'17116','Santuari de la Mare de Déu del Coll d''Osor','religioso','religioso_osm','La Mare de Déu del Coll és una església de Susqueda (Selva) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9578781,2.5244215,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Coll_d''Osor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182459,'23020','Ermita de Nuestra Señora de los Remedios','religioso','religioso_osm','La ermita de la Virgen de los Remedios situada en el término municipal de Canena (Provincia de Jaén, España) es una construcción que se inicia a finales del siglo XV y se concluye en la primera mitad del siglo XVIII gracias a limosnas como se indica en la fachada.​ Se trata de un templo de planta rectangular con…',38.0495111,-3.4821767,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_los_Remedios_(Canena)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182460,'31113','Ermita de Nuestra Señora de Zuberoa','religioso','religioso_osm','Zuberoako Andre Mariaren baseliza (erronkaribarreraz: Xiberuako Andra Mariren baseliza) Erronkariko ibaxako Garde udalerrian XVI. mendean kristiau baseliza bat da.',42.7900649,-0.8865011,'https://eu.wikipedia.org/wiki/Andre_Maria_Zuberoakoa_baseliza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182461,'17102','Mare de Déu de les Salines','religioso','religioso_osm','La Mare de Déu de les Salines és un santuari a migdia del puig de les Salines, a l''extrem nord del terme municipal de Maçanet de Cabrenys, a 15 km del nucli urbà, inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.4208701,2.7488785,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Salines');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182462,'40194','Ermita del Cristo del Mercado','religioso','religioso_osm','La ermita del Cristo del Mercado, situada en la Calle José Zorrilla de la ciudad de Segovia (España), es una construcción que data de los primeros años del siglo XV, coincidiendo con la llegada a la ciudad de San Vicente Ferrer. Se venera al Santo Cristo de la Cruz del Mercado, conocido popularmente como el Cristo…',40.9368299,-4.1129899,'https://es.wikipedia.org/wiki/Ermita_del_Cristo_del_Mercado');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182463,'16078','Iglesia del Santísimo Cristo del Amparo','religioso','religioso_osm','La iglesia del Santísimo Cristo del Amparo en Cuenca (España) fue construida a finales del siglo XVI y está situada en el barrio de Los Tiradores. Este barrio en el siglo XV conoció la llegada de gentes humildes que se acercaban a la gran ciudad en busca de trabajo.',40.0742414,-2.1310249,'https://es.wikipedia.org/wiki/Iglesia_del_Santísimo_Cristo_del_Amparo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182464,'31232','Ermita de la Virgen de la Cabeza','religioso','religioso_osm','Cabezako Ama Birjinaren baseliza Nafarroako Tutera udalerrian dagoen baseliza bat da. Cabezako Ama Birjinaren karrikan kokatua dago.',42.0663943,-1.6093477,'https://eu.wikipedia.org/wiki/Cabezako_Ama_Birjinaren_baseliza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182465,'06025','Iglesia de Nuestra Señora del Carmen','religioso','religioso_osm','La iglesia de Nuestra Señora del Carmen nace como santuario anexo al Convento de Franciscanos descalzos que había sido trasladado en el siglo XVIII desde la iglesia de Nuestra Señora de la Antigua. Tras la Desamortización de Mendizábal, el cenobio pasó a acoger las instalaciones del Hospital Psiquiátrico de la…',38.9191933,-6.3464764,'https://es.wikipedia.org/wiki/Iglesia_del_Carmen_(Mérida)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182466,'31114','Santo Cristo de Catalain','religioso','religioso_osm','La ermita del Cristo de Cataláin, o con un título más completo, ermita del Santo Cristo de Cataláin, cerca de Garínoain (Navarra) es un conjunto de arquitectura románica en España, datado en el siglo XII, conservado y utilizado, que llegó a pertenecer a Colegiata de Santa María de Roncesvalles, hasta su…',42.6024214,-1.6270018,'https://www.arquivoltas.com/6-Navarra/Catalain1.htm','https://es.wikipedia.org/wiki/Ermita_del_Cristo_de_Cataláin');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182467,'31059','Ermita de la Virgen del Castillo','religioso','religioso_osm','Gazteluko Andre Mariaren baseliza (erronkaribarreraz: Gaztuluko Andra Mariren baseliza) Erronkariko ibaxako Burgi udalerrian XII. mendeko kristiau baseliza bat da, erromaniko estiloan.',42.7204721,-1.0060011,'https://eu.wikipedia.org/wiki/Gazteluko_Andra_Mariren_baseliza_(Burgi)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182468,'34017','Ermita del Santísimo Cristo de Torre Marte','religioso','religioso_osm','Se encuentra situada sobre un alto a las afueras de Astudillo en la carretera de Amusco a Palacios del Alcor en la comarca de Tierra de Campos de Palencia. A fecha agosto de 2011 el monumento no era visitable.',42.1930924,-4.3257547,'https://es.wikipedia.org/wiki/Ermita_del_Santísimo_Cristo_de_Torre_Marte_(Astudillo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182469,'50297','Iglesia de Nuestra Señora del Portillo','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora del Portillo es un templo de culto católico en la ciudad de Zaragoza (Aragón, España). Está declarado Monumento Nacional.',41.6558831,-0.8931339,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Portillo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182470,'25064','Mare de Déu de Massarrúbies','religioso','religioso_osm','El santuari de Massarrúbies es una església de Montpol, al municipi de Lladurs (Solsonès), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0683471,1.4152471,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_Massarrúbies');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182471,'25123','Mare de Déu del Pont','religioso','religioso_osm','La Mare de Déu del Pont és una capella del poble de Lladrós, en el terme municipal de Vall de Cardós, a la comarca del Pallars Sobirà. És en territori de l''antic terme d''Estaon.',42.6073639,1.2454406,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Pont');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182472,'28083','Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia parroquial de la Asunción de Nuestra Señora es un templo católico situado en la localidad española de Meco. Cuenta con el estatus de Bien de Interés Cultural.',40.5536626,-3.3292835,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Meco)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182473,'29001','Parroquia Castrense Nuestra Señora de Loreto','religioso','religioso_osm','La parroquia castrense de Nuestra Señora de Loreto, también conocida como la parroquia de Loreto es un templo católico situado en Alcalá de Henares, en la Comunidad de Madrid, España). Se encuentra ubicada en la calle Barberán y Collar, en el barrio Ciudad del Aire, a las afueras de la ciudad complutense.',40.5021346,-3.348096,'https://es.wikipedia.org/wiki/Parroquia_castrense_Nuestra_Señora_de_Loreto_(Alcalá_de_Henares)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182474,'51025','Ermita de Nuestra Señora de la Cabeza','religioso','religioso_osm','La ermita de Nuestra Señora de la Cabeza es una pequeña ermita católica de origen medieval de la ciudad española de Ávila.',40.6606151,-4.702256,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_la_Cabeza_(Ávila)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182475,'08090','Mare de Déu de Montserrat','religioso','religioso_osm','La Mare de Déu de Montserrat de Cal Riera és una església situada a la colònia tèxtil homònima de Puig-reig (Berguedà), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9321464,1.8789898,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montserrat_de_Cal_Riera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182476,'08019','Mare de Déu de Montdois','religioso','religioso_osm','El santuari de la Mare de Déu de Montdois és una església del terme municipal de Rupit i Pruit catalogada a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''edifici actual data del segle xviii, tot i que ja es menciona una capella de Santa Maria de "Mont Doys" a la parròquia de Fàbregues l''any 1263.',41.9859146,2.481626,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montdois');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182477,'46021','Església de la Mare de Déu de l''Olivar','religioso','religioso_osm','L''Església parroquial de la Mare de Déu de l''Olivar és un temple catòlic situat a la plaça d''Espanya, al municipi d''Alaquàs. És un Bé de Rellevància Local amb identificador número 46.14.005-002.',39.4567884,-0.4613815,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_de_l''Olivar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182478,'08102','Basílica de Santa Maria d''Igualada','religioso','religioso_osm','Santa Maria d''Igualada o l''Església Gran és una basílica del municipi d''Igualada (Anoia). És el conjunt historicoartístic més important de la capital anoienca.',41.5787988,1.6183062,'http://www.igda.cat/espais/basilica-santa-maria/','https://ca.wikipedia.org/wiki/Santa_Maria_d''Igualada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182479,'06098','Iglesia de Nuestra Señora de Gracia','religioso','religioso_osm','La iglesia parroquial de Santa María de Gracia es un templo católico situado en la localidad española de Palomas, perteneciente a la provincia de Badajoz, en la comunidad autónoma de Extremadura.',38.6911898,-6.1336031,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Gracia_(Palomas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182480,'90774','Iglesia de Nuestra Señora de la Piedad','religioso','religioso_osm','La iglesia de Nuestra Señora de la Piedad en Azuara (Provincia de Zaragoza, España), originalmente respondía tipológicamente al modelo de iglesia fortificada mudéjar, tan difundido en Aragón durante la Baja Edad Media. Fue construida en la segunda mitad del siglo XIV, tenía cabecera recta y una amplia nave única de…',41.2561115,-0.8719349,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Piedad_(Azuara)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(182481,'13089','Iglesia parroquial de Nuestra Señora de la Asunción','religioso','religioso_osm','Templo de larga tradición devocional en Villahermosa (Ciudad Real).',38.7503524,-2.8719896);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182482,'10127','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de la Asunción es el templo central de Montehermoso. Se sitúa entre las calles Iglesia, Cisneros, Hernández Gil y el Osario, en pleno casco histórico de Montehermoso, a igual distancia de las plazas de España y Morón, y junto a la casa y los salones parroquiales.',40.0887924,-6.3496368,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Montehermoso)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182483,'28079','Convento de Santa Teresa de Jesús','religioso','religioso_osm','El convento de Santa Teresa es un convento de carmelitas descalzas en Madrid.',40.4438785,-3.6992275,'https://es.wikipedia.org/wiki/Convento_de_Santa_Teresa_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182484,'22223','Mare de Déu de l''Esperança','religioso','religioso_osm','La Mare de Déu de l''Esperança del Castellet és l''església romànica del veïnat del Castellet, en el terme actual de Tremp, dins de l''antic terme d''Espluga de Serra. La primitiva església del Castellet fou la de Sant Feliu del Castellet, que fou abandonada en un temps indeterminat.',42.2738174,0.8266772,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_l''Esperança_del_Castellet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182485,'08194','Mare de Déu de la Salut','religioso','religioso_osm','L''església de la Mare de Déu de la Salut és un temple parroquial catòlic del barri de La Salut de Badalona, al passeig de La Salut, núm. 38.',41.440852,2.2281183,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_de_la_Salut_(Badalona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182486,'37174','Iglesia de Nuestra Señora del Castillo','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora del Castillo es una iglesia católica de la localidad española de Macotera (en la provincia de Salamanca). Data de finales del siglo XV, como lo atestiguan los escudos de armas que campean en diversas partes del edificio, pertenecientes al segundo duque de Alba y a su esposa.',40.8309455,-5.2854786,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Castillo_(Macotera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182487,'04051','Iglesia de Nuestra Señora de la Anunciación','religioso','religioso_osm','La Iglesia de Nuestra Señora de la Anunciación es la iglesia parroquial de la localidad de Huécija (Almería-España).',36.9683397,-2.6102673,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Anunciación_(Huécija)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182488,'04051','Convento de los Agustinos','religioso','religioso_osm','El convento de los Agustinos es el monumento más importante del municipio de Huécija situado en la provincia de Almería (Andalucía, España) y uno de los mejores ejemplos de arquitectura barroca de la provincia de Almería.',36.96794,-2.60848,'https://es.wikipedia.org/wiki/Convento_de_los_Agustinos_(Huécija)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182489,'25115','Mare de Déu de les Esplugues','religioso','religioso_osm','La Mare de Déu de les Esplugues és un santuari de l''antic terme de Conques, actualment integrat en el terme municipal d''Isona i Conca Dellà. Està situat a l''extrem nord-oriental del Mont de Conques, a migdia i a prop del poble de Sant Romà d''Abella.',42.1309495,1.0262128,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Esplugues');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182490,'29069','Ermita del Santo Cristo de la Vera Cruz','religioso','religioso_osm','La ermita del Santo Cristo de la Vera Cruz es un templo católico de la ciudad de Marbella, en la provincia de Málaga, España. Está situada en el Barrio Alto, arrabal histórico de la antigua ciudad, considerado como parte del casco antiguo.',36.5124796,-4.8851027,'https://es.wikipedia.org/wiki/Ermita_del_Santo_Cristo_de_la_Vera_Cruz_(Marbella)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182491,'51025','Capilla de Nuestra Señora de las Nieves','religioso','religioso_osm','La ermita de Nuestra Señora de las Nieves es un templo católico de la ciudad española de Ávila.',40.6555737,-4.698746,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_las_Nieves_(Ávila)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182492,'25202','Mare de Déu de Gràcia','religioso','religioso_osm','Santa Maria de Gràcia de Senterada és l''església parroquial d''origen romànica del poble de Senterada, a la comarca del Pallars Jussà. Està situada aproximadament al centre de la població, al peu de la carretera de la Vall Fosca.',42.3248039,0.9373307,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Gràcia_de_Senterada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182493,'25173','Mare de Déu de les Neus','religioso','religioso_osm','Mare de Déu de les Neus d''Irgo de Tor o Santa Maria de les Neus d''Irgo és una església del municipi del Pont de Suert (Alta Ribagorça). En concret, és l''església parroquial del poble d''Irgo de Tor, de l''antic terme de Llesp.',42.4445539,0.7712903,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Neus_d''Irgo_de_Tor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182494,'25039','Mare de Déu d''Arboló','religioso','religioso_osm','L''ermita de la Mare de Déu d''Arboló és una capella del terme municipal de Soriguera, a la comarca del Pallars Sobirà. Pertany al territori del poble d''Arcalís, dins de l''antic terme d''Estac.',42.3353599,1.0660912,'https://ca.wikipedia.org/wiki/Mare_de_Déu_d''Arboló');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182495,'25089','Mare de Déu de la Serra','religioso','religioso_osm','La Mare de Déu de la Serra és una ermita romànica del poble de Farrera (Pallars Sobirà), en el terme municipal del mateix nom, a la comarca del Pallars Sobirà. Està situada a 600 metres al nord-oest del poble de Farrera.',42.5007462,1.2662327,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Serra_(Farrera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182496,'11020','Parroquia Nuestra Señora de Fátima','religioso','religioso_osm','La iglesia de Nuestra Señora de Fátima es un templo parroquial de la localidad andaluza de Jerez de la Frontera, en la provincia de Cádiz, España. Se encuentra ubicada entre la barriada de la Constancia y la barriada España.',36.6885786,-6.1295206,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Fátima_(Jerez_de_la_Frontera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182497,'90574','Mare de Déu de la Serra','religioso','religioso_osm','Mare de Déu de la Serra és una obra del municipi de Fogars de la Selva (Selva) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7246827,2.6282474,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Serra_(Fogars_de_la_Selva)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182498,'11032','Iglesia de Nuestra Señora de la O','religioso','religioso_osm','La iglesia de Nuestra Señora de la O de la ciudad española de Sanlúcar de Barrameda, en la andaluza provincia de Cádiz, es un templo católico.',36.7761357,-6.3530979,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_O_(Sanlúcar_de_Barrameda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182499,'46044','Iglesia parroquial de la Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia parroquial de la Asunción de Nuestra Señora se encuentra situada en el centro de Ayora, formando una manzana casi completa. Es un compendio de la arquitectura entre los siglos XVI y XVII, con estilo renacentista y manierista.',39.059922,-1.0565654,'https://es.wikipedia.org/wiki/Iglesia_de_la_Asunción_de_Nuestra_Señora_(Ayora)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182500,'46059','Monestir de Santa Maria d''Aigües Vives','religioso','religioso_osm','El Convento de Aguas Vivas (llamado en valenciano Convent d''Aigües Vives), también conocido como Real Monasterio de Santa María de Aguas Vivas (Reial Monestir de Santa Maria d''Aigües Vives) está situado en la entidad menor valenciana de La Barraca de Aguas Vivas; España.',39.0891527,-0.3545431,'https://es.wikipedia.org/wiki/Convento_de_Aguas_Vivas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182501,'08005','Mare de Déu de la Pietat','religioso','religioso_osm','La capella de la Pietat és un edifici de Berga protegit com a bé cultural d''interès local.',42.1052234,1.8470879,'https://ca.wikipedia.org/wiki/Capella_de_la_Pietat_(Berga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182502,'21030','Iglesia de Nuestra Señora de la Estrella','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de la Estrella es un templo católico que se encuentra en el municipio de Chucena, provincia de Huelva (España). Esta iglesia parroquial esta bajo el patrocinio de la advocación mariana de la Virgen de la Estrella.',37.3603629,-6.3951465,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Estrella_(Chucena)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182503,'21047','Iglesia de Nuestra Señora de la Purificación','religioso','religioso_osm','La iglesia de Santa María de la Purificación (Iglesia de Nuestra Señora de la Purificación), en la población de Manzanilla (Provincia de Huelva), es un ejemplo del tipo de iglesia sevillana, en el que confluyen los estilos mudéjar y barroco, siguiendo un modo de proceder característico de la práctica constructiva…',37.3869335,-6.4284276,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Purificación_(Manzanilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182504,'15022','Santuario de Santo André de Teixido','religioso','religioso_osm','O santuario de Santo André de Teixido é unha capela situada no lugar de Santo André de Teixido, na parroquia de Régoa, no leste do concello de Cedeira, e preto de cabo Ortegal. É un famoso lugar de peregrinación, ao que, segundo o dito popular "vai de morto quen non foi de vivo".',43.709041,-7.9841049,'https://gl.wikipedia.org/wiki/Santuario_de_Santo_André_de_Teixido');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182505,'21054','Iglesia de Nuestra Señora del Valle','religioso','religioso_osm','La ermita de Nuestra Señora del Valle es un templo católico situado en la localidad de La Palma del Condado.',37.3881432,-6.5537241,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Valle_(La_Palma_del_Condado)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182506,'08226','Mare de Déu de Sentfores','religioso','religioso_osm','Mare de Déu de Sentfores és un edifici religiós del municipi de Sant Martí de Tous comarca de l''(Anoia) protegida com a bé cultural d''interès local. Tenint vora set segles d''història, ha estat un punt de devoció pels habitants del poble de Tous i dels municipis propers.',41.5528286,1.5395606,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Sentfores');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182507,'21050','Convento de San Francisco','religioso','religioso_osm','El convento de San Francisco se encuentra en Moguer, provincia de Huelva (España).',37.2756833,-6.8410176,'https://es.wikipedia.org/wiki/Convento_de_San_Francisco_(Moguer)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182508,'40076','Ermita del Cristo del Caloco','religioso','religioso_osm','La ermita del Cristo del Caloco es una ermita en la que se venera la imagen del Cristo del Caloco. Se ubica en el municipio de El Espinar, en la provincia de Segovia (Castilla y León, España).',40.7437728,-4.2705487,'https://es.wikipedia.org/wiki/Cristo_del_Caloco');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182509,'46029','Basílica Menor de Sant Jaume','religioso','religioso_osm','La basílica de San Jaime Apóstol es una iglesia construida entre 1550 y 1582 por Domingo Gamieta, contando con la colaboración de Juan de Alicante y Juan Matalí. El templo y su entorno fueron propuestos y catalogados como Bien de Interés Cultural, en la categoría de monumento, por su gran riqueza histórica y…',39.1891291,-0.4364535,'https://es.wikipedia.org/wiki/Basílica_de_San_Jaime_Apóstol');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182510,'08255','Mare de Déu de Pinós','religioso','religioso_osm','Santa Maria de Ginebret és una santuari de Santa Maria de Merlès (Berguedà) inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya. Conegut com el Santuari de la Mare de Déu de Ginebret o de Pinós.',41.9800254,1.9414119,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Ginebret');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182511,'31179','Monasterio de La Oliva','religioso','religioso_osm','El Monasterio de Santa María la Real de la Oliva (o abadía cisterciense del monasterio de Santa María la Real de la Oliva, o también de Nuestra Señora de la Oliva) es un cenobio de la Orden Cisterciense situado en Carcastillo (Navarra). Fue la primera fundación cisterciense establecida dentro del reino de Navarra.​…',42.371808,-1.4664461,'https://www.monasteriodelaoliva.org/','https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_la_Real_de_la_Oliva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182512,'21078','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción de Zalamea la Real (provincia de Huelva, España) es un edificio religioso católico que tiene su origen en los comienzos del siglo XVI, aunque se conservan pocos elementos de aquella primera construcción. Situada en la zona alta de la localidad, domina el conjunto urbano…',37.6803532,-6.6607719,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Zalamea_la_Real)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182513,'05067','Ermita de Nuestra Señora de Rihondo','religioso','religioso_osm','La ermita de Nuestra Señora de Rihondo se localiza en el municipio de Benitos del Rebollar, en la vertiente norte de la sierra de Ávila, al pie de la carretera AV-110, cerca del cruce hacia la localidad de Benitos y a 1,5 km de Chamartín de la Sierra.',40.6954583,-4.9412291,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Rihondo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182514,'08128','Mare de Déu del Roser del Bosc','religioso','religioso_osm','La Mare de Déu del Roser del Bosc és una capella del poble de Monistrol de Calders, a la comarca del Moianès. Està situada en el mas del Bosc, al sud-oest del poble, a la part central-occidental del terme municipal.',41.7538799,2.0012953,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_del_Bosc');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182515,'46106','Iglesia Nuestra Señora de los Ángeles','religioso','religioso_osm','L''església de La nostra Senyora dels Àngels se situa en el municipi de Xelva, a la comarca dels Serrans, a la província de València. Es tracta d''un edifici d''arquitectura religiosa construït entre els segles xvii i xviii d''estils manierista i barroc, que posseeix una important col·lecció de pintura i orfebreria.',39.7476801,-0.9971854,'https://ca.wikipedia.org/wiki/Església_de_Nostra_Senyora_dels_Àngels_de_Xelva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182516,'90462','Iglesia de Nuestra Señora de la Consolación','religioso','religioso_osm','La Parroquia de Nuestra Señora de la Consolación es un templo católico situado en la localidad de Cabezas Rubias.',37.7266149,-7.0862966,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Consolación_(Cabezas_Rubias)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182517,'17046','Mare de Déu de la Devesa','religioso','religioso_osm','Santuari de la Mare de Déu de la Devesa és un edifici del municipi de Montagut i Oix (Garrotxa) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.2062926,2.5680165,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Devesa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182518,'08010','Mare de Déu de Mont-ros','religioso','religioso_osm','Les ruïnes de la capella de la Mare de Déu de Mont-ros es troben al cim del Mont-ros, al contrafort nord-occidental de la serra de Sant Julià del Mont, a l''extrem oriental del terme, dintre de la parròquia de Begudà. El 2012, l''Ajuntament de Sant Joan les Fonts va comprar el terreny on hi ha les restes del castell…',42.2067454,2.5503805,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Mont-ros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182519,'22188','Mare de Déu del Roser','religioso','religioso_osm','La Mare de Déu del Roser del Mas de Pere és una capella romànica del Mas de Pere, al nucli de masies dispers dels Masions, en el poble de Castissent, de l''antic terme municipal Fígols de Tremp, integrat actualment en el de Tremp, de la comarca del Pallars Jussà. És una capella romànica molt senzilla.',42.136174,0.7349558,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_del_Mas_de_Pere');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182520,'42215','Iglesia Nuestra Señora del Pino','religioso','religioso_osm','La iglesia de Nuestra Señora del Pino de Vinuesa es un templo católico situado en la localidad soriana de Vinuesa, en la comunidad autónoma de Castilla y León en España. Se comenzó a construir en el año 1591, es de estilo gótico renacentista.',41.9115733,-2.7627029,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Pino_(Vinuesa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182521,'41012','Ermita de Nuestra Señora de Cuatrovitas','religioso','religioso_osm','La ermita de Nuestra Señora de Cuatrovitas, también llamada de Nuestra Señora de Cuatrohabitan, o simplemente Ermita de Cuatrovitas, es un templo católico situado en el paraje de Cuatrovitas, perteneciente al municipio de Bollullos de la Mitación, en la provincia de Sevilla, España y distante seis kilómetros de su…',37.2981791,-6.1837695,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Cuatrovitas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182522,'41025','Ermita de Nuestra Señora de Consolación','religioso','religioso_osm','La ermita de Nuestra Señora de Consolación es un templo que se encuentra en la localidad de Carrión de los Céspedes, y cuyos titulares pertenecen a la Real, Antigua e Ilustre Hermandad del Santísimo Cristo de la Vera Cruz, María Santísima de la Soledad y Nuestra Señora de Consolación Patrona y Alcaldesa Honoraria…',37.3676078,-6.3259823,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Consolación');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182523,'44161','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es una iglesia parroquial de Muniesa, Teruel, Aragón, España.',41.0338914,-0.8122391,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Muniesa)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182524,'90149','Iglesia de la Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia de la Asunción de Nuestra Señora en La Almunia de Doña Godina (provincia de Zaragoza, España) cuenta con una torre que es el único vestigio de la construcción medieval de la Iglesia Parroquial, que fue demolida en el siglo XVIII y sustituida por la actual fábrica barroca. Está situada en el ángulo…',41.4767271,-1.3748027,'https://es.wikipedia.org/wiki/Iglesia_de_la_Asunción_de_Nuestra_Señora_(La_Almunia_de_Doña_Godina)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182525,'25196','Mare de Déu d''Arbul','religioso','religioso_osm','El santuari de la Mare de Déu d''Arbul pertany a l''antic terme de Fígols de Tremp, integrat actualment en el de Tremp, de la comarca del Pallars Jussà. És un temple d''origen romànic situat a 932 m d''altitud, a l''antic lloc d''Arbul, al sud-oest de Montllobar i, per tant, a prop de Fígols de Tremp.',42.1268903,0.785595,'https://ca.wikipedia.org/wiki/Mare_de_Déu_d''Arbul');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182526,'08228','Mare de Déu del Roser','religioso','religioso_osm','La Capella del Roser de Sant Martí Sesgueioles és una obra de Sant Martí Sesgueioles (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7029051,1.4893105,'https://ca.wikipedia.org/wiki/Capella_del_Roser_de_Sant_Martí_Sesgueioles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182527,'43017','Monestir de Sant Miquel d''Escornalbou','religioso','religioso_osm','El Castell d''Escornalbou és una mansió senyorial que ajunta monestir (Sant Miquel d''Escornalbou) amb castell, a l''antic terme d''Escornalbou (derivat del llatí Cornu Bovis, «el corn del bou»), avui al municipi de Riudecanyes al Baix Camp. El conjunt arquitectònic és format per un castell primigeni i l''antiga…',41.1271739,0.9161168,'https://ca.wikipedia.org/wiki/Castell_monestir_d''Escornalbou');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182528,'08170','Mare de Deu del Portal','religioso','religioso_osm','La Mare de Déu del Portal és una església a la vila dels Prats de Rei (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. L''actual edifici està situat al lloc que ocupà el Portal Major, de la vila dels Prats de Rei, sobre el qual, quan es van reedificar les muralles, entre els anys 1375 i 1377,…',41.7047529,1.5417651,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Portal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182529,'46230','Iglesia de Nuestra Señora de los Ángeles','religioso','religioso_osm','L''Església Parroquial de la Mare de Déu dels Àngels és un temple catòlic situat en el municipi de Silla. És Bé de Rellevància Local amb identificador nombre 46.16.230-001.',39.3629487,-0.4123416,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_dels_Àngels_de_Silla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182530,'17091','Mare de Déu del Carme','religioso','religioso_osm','L''Església del Carme de Camprodon és una obra gòtica de Camprodon (Ripollès) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3108362,2.3656973,'https://ca.wikipedia.org/wiki/Església_del_Carme_de_Camprodon');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182531,'17091','Mare de Déu del Roure','religioso','religioso_osm','La Capella del Roure és una petita capella de Camprodon (Ripollès). Originàriament era un petit oratori de camí situat a la sortida de la vila en direcció a Molló.',42.3152796,2.3782515,'https://ca.wikipedia.org/wiki/Capella_del_Roure_(Camprodon)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182532,'14021','Parroquia de Nuestra Señora de la Paz','religioso','religioso_osm','La iglesia de Nuestra Señora de la Paz, más conocida como iglesia de San Basilio, fue fundada en el año 1590 por los monjes de San Basilio y es la antigua iglesia conventual del desaparecido colegio de San Basilio. En 1846 fue designada parroquia auxiliar de la del Sagrario debido a la gran distancia entre la…',37.8761793,-4.7844154,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Paz_(Córdoba)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182533,'25190','Mare de Déu del Coll','religioso','religioso_osm','La Mare de Déu del Coll és l''actual església parroquial del poble de Salàs de Pallars, del terme municipal del mateix nom, a la comarca del Pallars Jussà.',42.212157,0.9320176,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Coll_de_Salàs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182534,'25201','Mare de Déu de Castellgermà','religioso','religioso_osm','La Mare de Déu de Castellgermà és una capella del terme municipal de Sarroca de Bellera, al Pallars Jussà. Està situada a l''antic poble de Castellgermà, abandonat de fa temps, aturonat al nord de Xerallo, a la dreta del riu de les Esglésies.',42.3750189,0.862083,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Castellgermà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182535,'90596','Mare de Déu de les Neus','religioso','religioso_osm','La capella de la Mare de Déu de les Neus és una església del municipi d''Alp (Cerdanya) protegida com a bé cultural d''interès local.',42.3357938,1.9371718,'https://ca.wikipedia.org/wiki/Capella_de_la_Mare_de_Déu_de_les_Neus_(la_Molina)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182536,'41091','Convento de Santa Inés','religioso','religioso_osm','El convento de Santa Inés de Sevilla, situado en la céntrica calle Doña María Coronel de esta ciudad, lo funda en el año 1374 una dama de ilustre familia sevillana, María Coronel, viuda de Juan de la Cerda. Esta fundación la lleva a cabo en el solar del palacio familiar de su padre, el señor de Aguilar, al que…',37.3934487,-5.9900318,'https://es.wikipedia.org/wiki/Convento_de_Santa_Inés_(Sevilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182537,'08083','Mare de Déu de la Damunt','religioso','religioso_osm','L''ermita de la Damunt és un edifici de Folgueroles (Osona) inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9444551,2.3231133,'https://ca.wikipedia.org/wiki/Ermita_de_la_Damunt');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182538,'90069','La Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia parroquial de la Asunción de Nuestra Señora es un templo católico situado en el municipio de español de Algete, perteneciente a la Comunidad de Madrid. Data de principios del siglo XVI. Está construida con cajoneras de mampostería y ladrillos revocados en parte.',40.5959033,-3.4974114,'https://es.wikipedia.org/wiki/Iglesia_de_la_Asunción_de_Nuestra_Señora_(Algete)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182539,'25249','Mare de Déu de les Omedes','religioso','religioso_osm','Santa Maria de les Omedes és una església del municipi de Vilanova de l''Aguda (Noguera) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. És al costat del mas de les Omedes, al peu de la pista que de Vilanova de l''Aguda remunta la vall del torrent de Valldàries, a la parròquia de l''Aguda.',41.921684,1.26256,'https://ca.wikipedia.org/wiki/Santa_Maria_de_les_Omedes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182540,'25115','Mare de Déu de la Posa','religioso','religioso_osm','La Mare de Déu de la Posa és un santuari del municipi d''Isona i Conca Dellà, pertanyent a l''antic terme municipal d''Isona.',42.1256207,1.0780858,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Posa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182541,'90606','Mare de Déu de la Pietat','religioso','religioso_osm','La Mare de Déu de la Pietat és una capella del municipi de Sant Gregori (Gironès).',41.986707,2.7016298,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Pietat_(Sant_Gregori)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182542,'28132','Iglesia de la Natividad de Nuestra Señora','religioso','religioso_osm','La iglesia parroquial de la Natividad de Nuestra Señora es un templo católico ubicado en el municipio español de San Martín de la Vega, en la Comunidad de Madrid. Se trata de un edificio del siglo XVI con planta rectangular, con una sola nave y cabecera plana.',40.2077061,-3.5699103,'https://es.wikipedia.org/wiki/Iglesia_de_la_Natividad_de_Nuestra_Señora_(San_Martín_de_la_Vega)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182543,'47038','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo de culto católico ubicado en la parte más alta de Castrillo de Duero (Valladolid).',41.5754734,-4.0150903,'https://es.wikipedia.org/wiki/Iglesia_de_la_Asunción_(Castrillo_de_Duero)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182544,'90492','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de la Asunción es un inmueble de la localidad española de Aldeacipreste, en la provincia de Salamanca.',40.3804877,-5.896975,'https://es.wikipedia.org/wiki/Iglesia_de_la_Asunción_(Aldeacipreste)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182545,'47207','Colegiata de San Luis','religioso','religioso_osm','La colegiata de San Luis es un templo católico ubicado en la localidad de Villagarcía de Campos, provincia de Valladolid (Castilla y León, España). Ejemplo de la arquitectura renacentista del siglo XVI, es obra del arquitecto Rodrigo Gil de Hontañón.',41.7788812,-5.190901,'https://es.wikipedia.org/wiki/Colegiata_de_San_Luis');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182546,'17043','Mare de Déu del Remei del Serrat','religioso','religioso_osm','La Mare de Déu del Remei del Serrat és una obra del poble del Serrat, municipi de Queralbs (Ripollès) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3419459,2.1853097,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Remei_del_Serrat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182547,'47082','Ermita de la Virgen de Sieteiglesias','religioso','religioso_osm','La ermita de la Virgen de Sieteiglesias es una ermita católica de la localidad española de Matapozuelos, perteneciente a la provincia de Valladolid, dentro de la comunidad autónoma de Castilla y León. Está situada a 5 km del municipio, entre los ríos Adaja y Eresma, casi en el punto de unión de ambos ríos y sobre…',41.4378744,-4.7535405,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_Sieteiglesias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182548,'02001','Catedral de San Juan Bautista','religioso','religioso_osm','La catedral de San Juan Bautista es una catedral de culto católico dedicada al patrón san Juan Bautista situada en la ciudad española de Albacete. Tiene sus orígenes en un antiguo templo mudéjar de finales del siglo XIII, sobre el cual se comenzó a levantar en 1515 la actual catedral en estilo renacentista, de…',38.9957016,-1.8559317,'https://es.wikipedia.org/wiki/Catedral_de_Albacete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182549,'02014','Santuario de Nuestra Señora del Rosario','religioso','religioso_osm','El santuario de Nuestra Señora del Rosario se encuentra situado en el cerro del Castillo y dentro del casco urbano de Hellín (Provincia de Albacete, España). En su interior se alberga a la imagen de Nuestra Señora del Rosario, que es patrona de esta localidad.',38.5117615,-1.7042986,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_del_Rosario_(Hellín)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182550,'08132','Mare de Déu dels Torrents','religioso','religioso_osm','La Mare de Déu dels Torrents és un santuari al terme municipal de l''Espunyola (Berguedà) catalogat a l''Inventari del Patrimoni Arquitectònic de Catalunya. Documentat ja al segle xiv, tot i que la devoció sembla fins i tot anterior.',42.0426743,1.728904,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_dels_Torrents');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182551,'33033','Iglesia de la Virgen de Bendueños','religioso','religioso_osm','El Santuario de la Virgen de Bendueños, también llamado de Nuestra Señora de Bendueños, es un lugar de culto de la Iglesia católica situado en la localidad de Bendueños (concejo de Lena), en la zona central de Asturias. Se encuentra camino del sur, hacia el puerto de Pajares por la N-630, a unos 5 km de Pola de…',43.0904199,-5.8185185,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_de_Bendueños');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182552,'28045','Basílica de la Asunción de Nuestra Señora','religioso','religioso_osm','La basílica de la Asunción de Nuestra Señora de Colmenar Viejo es un templo gótico con un impresionante campanario y un magnífico retablo mayor de estilo renacentista, realizado entre 1563 y 1579, en madera dorada, policromada y estofada excepto el frontal de altar, en alabastro, centrándose su iconografía en la…',40.6577174,-3.7663465,'https://es.wikipedia.org/wiki/Basílica_de_la_Asunción_de_Nuestra_Señora_(Colmenar_Viejo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182553,'08025','Mare de Déu de Rocaprevera','religioso','religioso_osm','El Santuari de la Mare de Déu de Rocaprevera és un conjunt religiós situat al Puig de les Tres Creus sobre la vila de Torelló en la comarca d''Osona. Originalment un oratori del segle xiii, ha estat reconstruïda tres vegades, com a capella romànica al segle xv i com a capella popular al segle xviii.',42.0419768,2.2599822,'https://ca.wikipedia.org/wiki/Santuari_de_Rocaprevera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182554,'25183','Mare de Déu de la Candelera','religioso','religioso_osm','La Mare de Déu de la Candelera d''Olp, modernament la Purificació, és l''església parroquial del poble d''Olp, en el terme municipal de Sort, a la comarca del Pallars Sobirà. Pertanyia a l''antic terme d''Enviny.',42.4301564,1.1147877,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Candelera_d''Olp');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182555,'25577','Sant Pere de l''Abadia','religioso','religioso_osm','Sant Pere de l''Abadia, o Sant Pere de Son, és una antiga església romànica del poble de Son, en el terme municipal d''Alt Àneu, a la comarca del Pallars Sobirà. Està desafectada des d''antic; durant molts anys serví d''escola, residència dels mestres, ajuntament, rectoria (d''on el nom d''Abadia).',42.6200891,1.0957868,'https://ca.wikipedia.org/wiki/Sant_Pere_de_l''Abadia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182556,'25034','Mare de Déu de l''Assumpció','religioso','religioso_osm','La Mare de Déu de l''Assumpció d''Artesa de Segre és una església de les darreres tendències d''Artesa de Segre (Noguera) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8961412,1.0482221,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_l''Assumpció_d''Artesa_de_Segre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182557,'47027','Monasterio de Santa María de Palazuelos','religioso','religioso_osm','El monasterio de Santa María de Palazuelos o de Nuestra Señora de Palazuelos fue un monasterio cisterciense del primer tercio del siglo XIII, construido en el valle del río Pisuerga, muy cerca de su orilla derecha, en lo que fue la villa de Palazuelos —hoy despoblado—, entre los términos actuales de Corcos del…',41.752817,-4.6335658,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_Palazuelos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182558,'41091','Iglesia Nuestra Señora de la O','religioso','religioso_osm','La iglesia de Nuestra Señora de la O es un templo católico situado en la calle Castilla, en el barrio de Triana, Sevilla, Andalucía, España.',37.3871373,-6.0051372,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_O_(Sevilla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182559,'19162','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo católico con base románica, del siglo XII y amplias reformas realizadas en el siglo XVIII, situado en Luzaga (Guadalajara, España). Contiene las imágenes de la Virgen de la Quinta Angustia y de San Zenón, patrones del pueblo.',40.9737005,-2.4457439,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Luzaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182560,'42035','Colegiata de Santa María del Mercado','religioso','religioso_osm','La colegiata de Santa María del Mercado es una iglesia de la localidad española de Berlanga de Duero, en la provincia de Soria.',41.4648696,-2.86104,'https://es.wikipedia.org/wiki/Colegiata_de_Santa_María_del_Mercado');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182561,'50200','Iglesia Nuestra Señora de los Angeles','religioso','religioso_osm','La iglesia de Nuestra Señora de los Ángeles en Paniza (provincia de Zaragoza, España) es una iglesia mudéjar de la segunda mitad del siglo XVI con nave única, capillas laterales entre los contrafuertes y ábside poligonal en alzado, que en el siglo XVII sufrió un cambio de orientación, con la consiguiente…',41.2846162,-1.2125044,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_los_Ángeles_(Paniza)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182562,'42171','Iglesia de Nuestra Señora del Mercado','religioso','religioso_osm','La iglesia de Nuestra Señora del Mercado, en la localidad de Serón de Nágima (Provincia de Soria, comunidad autónoma de Castilla y León, España) fue construida en el siglo XVI en estilo gótico tardío.',41.4963,-2.2012139,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Mercado_(Serón_de_Nágima)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182563,'31232','Catedral de Santa María','religioso','religioso_osm','La catedral de Santa María (Santa María la Mayor) de Tudela (Navarra) es un templo tardorrománico, inspirada en la arquitectura cisterciense, de grandes dimensiones,​ que se comenzó a construir a finales del siglo XII durante el reinado de Sancho VI el Sabio, pasando el testigo a su hijo Sancho VII el Fuerte, que a…',42.0636499,-1.6052331,'https://es.wikipedia.org/wiki/Catedral_de_Tudela');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182564,'31232','Iglesia y convento del Carmen','religioso','religioso_osm','La iglesia y convento del Carmen de Tudela (Navarra) es un templo de finales del siglo XVI, de estilo manierista,​ situado en la esquina que forman la calle Gayarre y Carmen Alta del Casco Antiguo de Tudela, con salida en esta última calle.​',42.0627148,-1.6082456,'https://es.wikipedia.org/wiki/Iglesia_y_convento_del_Carmen_(Tudela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182565,'33007','Basilica Nuestra Señora del Puy','religioso','religioso_osm','Puyko Andre Mariaren basilika Lizarrako goiko aldean dagoen eliza modernoa da, udalerriko bi zaindarietako baten omenez XX. mendean eraikitakoa, XI. mendeko baseliza izan zenaren eta ondorengo tenplu barrokoaren gainean. Lizarra auzoaren gaineko muino baten gainean dago, gaur egungo Lizarra hiriaren jatorrizko…',42.6755826,-2.0300033,'https://eu.wikipedia.org/wiki/Puyko_Andre_Mariaren_basilika');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182566,'25211','Mare de deu de Butsènit','religioso','religioso_osm','Ermita de Butsènit és una església de Lleida protegida com a bé cultural d''interès local.',41.5798951,0.5741097,'https://ca.wikipedia.org/wiki/Ermita_de_Butsènit');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182567,'40101','Ermita de la Virgen de La Aparecida','religioso','religioso_osm','La ermita de la Virgen de la Aparecida es un edificio situado en el despoblado de Mazuelos, del municipio de Valverde del Majano, perteneciente a la provincia de Segovia, en la comunidad autónoma de Castilla y León.',40.9561157,-4.1927557,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_la_Aparecida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182568,'44047','Iglesia de Nuestra Señora de Los Ángeles','religioso','religioso_osm','La iglesia de Nuestra Señora de los Ángeles también denominada iglesia de la Asunción en Burbáguena (Provincia de Teruel, España) es una iglesia barroca del siglo XVIII, construida en sillar combinado con ladrillo en las partes altas (alero, cimborrio y torre) y que forma un volumen destacado y compacto dentro de…',41.0163838,-1.337596,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_los_Ángeles_(Burbáguena)');
