INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182570,'08175','Mare de Déu del Carme de Periques','religioso','religioso_osm','Mare de Déu del Carme de Periques és una església del municipi de Puig-reig (Berguedà) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9774603,1.8854131,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Carme_de_Periques');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182571,'90263','iglesia de la Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia de la Asunción de Nuestra Señora es un edificio situado en la anteiglesia española de Barajuén, en la provincia de Álava.',43.0463726,-2.5594254,'https://es.wikipedia.org/wiki/Iglesia_de_la_Asunción_de_Nuestra_Señora_(Barajuén)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182572,'31232','Iglesia y convento de los Capuchinos','religioso','religioso_osm','El convento de los Capuchinos e iglesia de la Divina Pastora de Tudela (Navarra) es un convento e iglesia de la orden de los capuchinos de finales del siglo XIX,​ situado en la calle del mismo nombre del actual ensanche de Tudela.​',42.0600163,-1.6025862,'https://es.wikipedia.org/wiki/Iglesia_y_convento_de_los_Capuchinos_(Tudela)');
