INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182574,'50297','Iglesia de Nuestra Señora del Carmen','religioso','religioso_osm','La iglesia de Nuestra Señora del Carmen y el colegio mayor «Virgen del Carmen» es un conjunto de edificios de la ciudad española de Zaragoza, en Aragón. Ubicado en el número 8 del paseo de Mª Agustín, su construcción data de la década de 1960, fruto de un proyecto de José Romero.',41.650773,-0.8886867,'https://parroquiadelcarmen.es/','https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Carmen_y_colegio_mayor_Virgen_del_Carmen');
