INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182577,'08022','Mare de Déu dels Arcs','religioso','religioso_osm','El Mare de Déu dels Arcs o Santa Maria dels Arcs és una església de Santa Pau (Garrotxa) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. El santuari dels Arcs és l''hostatgeria per a pelegrins bastida als segles xvii i XVIII i s''hi accedeix per una escalinata també d''època barroca.',42.1412238,2.58526,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Arcs');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182578,'12901','Església de la Mare de Déu del Niño Perdido','religioso','religioso_osm','L''Església Parroquial de la Mare de Déu del Niño Perdido, a Les Alqueries, comarca de la Plana Baixa, és un temple catòlic situat al carrer Mossén Juan Miralles, 9 de l''esmentat municipi. Datat del segle xix, presenta una declaració genèrica com Bé de Rellevància Local segons la Disposició Addicional Cinquena de la…',39.8972043,-0.1138611,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_del_Niño_Perdido');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182579,'40134','Ermita de Nuestra Señora de Rodelga','religioso','religioso_osm','La Virgen de Rodelga o Nuestra Señora de Rodelga es una advocación de la Virgen María venerada en el municipio castellano de Mozoncillo, de la que es patrona.',41.1460206,-4.1634646,'https://es.wikipedia.org/wiki/Virgen_de_Rodelga#La_ermita');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182580,'22906','Nuestra Señora de Treviño','religioso','religioso_osm','La ermita de Nuestra Señora de Treviño es una iglesia del siglo XIII ubicada en la localidad española de Adahuesca, perteneciente a la provincia de Huesca, en Aragón. Está catalogada como Bien de Interés Cultural.',42.1339979,-0.0080768,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_Treviño');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182581,'28055','Iglesia de Nuestra Señora de los Remedios','religioso','religioso_osm','La iglesia de Nuestra Señora de los Remedios es un edificio religioso situado en el municipio español de Estremera, perteneciente a la Comunidad de Madrid, cuya construcción data del siglo xvi.​',40.1848879,-3.1057181,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_los_Remedios_(Estremera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182582,'25171','Mare de Déu dels Socors','religioso','religioso_osm','La Mare de Déu del Socors és una ermita del poble del Pont de Claverol, pertanyent al municipi de Conca de Dalt, al Pallars Jussà. Fins al 1969 formava part del terme municipal de Claverol.',42.2356321,0.9732048,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Socors_(el_Pont_de_Claverol)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182583,'30038','Iglesia de Nuestra Señora de la Salceda','religioso','religioso_osm','La iglesia de Nuestra Señora de la Salceda es un templo católico español que se encuentra ubicado en la población de Las Torres de Cotillas, perteneciente a Murcia. Es de estilo barroco.',38.0295058,-1.2413958,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Salceda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182584,'50215','Ermita de Nuestra Señora de la Torre','religioso','religioso_osm','La Ermita de Nuestra Señora de la Torre, también conocida como Ermita de San Marcos se encuentra situada a los pies del Castillo de la Raya. Su origen posiblemente es el de la iglesia de un poblado, pequeño, junto al castillo.',41.3329296,-2.1571633,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_la_Torre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182585,'17047','Basílica de Santa Maria','religioso','religioso_osm','Santa Maria de Castelló d''Empúries, Catedral de l''Empordà o Catedral de Castelló d''Empúries és una església gòtica situada al barri del Puig Salner del nucli antic de Castelló d''Empúries (Alt Empordà). Fou construït a sobre l''església romànica primitiva, de la qual queden alguns vestigis, com els primers pisos de…',42.2594976,3.0763009,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Castelló_d''Empúries');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182586,'23060','Santuario de la Virgen de la Villa','religioso','religioso_osm','El santuario de Santa María de la Villa y su torre-campanario es un templo católico y espacio de culto ubicado en la ciudad de Martos, Provincia de Jaén (España). En él se venera la imagen de Santa María de la Villa, conocida como La Labradora.',37.7233264,-3.9686262,'https://es.wikipedia.org/wiki/Santuario_de_Santa_María_de_la_Villa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182587,'90512','Santuario da Nosa Señora dos Milagres do Monte Medo','religioso','religioso_osm','O Santuario de Nosa Señora dos Milagres e un templo relixioso situado no Monte Medo, en Baños de Molgas. Foi construído entre 1731 e 1768.',42.2324971,-7.6287245,'https://www.santuariomilagros.com/','https://gl.wikipedia.org/wiki/Santuario_da_Nosa_Señora_dos_Milagres_do_Medo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182588,'17116','Capella de la Mare de Déu del Part','religioso','religioso_osm','La Mare de Déu del Part és una capella d''Osor (Selva) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. La Capella de la Mare de Déu del Part està ubicada sota el Coll de Nafrè a 4 quilòmetres d''Osor seguint el Camí Ral.',41.9583068,2.5405739,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Part');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182589,'17194','Mare de Déu del Far','religioso','religioso_osm','El Santuari del Far és una església de Susqueda (Selva) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. El Santuari de la Mare de Déu del Far corona la punta d''una colossal i impressionant cinglera, de silueta inconfusible, a 1.123 metres d''altitud.',42.0211767,2.5365991,'https://ca.wikipedia.org/wiki/Santuari_del_Far');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182590,'25209','Mare de Déu del Soler','religioso','religioso_osm','La Mare de Déu del Soler és una ermita del poble de Montardit de Baix, al terme municipal de Sort, de la comarca del Pallars Sobirà. Pertanyia a l''antic terme d''Enviny.',42.3920366,1.1246628,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Soler');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182591,'08134','Santuari de la Mare de Déu del Puiggraciós','religioso','religioso_osm','El santuari de Puiggraciós està situat al bell cim del contrafort oriental dels Cingles de Bertí, en el terme municipal del Figueró, a la comarca del Vallès Oriental. Es troba a una altitud de 689,2 metres, una mica abans d''arribar al cim del Puiggraciós, al seu nord-est.',41.7060544,2.2475911,'https://ca.wikipedia.org/wiki/Santuari_de_Puiggraciós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182592,'10100','Iglesia Nuestra Señora del Buen Varón','religioso','religioso_osm','La iglesia de Nuestra Señora del Buen Varón,​ o simplemente iglesia del Buen Varón,​ es el templo parroquial católico del municipio español de Hoyos, en el noroeste de la provincia de Cáceres.',40.1710051,-6.721217,'https://es.wikipedia.org/wiki/Iglesia_del_Buen_Varón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182593,'18022','Iglesia de Nuestra Señora de la Encarnación','religioso','religioso_osm','La Iglesia de la Encarnación es un templo cristiano de la localidad española de Atarfe, en la provincia de Granada.',37.2226656,-3.6885442,'https://es.wikipedia.org/wiki/Iglesia_de_la_Encarnación_(Atarfe)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182594,'41039','Iglesia de Nuestra Señora del Carmen','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora del Carmen de Écija fue un antiguo convento perteneciente a la Orden de Carmelitas Calzados. Actualmente, el templo es una iglesia parroquial desde la década de 1950,​ y las antiguas dependencias del convento forman parte del Colegio Diocesano Santa María Nuestra Señora.',37.540037,-5.0852298,'https://es.wikipedia.org/wiki/Iglesia_del_Carmen_(Écija)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182595,'18049','Iglesia de Nuestra Señora de la Anunciación','religioso','religioso_osm','La iglesia de la Anunciación de Cogollos de Guadix (provincia de Granada) se construyó en un primer momento en el siglo XVI con módulo sencillo y técnica mudéjar fue posteriormente ampliada, apareciendo hoy con una particular «desproporcionada escala», con interesante armadura mudéjar en su nave principal y…',37.2252511,-3.1602412,'https://es.wikipedia.org/wiki/Iglesia_de_la_Anunciación_(Cogollos_de_Guadix)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182596,'19181','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo católico situado en la localidad de Alpedroches (Guadalajara, España). Se encuentra en la calle Barrio de Abajo, 1,​ a la entrada de la localidad a la que se accede desde la carretera GU-145.',41.2327186,-2.9255898,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Alpedroches)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182597,'29043','Ermita de Nuestra Señora de la Candelaria','religioso','religioso_osm','La ermita de Nuestra Señora de la Candelaria es un templo cristiano situado en el municipio de Colmenar (en la provincia de Málaga, España), declarado bien de interés cultural en 1996. Se trata de una edificación de estilo barroco, construida durante los siglos XVII y XVIII, de autor desconocido.',36.9029959,-4.3326556,'https://es.wikipedia.org/wiki/Ermita_de_la_Candelaria_(Colmenar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182598,'11030','Parroquia de Nuestra Señora de la O','religioso','religioso_osm','La iglesia Mayor Parroquial de Nuestra Señora de la O de Rota, en la provincia de Cádiz (Andalucía, España), es un templo católico levantado en el siglo XVI en estilo gótico-renacentista y cuyo mobiliario es mayormente de época barroca.',36.6168013,-6.3574952,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_O_(Rota)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182599,'22142','Ermita de La Virgen del Llano','religioso','religioso_osm','Mare de Déu del Llano (o del Pla) és una ermita romànica de final de segle xii, situada al municipi de Capella (Ribagorça), dins de la Franja de Ponent a la comarca de la Ribagorça. La seva planta és una nau i absis cilíndric i capelles laterals, amb un campanar en espadanya de dos ulls centrats.',42.2042953,0.4722305,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Llano');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182600,'46169','Iglesia Parroquial de Nuestra Señora de los Ángeles','religioso','religioso_osm','L''Església Parroquial de la Mare de Déu dels Àngeles és un temple catòlic situat al municipi de Mislata. És Bé de Rellevància Local amb identificador nombre 46.14.169-001.',39.475658,-0.4167686,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_dels_Àngels_de_Mislata');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182601,'43038','Mare de Déu del Camí','religioso','religioso_osm','La Mare de Déu del Camí és una ermita de Cambrils, antiga església parroquial segons apareix documentada l''any 1214. L''edifici actual és renaixentista tardà del 1778 i es va construir amb pedres procedents de la pedrera de Montjuïc.',41.0715121,1.0511487,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Camí_(Cambrils)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182602,'24148','Santuario de Fátima','religioso','religioso_osm','El Santuario de la Virgen de Fátima de la ciudad de Astorga, que antes fue iglesia de San Julián, es un templo edificado a finales del siglo XII, renovado en el siglo XVIII y restaurado en el siglo XX, que aún conserva restos románicos, como la portada de la fachada occidental.',42.4537428,-6.0535039,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_de_Fátima_(Astorga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182603,'17148','Mare de Déu de Montcorb','religioso','religioso_osm','La Mare de Déu de Montcorb és una església de Riudarenes (Selva) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8098989,2.7013362,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Montcorb');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182604,'12032','Basílica El Salvador','religioso','religioso_osm','La basílica de El Salvador, situada en la plaza de la Iglesia de Burriana (Provincia de Castellón, España), es un edificio de estilo gótico valenciano que comenzó a construirse a finales del siglo XIII. En el siglo XVII tuvo una intervención barroca que modificó la imagen de la iglesia; en el siglo XVIII se levantó…',39.8895359,-0.0836168,'https://turisme.burriana.es/listing/el-salvador-basilica-manor/','https://es.wikipedia.org/wiki/Basílica_de_El_Salvador_(Burriana)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182605,'12093','Monestir de Santa María de Benifassà','religioso','religioso_osm','El Reial convent de Santa Maria de Benifassà és un monestir fundat per l''orde del Cister, actualment ocupat per monges cartoixanes, i situat dins del Parc Natural de la Tinença de Benifassà, al terme municipal de La Pobla de Benifassà, Baix Maestrat (País Valencià). El monestir està situat a la vora de la carretera…',40.6767493,0.1986343,'https://ca.wikipedia.org/wiki/Monestir_de_Santa_Maria_de_Benifassà');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182606,'42076','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La Iglesia de Nuestra Señora de la Asunción de la localidad soriana de Deza, (Castilla y León), se encuentra en la zona Oeste de la localidad.',41.4634305,-2.0220781,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Deza)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182607,'25227','Mare de Déu de Far','religioso','religioso_osm','La Mare de Déu de Fa és una ermita del poble d''Espui, en el terme municipal de la Torre de Cabdella, del Pallars Jussà. Està situada a considerable alçada en un contrafort oriental del Tossal de la Collada Gran, damunt de la vall del Flamisell.',42.4462926,0.9838214,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Far');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182608,'43099','Església de la Mare de Déu de l''Assumpció','religioso','religioso_osm','La Mare de Déu de l''Assumpció és una església dins del nucli urbà de la població de la Palma d''Ebre, al bell mig del terme i delimitada pels carrers de l''Església, de Dins i Baronia de Barcelona i la plaça de l''Església. L''església nova de Palma d''Ebre va ser començada a la fi del segle xviii, segurament pel poc…',41.2827398,0.6662963,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_de_l''Assumpció_(la_Palma_d''Ebre)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182609,'05041','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La abadía de Nuestra Señora de la Asunción es una abadía ubicada en la localidad española de Burgohondo, perteneciente a la provincia de Ávila.',40.4161867,-4.7857771,'https://es.wikipedia.org/wiki/Abadía_de_Burgohondo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182610,'08017','Mare de Déu de Lurdes','religioso','religioso_osm','Santuari de Lourdes és una església eclèctica de Prats de Lluçanès (Osona) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.0087333,2.0385716,'https://ca.wikipedia.org/wiki/Santuari_de_Lourdes_(Prats_de_Lluçanès)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182611,'08233','Mare de Déu del Roser','religioso','religioso_osm','La Capella del Roser és una obra de Sant Pere de Torelló (Osona) protegida com a Bé Cultural d''Interès Local.',42.0937352,2.3283153,'https://ca.wikipedia.org/wiki/Capella_del_Roser_(Sant_Pere_de_Torelló)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182612,'02001','Iglesia Nuestra Señora de las Angustias','religioso','religioso_osm','La capilla de las Adoratrices o capilla de las Angustias es un templo religioso de culto católico situado en la ciudad española de Albacete.',38.9863555,-1.8510682,'https://es.wikipedia.org/wiki/Capilla_de_las_Adoratrices');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182613,'25115','Mare de Déu dels Àngels','religioso','religioso_osm','Santa Maria de Figuerola d''Orcau és l''església parroquial de Figuerola d''Orcau, al terme municipal d''Isona i Conca Dellà (Pallars Jussà). Està situada ben bé al centre del poble, dins del seu recinte murat.',42.1301856,0.9946365,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Figuerola_d''Orcau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182614,'47186','Iglesia de Nuestra Señora del Carmen Extramuros','religioso','religioso_osm','El santuario de Nuestra Señora del Carmen Extramuros es un templo católico situado a las afueras de la ciudad de Valladolid (Castilla y León, España). De estilo básicamente barroco (aunque con la fachada reformada en los años sesenta del siglo XX), fue levantada entre los siglos XVI y XVIII como parte del antiguo…',41.6704213,-4.7016786,'http://carmenextramuros.blogspot.com.es/','https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_del_Carmen_Extramuros_(Valladolid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182615,'08087','Mare de Déu del Grau','religioso','religioso_osm','Mare de Déu del Grau és un edifici del municipi de Gallifa (Vallès Occidental) protegida com a bé cultural d''interès local.',41.6783909,2.1289207,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Grau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182616,'47098','Ermita de Nuestra Señora de la Vega','religioso','religioso_osm','La ermita de Nuestra Señora de la Vega es un templo católico ubicado en la localidad de Mucientes, Provincia de Valladolid, Castilla y León, España.',41.7412552,-4.7547562,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_de_la_Vega_(Mucientes)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182617,'25172','Mare de Déu de la Vedrenya','religioso','religioso_osm','Mare de Déu de la Vedrenya és una ermita del municipi d''Artesa de Segre (Noguera) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. Es troba al costat de la carretera que mena a Montmagastre, entitat de població del municipi d''Artesa de Segre.',41.9600525,1.1096938,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Vedrenya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182618,'25150','Mare de Déu de Refet','religioso','religioso_osm','Mare de Déu de Refet és una església de Seró, al municipi d''Artesa de Segre (Noguera) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya. Està situada al nord de Seró, a l''indret de Refet, als peus de l''altiplà de la Força.',41.8885791,1.1187655,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Refet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182619,'03013','Iglesia Parroquial de Nuestra Señora de Belén','religioso','religioso_osm','L''església parroquial de la Mare de Déu de Betlem és un edifici històric de la localitat de Crevillent, a la comarca valenciana del Baix Vinalopó. Pertany a la diòcesi d''Oriola, del qual és el temple més gran, i té la categoria de Bé de Rellevància Local, amb el codi 03.33.059-001.',38.2485344,-0.8083086,'https://ca.wikipedia.org/wiki/Església_parroquial_de_la_Mare_de_Déu_de_Betlem_(Crevillent)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182620,'08003','Parròquia Basílica de Santa Maria del Pi','religioso','religioso_osm','L''església de Santa Maria del Pi, o simplement del Pi, és una basílica gòtica situada a la plaça del Pi de Barcelona, declarada bé cultural d''interès nacional.',41.3820422,2.1739172,'https://www.basilicadelpi.cat','https://ca.wikipedia.org/wiki/Santa_Maria_del_Pi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182621,'08305','Basílica de Santa Maria','religioso','religioso_osm','La Basílica de Santa Maria de Vilafranca és un edifici religiós del municipi de Vilafranca del Penedès (Alt Penedès). Està situat a la Plaça de Jaume I, al centre del nucli medieval de la població.',41.3470493,1.697353,'https://ca.wikipedia.org/wiki/Basílica_de_Santa_Maria_de_Vilafranca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182622,'43166','Mare de Déu de Paretdelgada','religioso','religioso_osm','L''ermita de Santa Maria de Paretdelgada és un edifici religiós situat al terme de la Selva del Camp i a uns 4 km del poble, a l''antic camí de Vilallonga. La primitiva imatge venerada era una marededeu romànica amb el Nen a la falda.',41.2136891,1.1754484,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Paretdelgada');
