INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182625,'40121','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción y San Sebastián es un edificio católico ubicado en el municipio de Martín Muñoz de las Posadas (Segovia) que fue construido en estilo gótico en el siglo XVI, sustituyendo al antiguo templo románico del siglo XIII. Tiene una sola nave bastante larga. La portada occidental…',40.9964304,-4.5963775,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Martín_Muñoz_de_las_Posadas)');
