INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182641,'47117','Iglesia de Nuestra Señora','religioso','religioso_osm','La iglesia de Nuestra Señora es un templo católico español situado en Piña de Esgueva provincia de Valladolid; es la iglesia parroquial del pueblo cuya construcción se remonta a finales del siglo XII o principios del XIII, época del románico.',41.7298059,-4.4280726,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_(Piña_de_Esgueva)');
