INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182655,'09078','Iglesia de la Natividad de Nuestra Señora','religioso','religioso_osm','La iglesia de la Natividad de Nuestra Señora es una iglesia parroquial católica de estilo románico situada en la localidad burgalesa de Cascajares de la Sierra (España). Está dedicada a la Natividad de María.​​ Se trata de un edificio de sillería y mampostería de tres naves.',42.0620787,-3.3993579,'https://es.wikipedia.org/wiki/Iglesia_de_la_Natividad_de_Nuestra_Señora_(Cascajares_de_la_Sierra)');
