INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182657,'09396','Iglesia de la Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es una iglesia parroquial católica del siglo XVI situada en la localidad burgalesa de Tubilla del Lago (España). Está dedicada a Nuestra Señora de la Asunción, patrona de la localidad.​​ Se trata de un templo de una sola nave de planta rectangular con bóveda de crucería.',41.8013426,-3.5863552,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Tubilla_del_Lago)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182658,'03012','Monasterio de la “Mare de Déu del Miracle”','religioso','religioso_osm','El Monestir de la Mare de Déu del Miracle de Cocentaina (Comtat, País Valencià) ocupa part del Palau dels Comtes i, des del punt de vista artístic, el Monestir és la part més interessant. Es va iniciar la seua construcció el 20 de setembre de 1656 i el 20 de gener de 1670 era traslladada la Mare de Déu del Miracle…',38.7436845,-0.4408357,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Miracle_de_Cocentaina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182659,'31254','Virgen del Portal','religioso','religioso_osm','Atariko Andre Mariaren eliza Aragoiko Erriberako Alesbes udalerrian kokatutako XVI. mendeko kristiau basilika bat da. Barroko estiloa ditu.',42.2779475,-1.7473429,'https://eu.wikipedia.org/wiki/Atariko_Andre_Mariaren_eliza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182660,'38023','Santuario del Cristo de La Laguna','religioso','religioso_osm','El Real Santuario del Santísimo Cristo de La Laguna es un templo católico situado en la ciudad de San Cristóbal de La Laguna (Tenerife, España). El Real Santuario es el convento franciscano de San Miguel de las Victorias y tiene la categoría de bien de interés cultural.',28.4933478,-16.3125898,'https://es.wikipedia.org/wiki/Real_Santuario_del_Santísimo_Cristo_de_La_Laguna');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182661,'14042','Basílica de San Juan de Ávila','religioso','religioso_osm','La basílica de San Juan de Ávila es una basílica pontificia menor situada en la localidad de Montilla, Córdoba (España). La antigua iglesia de la Encarnación y posteriormente Santuario de San Juan de Ávila fue elevada a la categoría de basílica menor por decreto De titulo Basilicae Minoris de fecha 20 de junio de…',37.5888003,-4.6382396,'https://es.wikipedia.org/wiki/Basílica_de_San_Juan_de_Ávila');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182662,'13064','Ermita de Nuestra Señora de Alarcos','religioso','religioso_osm','El santuario de Nuestra Señora de Alarcos es una ermita de estilo gótico localizada en Alarcos (provincia de Ciudad Real - España) declarada Bien de Interés Cultural en 1980.​​​ De estilo gótico y planta basilical, sobre su puerta se abre un gran rosetón de tracería.',38.9571754,-4.0113357,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_Alarcos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182663,'17171','Mare de Déu de Palau','religioso','religioso_osm','La Mare de Déu de Palau és una església romànica del veïnat de Palau (municipi de Sant Llorenç de la Muga, Alt Empordà) protegida com a bé cultural d''interès local. L''església de Palau és d''una sola nau amb absis semicircular.',42.3072118,2.7388991,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Palau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182664,'25088','Mare de Déu de les Peces','religioso','religioso_osm','L''església de la Mare de Déu de les Peces o Santa Maria de les Peces és d''estil romànic i està situada sobre un turó pròxim a la població d''Alàs i Cerc, a la comarca de l''Alt Urgell. Està inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.3515273,1.5180612,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Peces');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182665,'08128','Mare de Déu del Consol','religioso','religioso_osm','La Mare de Déu del Consol de la Coma és una capella del poble de Monistrol de Calders, a la comarca del Moianès. Està situada en el mas de la Coma, al nord del poble, a l''extrem del terme municipal, llindant amb Calders i Moià.',41.7806696,2.0310298,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Consol_de_la_Coma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182666,'09160','Santuario de la Virgen de la Cueva','religioso','religioso_osm','El santuario de la Virgen de la Cueva es un inmueble del municipio español de Hontangas, en la provincia de Burgos. Cuenta con el estatus de bien de interés cultural.',41.5829657,-3.7958082,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_de_la_Cueva_(Hontangas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182667,'43096','Mare de Déu de la Mercè','religioso','religioso_osm','Mare de Déu de la Mercè és una església del municipi de la Morera de Montsant (Priorat) protegida com a bé cultural d''interès local.',41.2481789,0.8108148,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Mercè_(la_Morera_de_Montsant)');
