INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182670,'44066','Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo católico situado en la localidad aragonesa de Castel de Cabra (España). En 2002 fue declarado Bien Catalogado.​ Se trata de una edificación de estilo gótico-renacentista construido entre los siglos XIII y XVII. El edificio está realizado en mampostería y…',40.80263,-0.6964622,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Castel_de_Cabra)');
