INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182672,'12135','Ermitori de la Mare de Déu de Gràcia','religioso','religioso_osm','El Ermitorio de Nuestra Señora de Gracia, situado en el municipio de Villarreal (Provincia de Castellón, España), es un edificio representativo de la arquitectura popular mediterránea. Alberga, junto a una importante muestra de azulejería medieval, renacentista y barroca y un museo etnológico, un gabinete de…',39.9617941,-0.1162496,'https://es.wikipedia.org/wiki/Ermitorio_de_la_Virgen_de_Gracia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182673,'08101','Mare de Déu dels Desemparats','religioso','religioso_osm','La Mare de Déu dels Desemparats és l''església parroquial del barri de la Torrassa a la ciutat de l''Hospitalet de Llobregat (Barcelonès), protegida com a bé cultural d''interès local. L''església parroquial, sota l''advocació de la Mare de Déu dels Desemparats, fou construïda per l''arquitecte municipal Manuel Puig…',41.3705772,2.1226731,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Desemparats_(l''Hospitalet_de_Llobregat)');
