INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182676,'17087','Santuari Mare de Déu dels Angels','religioso','religioso_osm','El Santuari dels Àngels és un dels santuaris més visitats i de més devoció de les terres gironines, i s''hi venera la Mare de Déu dels Àngels. És al cim del Puig Alt al Massís de les Gavarres, al terme municipal de Sant Martí Vell (Gironès).',41.9847906,2.9087777,'https://ca.wikipedia.org/wiki/Santuari_dels_Àngels');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182677,'25177','Mare de Déu de la Gorga','religioso','religioso_osm','La Mare de Déu de la Gorga és un santuari del municipi de Preixens (Noguera) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya. És situat al mig dels camps de conreu que hi ha al nord-est del poble de Preixens a prop del poble de Mafet del municipi d''Agramunt.',41.8212484,1.0772025,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Gorga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182678,'39094','Colegiata de San Martín de Elines','religioso','religioso_osm','La iglesia conocida como colegiata de San Martín de Elines, situada en la población de San Martín de Elines (Cantabria), es la más destacada de Valderredible por su tamaño, monumentalidad y belleza. Durante la Edad Media constituyó el monasterio principal del valle.',42.8289174,-3.8693107,'https://es.wikipedia.org/wiki/Colegiata_de_San_Martín_de_Elines');
