INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182685,'46110','Iglesia de la Virgen de la Salud','religioso','religioso_osm','L''Església Parroquial de la Mare de Déu de la Salut és un temple catòlic a la plaça de l''Església de Xirivella a l''Horta Oest. Està catalogat com a bé de rellevància local amb codi 46.14.110-001 segons la Disposició Addicional Cinquena de la Llei 5/2007, de 9 de febrer, de la Generalitat Valenciana, de modificació…',39.465878,-0.4253259,'https://ca.wikipedia.org/wiki/Església_Parroquial_de_la_Mare_de_Déu_de_la_Salut');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182686,'09256','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es una iglesia parroquial católica románica situada en la localidad burgalesa de Boada de Roa (España). Desde el siglo XVI o XVII está dedicada a la Asunción de la Virgen María, aunque originalmente se denominaba Nuestra Señora de la Antigua.​​ Se trata de un templo de…',41.7297968,-3.9755998,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Boada_de_Roa)');
