INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182689,'28106','Iglesia Parroquial de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción de Parla, conocida popularmente como iglesia vieja, fue construida a comienzos del siglo XVI y reconstruida a lo largo del siglo XX. Rendía culto a la antigua patrona del municipio, Nuestra Señora de Agosto, también denominada Nuestra Señora de la Asunción.',40.2378022,-3.7709339,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Parla)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182690,'17901','Mare de Déu de l''Esperança','religioso','religioso_osm','La Mare de Déu d''Esperança és un santuari i ermita a poc menys d''un kilòmetre al nord de la vila de Cruïlles davant de la qual es dreça una creu de terme. El paratge és conegut popularment amb el nom d''"Esperança" (sense l''article).',41.9639073,3.0118574,'https://marededeuesperanca.cat','https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_l''Esperança');
