INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182693,'47186','Iglesia de Nuestra Señora Reina de la Paz','religioso','religioso_osm','La iglesia de Nuestra Señora Reina de la Paz es un templo moderno ubicado en la plaza de España de Valladolid que pertenece a la Orden de los Capuchinos.',41.6484547,-4.7248824,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_Reina_de_la_Paz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182694,'23055','Basílica de Santa María la Mayor','religioso','religioso_osm','La basílica de Santa María la Mayor (en italiano: Basilica di Santa Maria Maggiore), también conocida como basílica de Santa María de las Nieves y Basílica Liberiana, es una basílica católica situada en Roma, Italia. Es una de las cuatro basílicas mayores y una de las cinco basílicas patriarcales asociadas con la…',38.0923265,-3.634696,'https://es.wikipedia.org/wiki/Basílica_de_Santa_María_la_Mayor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182695,'16078','Convento de San Felipe Neri','religioso','religioso_osm','El convento de San Felipe Neri, en Cuenca (España), construcción dirigida por José Martín, sobre trazas dadas por Felipe Bernardo Mateo, maestro mayor de la diócesis de Cuenca. El Oratorio de San Felipe Neri fue construido en 1739.',40.0755767,-2.1321933,'https://es.wikipedia.org/wiki/Convento_de_San_Felipe_Neri_(Cuenca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182696,'29067','Abadía de Santa Ana','religioso','religioso_osm','La antigua Abadía de Santa Ana de Recoletas Bernardas del Císter, más conocida como la Abadía del Císter, es un edificio situado en el centro histórico de la ciudad española de Málaga.',36.7208945,-4.4178971,'https://es.wikipedia.org/wiki/Abadía_del_Císter');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182697,'09191','Iglesia de la Natividad de Nuestra Señora','religioso','religioso_osm','La iglesia de Nuestra Señora de la Natividad es un templo católico de la localidad española de Lara de los Infantes, en la provincia de Burgos.',42.1232651,-3.4442929,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Natividad_(Lara_de_los_Infantes)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182698,'12139','Ermita de la Mare de Déu de Loreto','religioso','religioso_osm','L''ermita de Nostra Senyora de Loreto de Vistabella del Maestrat, a la comarca de l''Alt Maestrat, és un lloc de culte declarat genèricament com Bé de Rellevància Local, segons la Disposició Addicional Cinquena de la Llei 5/2007, de 9 de febrer, de la Generalitat, de modificació de la Llei 4/1998, d''11 de juny, del…',40.2931227,-0.2943188,'https://ca.wikipedia.org/wiki/Ermita_de_la_Mare_de_Déu_de_Loreto_(Vistabella_del_Maestrat)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182699,'09183','Iglesia de la Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia de la Asunción de Nuestra Señora,​ templo parroquial de la población de Jaramillo de la Fuente (Burgos, Castilla y León, España), es un edificio de estilo románico que responde a la tipología comarcal conocida como la Escuela de la Sierra.',42.1160672,-3.313357,'https://es.wikipedia.org/wiki/Iglesia_de_la_Asunción_de_Nuestra_Señora_(Jaramillo_de_la_Fuente)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182700,'08103','Mare de Déu de la Sala','religioso','religioso_osm','La Mare de Déu de la Sala o Santa Maria de la Sala és una ermita romànica al SE del terme municipal de Jorba (l''Anoia) construïda sobre un petit planell enlairat prop de l''Anoia i del mas de Can Cansalada.',41.5894321,1.5553853,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Sala');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182701,'29067','Iglesia de Nuestra Señora de Fátima','religioso','religioso_osm','La iglesia de Nuestra Señora de Fátima es un templo cristiano católico de la ciudad de Málaga, Andalucía (España). Situado en la margen derecha del río Guadalmedina, en el barrio de La Trinidad, fue construido en 1961, según el diseño del arquitecto Fernando Morilla Cabello.',36.7240436,-4.4266341,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Fátima_(Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182702,'08251','Mare de Déu de la Bleda','religioso','religioso_osm','Santa Maria de la Bleda és una església del veïnat del mateix nom al municipi de Santa Margarida i els Monjos (Alt Penedès), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.3435654,1.6608528,'https://ca.wikipedia.org/wiki/Santa_Maria_de_la_Bleda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182703,'25105','Mare de Déu del Roser','religioso','religioso_osm','Mare de Déu del Roser de Granyena és una obra de Granyena de les Garrigues (Garrigues) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.4342836,0.6541139,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_de_Granyena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182704,'12006','Església de la Mare de Déu dels Desemparats (Benitandús)','religioso','religioso_osm','L''església de la Mare de Déu dels Desemparats de Benitandús és un temple catòlic situat tot just a l''entrada del poble, a la vora del riu de Veo. Amb la consideració d''ermita, depèn eclesiàsticament de l''església de sant Miquel Arcàngel de l''Alcúdia de Veo, el cap municipal.',39.9300516,-0.336204,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_dels_Desemparats_(Benitandús)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182705,'12006','Església de la Mare de Déu de l''Assumpció','religioso','religioso_osm','La iglesia de la Virgen María de la Asunción de Veo (Alcudia de Veo, provincia de Castellón, España) es un templo católico situado al centro del pueblo, en la plaza de san Antonio Abad, 1. Forma parte del arciprestazgo de la Virgen María de Esperanza, dentro de la diócesis de diócesis de Segorbe-Castellón, y es…',39.9185203,-0.3400681,'https://es.wikipedia.org/wiki/Iglesia_de_la_Virgen_de_la_Asunción_(Veo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182706,'39093','Real Santuario de Montesclaros','religioso','religioso_osm','El Real Santuario de Montesclaros es un cenobio dominico situado en el término municipal de Valdeprado del Río (Cantabria, España). Se ubica a media ladera entre el Pico Solaloma y el río Ebro, en un leve saliente del terreno desde el que se domina una extensa área de terreno que se pierde por los terrenos de Los…',42.9314768,-4.0497755,'https://es.wikipedia.org/wiki/Real_Santuario_de_Montesclaros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182707,'29067','Iglesia del Santo Cristo de la Salud','religioso','religioso_osm','La iglesia del Santísimo Cristo de la Salud es una iglesia del culto católico situada en la ciudad andaluza de Málaga, España. Este edificio data de los siglos XVI y XVII y fue construido por la Compañía de Jesús.',36.7214318,-4.4225673,'https://www.andalucia.org/es/malaga-turismo-cultural-iglesia-del-santo-cristo-de-la-salud','https://es.wikipedia.org/wiki/Iglesia_del_Santo_Cristo_de_la_Salud_(Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182708,'29067','Iglesia del Sagrado Corazón','religioso','religioso_osm','La iglesia del Sagrado Corazón está situada en la Plaza de San Ignacio de Loyola del centro histórico de Málaga, España. Es una obra neogótica construida en 1920, según el proyecto trazado en enero de 1907 por el arquitecto Fernando Guerrero Strachan, por encargo de los jesuitas.',36.721783,-4.4234499,'https://es.wikipedia.org/wiki/Iglesia_del_Sagrado_Corazón_(Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182709,'28079','Parroquia Virgen de la Paloma y San Pedro el Real','religioso','religioso_osm','La iglesia de la Paloma es el nombre popular que recibe la iglesia de la parroquia de San Pedro el Real, un templo católico situado en la ciudad española de Madrid, en la calle de la Paloma. Es parte de las celebraciones religiosas de la verbena de la Paloma.',40.4083227,-3.7116152,'https://es.wikipedia.org/wiki/Iglesia_de_la_Paloma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182710,'10059','Nuestra Señora de Almocóbar','religioso','religioso_osm','La iglesia de Nuestra Señora de Almocóbar o de la Asunción es una iglesia parroquial católica del siglo XVI situada en la localidad cacereña de Casillas de Coria (España).​ Se trata de un templo de una sola nave, de mampostería de pizarra y con sillería en los ángulos. Alrededor del edificio cuenta con contrafuertes.',39.9659851,-6.6365341,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Almocóbar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182711,'09410','Iglesia de la Asunción de Nuestra Señora','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un edificio situado en la localidad española de Partearroyo, en la provincia de Burgos.',43.1489268,-3.2840155,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Partearroyo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182712,'12038','Ermita de la Mare de Déu de la Font de Castellfort','religioso','religioso_osm','La ermita de la Virgen de la Fuente situada en el término municipal de Castellfort (Provincia de Castellón, España) en la carretera de Castellfort a Ares es un edificio religioso construido entre los siglos XVI y XVII de estilo barroco.',40.4766043,-0.1727011,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_la_Fuente_(Castellfort)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182713,'23050','Basílica Menor de San Ildefonso','religioso','religioso_osm','La basílica menor de la Sacra Iglesia Parroquial de San Ildefonso es un templo cristiano católico de Jaén. Fue erigido en 1248 en el arrabal San Ildefonso, creado tras la ampliación del recinto amurallado de la ciudad.',37.7665702,-3.7864945,'https://basilicasanildefonso.es/','https://es.wikipedia.org/wiki/Basílica_de_San_Ildefonso_(Jaén)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182714,'25222','Mare de Déu dels Solés','religioso','religioso_osm','La Mare de Déu de Solers és un santuari del municipi noguerenc de Tiurana, al Segre Mitjà, inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9760852,1.2554491,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Solers');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182715,'11024','Parroquia Nuestra Señora de la Encarnación','religioso','religioso_osm','La iglesia de Nuestra Señora de la Encarnación es un templo católico de estilo neoclásico situado en el municipio de Olvera (provincia de Cádiz, España) se ubica en la plaza de la Iglesia y es uno de los principales monumentos de la localidad, elevándose su silueta sobre el perfil urbano. De monumental fachada de…',36.9352978,-5.2682665,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Encarnación_(Olvera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182716,'50139','Ermita de Nuestra Señora de los Dolores','religioso','religioso_osm','La ermita de la Virgen de los Dolores es una ermita barroca situada en la localidad zaragozana de Letux (España). Se encuentra fuera de la localidad, junto a la carretera entre Letux y Lagata.',41.2502941,-0.8023179,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_los_Dolores_(Letux)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182717,'25161','la Nativitat de la Mare de Déu de Sossís','religioso','religioso_osm','La Nativitat de la Mare de Déu de Sossís és l''església de Sossís, pertanyent al municipi de Conca de Dalt, al Pallars Jussà, dins de l''antic terme de Claverol. Es tracta d''una església petita, situada a la part baixa del poble, a ponent.',42.2530835,0.9855842,'https://ca.wikipedia.org/wiki/La_Nativitat_de_la_Mare_de_Déu_de_Sossís');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182718,'43044','Mare de Déu de Pallerols','religioso','religioso_osm','Mare de Déu de Pallerols és una obra de la Sénia (Montsià) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',40.6782878,0.2841857,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Pallerols_(la_Sénia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182719,'21046','Iglesia Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de la Asunción es un templo católico que se encuentra en el municipio de Bonares, provincia de Huelva (España). Esta iglesia parroquial esta bajo el patrocinio de la Asunción de la Virgen.',37.3211896,-6.6838319,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Bonares)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182720,'90893','Mare de Déu de l''Esperança','religioso','religioso_osm','La Mare de Déu de l''Esperança de Ferreres és una església de Ferreres, al municipi de Flaçà (Gironès), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',42.044962,2.9721058,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_l''Esperança_de_Ferreres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182721,'16042','Santuario Virgen de la Loma','religioso','religioso_osm','El santuario de la Virgen de la Loma situado en el término municipal de Campillo de Altobuey (provincia de Cuenca, España) es un conjunto que consta de templo, cuerpo conventual y huerta, que empezó su andadura como hospicio de caminantes peregrinos y pobres, a caballo entre los siglos XVII y XVIII. Se construyó al…',39.6053615,-1.7894489,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_de_la_Loma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182722,'90467','Convento de Caño Santo','religioso','religioso_osm','El convento de Caños Santos se sitúa en el término municipal de Olvera, Provincia de Cádiz, en un entorno de gran valor paisajístico y es propiedad del ayuntamiento de Alcalá del Valle. Remonta sus orígenes al siglo XVI cuando el Conde de Ureña y Morón facilita tierras para la construcción de una ermita a Nuestra…',36.9474638,-5.1594249,'https://es.wikipedia.org/wiki/Convento_de_Caños_Santos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182723,'29067','Catedral de Málaga','religioso','religioso_osm','La Santa Iglesia Catedral Basílica de la Encarnación es la catedral de Málaga, en España. Situada enfrente de la plaza del Obispo, el templo es considerado una de las joyas renacentistas más valiosas de Andalucía.',36.7201789,-4.41941,'https://malagacatedral.com/','https://es.wikipedia.org/wiki/Catedral_de_Málaga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182724,'43161','Parròquia de la Mare de Déu del Lledó','religioso','religioso_osm','Mare de Déu del Lledó de Valls és una església del municipi de Valls (Alt Camp) protegida com a bé cultural d''interès local.',41.2892411,1.2520326,'https://web.archive.org/web/20220315010804/https://www.parroquialledovalls.cat/','https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Lledó_de_Valls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182725,'90564','Santuari de la Mare de Déu de l''Ajuda','religioso','religioso_osm','El Santuari de la Mare de Déu de l''Ajuda és una església situada als afores de Balenyà (Osona) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.8214129,2.2229943,'https://ca.wikipedia.org/wiki/Santuari_de_la_Mare_de_Déu_de_l''Ajuda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182726,'12068','Ermita de la Mare de Déu del Sargar','religioso','religioso_osm','La ermita de la Virgen del Sargar (en valenciano: Mare de Déu del Sargar) es una ermita, en un tiempo fortificada, que se encuentra en el pueblo de Herbés, en la comarca de Los Puertos de Morella de la Comunidad Valenciana. Se construyó a finales del siglo XIII o principios del siglo XIV, poco después de haber sido…',40.7130342,0.0171968,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_del_Sargar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182727,'17043','Basílica de la Mare de Déu de Núria','religioso','religioso_osm','La Mare de Déu de Núria és una imatge de Maria, mare de Jesús, que hi ha a la Vall de Núria, municipi de Queralbs (Ripollès). És la patrona principal de la diòcesi d''Urgell juntament amb Sant Ermengol d''Urgell i també patrona del Pirineu català.',42.3972178,2.1534356,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Núria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182728,'40034','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de la Asunción de Nuestra Señora​ es un templo románico, construido en el siglo XIII, que se encuentra en la localidad española de Caballar (Segovia).',41.1205896,-3.964323,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Caballar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182729,'90908','Mare de Déu de Puigcerver','religioso','religioso_osm','El santuari de la Mare de Déu de Puigcerver és un edifici religiós entre els termes de Riudecols i Alforja. Agafa el seu nom del no gaire llunyà Puigcerver (de 835 metres) i es troba a la vora del límit del terme amb el terme de Riudecols.',41.1932918,0.9363336,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Puigcerver');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182730,'08009','Mare de Déu del Remei','religioso','religioso_osm','L''Església del Remei és un monument que forma part de l''Inventari del Patrimoni Arquitectònic Català de la vila de Cardona (Bages).',41.934723,1.6969489,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_del_Remei_(Cardona)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182731,'18165','Iglesia Parroquial de Nuestra Señora del Rosario','religioso','religioso_osm','La Iglesia parroquial de San José es una iglesia parroquial de la localidad española de Pulianas, en la provincia de Granada.',37.2232219,-3.6067498,'https://es.wikipedia.org/wiki/Iglesia_parroquial_de_San_José_(Pulianas)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182732,'46051','Iglesia Parroquial de Nuestra Señora de la Asunción','religioso','religioso_osm','L''Església de l''Assumpció, sub invocatione Assumptionis Beatae Mariae Virginis, com era costum al S. XIII, es troba al centre urbà de Benaguasil, al Camp de Túria (País Valencià). Està situat a la plaça Major, sobre el solar de l''antiga mesquita musulmana.',39.5937835,-0.5858394,'https://ca.wikipedia.org/wiki/Església_de_l''Assumpció_de_Benaguasil');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182733,'08070','Mare de Déu dels Socors','religioso','religioso_osm','Santa Maria de Collsuspina o la Mare de Déu dels Socors és l''església parroquial del municipi de Collsuspina (Moianès). És una església moderna, atès que la parròquia primitiva fou Sant Cugat de Gavadons, sufragània de Sant Andreu de Tona.',41.8253462,2.1748255,'https://ca.wikipedia.org/wiki/Santa_Maria_de_Collsuspina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182734,'30027','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es un templo religioso católico ubicado en el término municipal de Molina de Segura, (Región de Murcia, España). Se encuentra ubicada en la zona sur de la ciudad, en el actual Barrio del Castillo.',38.0505041,-1.2114521,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Molina_de_Segura)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182735,'10133','Iglesia de Nuestra Señora de la O','religioso','religioso_osm','La iglesia de Nuestra Señora de la O es el templo parroquial católico de la villa española de Navas del Madroño, en la provincia de Cáceres.',39.6240354,-6.6502395,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_O_(Navas_del_Madroño)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182736,'08133','Mare de Déu del Bon Viatge','religioso','religioso_osm','La Mare de Déu del Bon Viatge és una capella al poble de la Panadella (Anoia) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Va ser consagrada pel bisbe de Vic el 1976.',41.6173448,1.3979171,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Bon_Viatge');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182737,'33041','Santuario de la Virgen de Villaoril','religioso','religioso_osm','El Santuario de la Virgen de Villaoril es un santuario de la Iglesia Católica, que éstá situado en el pueblo de «Villaoril», perteneciente al concejo de Navia, en el occidente asturiano y allí acuden el día de su festividad peregrinos de la «mariña» o costa lucense y de todo el occidente asturiano.…',43.5362712,-6.6803391,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_de_Villaoril');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182738,'08140','Mare de Déu de la Concepció','religioso','religioso_osm','La Capella de la Concepció és una església del municipi de Talamanca (Bages) inclosa en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.7366447,1.9321382,'https://ca.wikipedia.org/wiki/Capella_de_la_Concepció_(Talamanca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182739,'27061','Santuario da Nosa Señora das Virtudes da Ponte','religioso','religioso_osm','O Santuario da Nosa Señora das Virtudes, tamén coñecido como Igrexa das Virtudes ou ermida de Santa María, é un templo relixioso situado no lugar da Ponte (Arante, Ribadeo). Arredor da capela celébrase a romaría das Cruces, declarada festa de interese turístico de Galicia (declarada no 2018).',43.496705,-7.1432101,'https://gl.wikipedia.org/wiki/Santuario_da_Nosa_Señora_das_Virtudes_da_Ponte');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182740,'10127','Ermita del Cristo de los Remedios','religioso','religioso_osm','La ermita del Cristo es una ermita situada al sureste de Montehermoso, en la calle Real, cerca de la carretera de Plasencia, en España. Cuando se construyó era el límite sureste de Montehermoso, el que señalaba la entrada al pueblo.',40.0869521,-6.3454142,'https://es.wikipedia.org/wiki/Ermita_del_Cristo_de_los_Remedios');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182741,'08224','Mare de Déu dels Àngels','religioso','religioso_osm','Nostra Senyora dels Àngels de Sant Martí de Centelles és una església de Sant Martí de Centelles (Osona) protegida com a Bé Cultural d''Interès Local.',41.7589065,2.2461032,'https://ca.wikipedia.org/wiki/Nostra_Senyora_dels_Àngels_de_Sant_Martí_de_Centelles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182742,'43175','Mare de Déu de Montserrat','religioso','religioso_osm','La Capella de la Mare de Déu de Montserrat és una edificació de Vilalba dels Arcs (Terra Alta) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.1209825,0.4149388,'https://ca.wikipedia.org/wiki/Capella_de_la_Mare_de_Déu_de_Montserrat_(Vilalba_dels_Arcs)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182743,'25115','Mare de Déu del Prat','religioso','religioso_osm','La Mare de Déu del Prat és una església al nucli de Figuerola d''Orcau (terme d''Isona i Conca Dellà, el Pallars Jussà) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. És una antiga església de planta rectangular amb contrafort en un dels murs laterals.',42.1311242,0.9961719,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Prat_de_Figuerola_d''Orcau');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182744,'17090','Mare de Déu de la Pietat d''Erols','religioso','religioso_osm','Mare de Déu de la Pietat d''Erols és l''església parroquial d''Erols, al municipi de Llambilles (Gironès), inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.9292183,2.850897,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Pietat_d''Erols');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182745,'25064','Mare de Déu de Savila','religioso','religioso_osm','El Santuari de Santa Maria de Savila és una església de Castellar de la Ribera (Solsonès) inclòs a l''Inventari del Patrimoni Arquitectònic de Catalunya. Te la categoria de santuari marià, ja que s''hi venera la imatge de la Mare de Déu de Savila.',42.0272095,1.3671221,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_Savila');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182746,'90626','Iglesia Matriz de Nuestra Señora de la Concepción','religioso','religioso_osm','El templo matriz de Nuestra Señora de la Concepción de Agaete,​ se encuentra asentada en el casco histórico del municipio grancanario de Agaete (Canarias, España).',28.1002157,-15.7009421,'https://es.wikipedia.org/wiki/Iglesia_matriz_de_Nuestra_Señora_de_la_Concepción_(Agaete)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182747,'25250','Mare de Déu del Carme','religioso','religioso_osm','Mare de Déu del Carme d''Argentera és una església d''Argentera al municipi de Vilanova de Meià (Noguera) protegida com a bé cultural d''interès local.',41.9595556,1.0430606,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Carme_d''Argentera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182748,'45163','Ermita de la Virgen de la Salud','religioso','religioso_osm','La ermita de la Virgen de la Salud es una ermita ubicada en la localidad de Sonseca, en la provincia de Toledo, Castilla‑La Mancha, España. Inicialmente conocida bajo la advocación de San Sebastián, se encuentra junto al cementerio municipal de la localidad.',39.6736105,-3.9831176,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_la_Salud_(Sonseca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182749,'27013','Mare de Déu dels Arcs','religioso','religioso_osm','Mare de Déu dels Arcs de Claravalls és una ermita de Claravalls, al municipi de Tàrrega (Urgell), protegida com a bé cultural d''interès local.',41.70248,1.1241654,'https://ca.wikipedia.org/wiki/Mare_de_Déu_dels_Arcs_de_Claravalls');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182750,'38011','Templo Parroquial Nuestra Señora de la Peñita','religioso','religioso_osm','La parroquia de Nuestra Señora de la Peñita se encuentra en la ciudad de Puerto de la Cruz en el norte de la isla de Tenerife (Islas Canarias, España). El templo está dedicado a Nuestra Señora la Virgen de la Peñita, la cual destaca por ser una réplica de la imagen de Virgen de la Peña (Patrona de la isla de…',28.4166517,-16.5535819,'https://es.wikipedia.org/wiki/Parroquia_de_Nuestra_Señora_de_la_Peñita_(Puerto_de_la_Cruz)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182751,'05053','Iglesia de Nuestra Señora de la Asunción','religioso','religioso_osm','La iglesia de Nuestra Señora de la Asunción es una iglesia parroquial católica de estilo románico situada en el municipio abulense de Casasola (España). Se encuentra a unos dos kilómetros de la localidad en dirección a la vecina Duruelo, localidad del mismo municipio más próxima al templo que la misma Casasola.​​…',40.6602364,-4.8048584,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Asunción_(Casasola)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182752,'46013','Església de la Mare de Déu de l''Assumpció','religioso','religioso_osm','L''Església parroquial de l''Assumpció, sub invocatione Assumptionis Beatae Mariae Virginis, com era costum al S. XIII, és un temple catòlic situat a la plaça de la Constitució, 1, al municipi d''Alboraia. És un Bé de Rellevància Local amb identificador número 46.13.013-001.',39.5000675,-0.3497093,'https://ca.wikipedia.org/wiki/Església_parroquial_de_l''Assumpció_de_Nostra_Senyora_d''Alboraia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182753,'90121','Ermita de la Virgen del Pinarejo','religioso','religioso_osm','La Ermita de la Virgen del Pinarejo se sitúa a unos tres kilómetros del pueblo de Aldeanueva del Codonal (Segovia). Está cerca del lugar en el que se cruzan la Cañada Real Leonesa Oriental con la carretera de Segovia a Arévalo, lugar del que parte el cordel denominado Camino del Moro, a orillas del río Voltoya y…',41.07475,-4.5078242,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_del_Pinarejo_(Aldeanueva_del_Codonal)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182754,'36052','Santuario de Nosa Señora do Corpiño','religioso','religioso_osm','O santuario da Nosa Señora do Corpiño, máis coñecido simplemente coma O Corpiño, é un santuario situado no lugar do Corpiño, na parroquia de Santa Baia de Losón pertencente o concello de Lalín, nun pequeno outeiro situado no alto do val do río Deza, a medio camiño na estrada que vai de Silleda a Vila de Cruces.',42.7450965,-8.2151995,'https://ocorpino.org/','https://gl.wikipedia.org/wiki/Santuario_da_Nosa_Señora_do_Corpiño');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182755,'45121','Convento de Santa Catalina de Siena','religioso','religioso_osm','El convento de Santa Catalina de Siena, de estilo renacentista, es el tercero de religiosas coetáneo en Ocaña, erigido el 8 de junio de 1571 por Catalina de Guzmán y Vargas (viuda del insigne capitán Juan Maldonado, e hija de Manuel de Guzmán e Inés de Vargas), por registro, ante Juan Pérez del Hoyo, haciendo una…',39.9612192,-3.4940536,'https://es.wikipedia.org/wiki/Convento_de_Santa_Catalina_de_Siena_(Ocaña)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182756,'46193','Església Parroquial de la Mare de Déu de Montserrat','religioso','religioso_osm','L''Església Parroquial de la Mare de Déu de Montserrat és un temple catòlic situat al municipi de Picanya. És Bé de Rellevància Local amb identificador nombre 46.14.193-001.',39.4359956,-0.4347241,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_de_Montserrat_de_Picanya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182757,'41036','Iglesia de Nuestra Señora de la Consolación','religioso','religioso_osm','La iglesia de Nuestra Señora de Consolación​ es un inmueble de la localidad española de El Coronil, en la provincia de Sevilla.',37.0817105,-5.634436,'https://www.parroquiaconsolacionelcoronil.es/','https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Consolación_(El_Coronil)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182758,'90518','Santuario de Nosa Señora das Ermidas','religioso','religioso_osm','O santuario da Nosa Señora das Ermidas pode referirse a: Santuario da Nosa Señora das Ermidas, en Antas (A Lama); Santuario da Nosa Señora das Ermidas, nas Ermidas (O Bolo).',42.2922995,-7.1385637,'https://gl.wikipedia.org/wiki/Santuario_de_Nosa_Señora_das_Ermidas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182759,'17051','Mare de Déu de Vida','religioso','religioso_osm','El Santuari de Nostra Senyora de Vida o Ermita de la Mare de Déu de Vida és un edifici religiós reconstruït el segle xvii i situat al municipi de Cistella (Alt Empordà). És una ermita situada dalt d''un turó situat a uns dos quilòmetres al nord-est del nucli de Cistella, al cim d''un turó cobert d''olivars, des d''on…',42.2665392,2.838476,'https://ca.wikipedia.org/wiki/Santuari_de_Nostra_Senyora_de_Vida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182760,'47194','Santuario de Nuestra Señora de El Henar','religioso','religioso_osm','El santuario de Nuestra Señora del Henar,​ o simplemente El Henar, está ubicado en el municipio de Cuéllar, en la provincia de Segovia, España a cinco kilómetros de su casco urbano, si bien está más próximo al pueblo de Viloria del Henar, que pertenece a la provincia de Valladolid. De hecho, el límite entre las dos…',41.4432205,-4.3494676,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_El_Henar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182761,'28131','Basílica de San Lorenzo de El Escorial','religioso','religioso_osm','La Basílica de El Escorial es un templo de culto católico que forma parte del conjunto del Monasterio de El Escorial, en la localidad de San Lorenzo de El Escorial, Madrid, España, que formaba parte en su momento de la archidiócesis de Toledo. Fue concebida como centro del conjunto monacal y lugar de conmemoración…',40.588966,-4.1474205,'https://es.wikipedia.org/wiki/Real_Basílica_de_San_Lorenzo_de_El_Escorial');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182762,'28079','Iglesia del Monasterio de Benedictinas de San Plácido','religioso','religioso_osm','El convento de San Plácido es un edificio religioso de la orden benedictina situado en la calle del Pez, entre las calles de san Roque y Madera, en el barrio de Universidad de la ciudad de Madrid (España). Tiene entrada por San Roque, n,º 9.',40.4226474,-3.7048176,'https://es.wikipedia.org/wiki/Convento_de_San_Plácido_(Madrid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182763,'25052','Mare de Déu de les Sogues','religioso','religioso_osm','La Mare de Déu de les Sogues és un santuari del municipi de Bellvís (Pla d''Urgell) inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6886731,0.8203326,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_les_Sogues');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182764,'25912','Mare de Déu del Roser','religioso','religioso_osm','La Mare de Déu del Roser de Gimenells és l''església parroquial de Gimenells, al municipi de Gimenells i el Pla de la Font (Segrià) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.6522205,0.3898763,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Roser_de_Gimenells');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182765,'36054','Santuario de San Campio de Lonxe','religioso','religioso_osm','O santuario de San Martiño e San Campio é a igrexa parroquial de Figueiró (Tomiño), amais de centro de peregrinación. É coñecido como San Campio de Lonxe ou San Campio do Monte.',41.9638223,-8.7719687,'https://gl.wikipedia.org/wiki/Santuario_de_San_Campio_de_Figueiró');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182766,'46054','Església de la Mare de Déu dels Socors','religioso','religioso_osm','L''Església parroquial de la Mare de Déu del Socors, és un edifici religiós situat al municipi de Benetússer. És Bé de Rellevància Local amb identificador nombre 46.16.054-001.',39.4233035,-0.4013346,'https://ca.wikipedia.org/wiki/Església_de_la_Mare_de_Déu_del_Socors_de_Benetússer');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182767,'22247','Santuario de Nuestra Señora de Obac','religioso','religioso_osm','Verge d''Obac de Viacamp és una ermita situada als afores del nucli de Viacamp (municipi de Viacamp i Lliterà), a la comarca de la Ribagorça. Era un antic monestir visigòtic que ha sofert moltes reformes i que ostenta el títol de Capella Reial.',42.1287966,0.6123337,'https://ca.wikipedia.org/wiki/Verge_d''Obac_de_Viacamp');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182768,'46023','Església de la Mare de Déu del Roser','religioso','religioso_osm','L''Església Parroquial de la Mare de Déu del Roser d''Alfauir és un monument religiós, que està ubicat al carrer Major s/n del municipi d''Alfauir, a la comarca de la Safor, província de València, que està declarat Bé de Rellevància Local, amb codi 46.25.023-003. Es tracta d''un edifici religiós construït durant la…',38.9278796,-0.2518773,'https://ca.wikipedia.org/wiki/Església_Parroquial_de_la_Mare_de_Déu_del_Roser_d''Alfauir');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182769,'08020','Mare de Déu de la Gleva','religioso','religioso_osm','La Mare de Déu de la Gleva és un santuari de les Masies de Voltregà, al Voltreganès (Osona), dedicat a una imatge trobada cap al segle xiii. Catalogat com a bé cultural d''interès local, és el segon més important de Catalunya després del de Montserrat.',42.0035577,2.2411649,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Gleva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182770,'90279','Iglesia Nuestra Señora de los Ángeles','religioso','religioso_osm','La iglesia de Nuestra Señora de los Ángeles es una iglesia románica que se encuentra en Fuensaúco (Provincia de Soria, Castilla y León, España). Destaca por ser un edificio de buena hechura y por los merlones o almenas que le confieren ese aspecto de fortaleza.',41.7658499,-2.3371562,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_los_Ángeles_(Fuensaúco)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182771,'08055','Mare de Déu de la Concepció','religioso','religioso_osm','La Mare de Déu de la Concepció del Bosc és l''antiga capella del mas el Bosc, del terme municipal de Castellcir, al Moianès. Està situada a prop del límit amb Sant Quirze Safaja.',41.7533998,2.1684911,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Concepció_del_Bosc');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182772,'31232','Iglesia de Nuestra Señora de Lourdes','religioso','religioso_osm','La iglesia parroquial de Nuestra Señora de Lourdes de Tudela (Navarra) es una iglesia del siglo XX,​ situada en la plaza del Padre Lasa del Barrio de Lourdes de Tudela.​',42.0546985,-1.6032347,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_Lourdes_(Tudela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182773,'31232','Convento e Iglesia de las Siervas de María','religioso','religioso_osm','El convento de las Siervas de María de Tudela (Navarra) es un convento e iglesia de estilo neogótico del siglo XX,​ situada en la calle de Gayarre del Casco Antiguo de Tudela.​',42.0620741,-1.6085657,'https://es.wikipedia.org/wiki/Convento_de_las_Siervas_de_María');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182774,'22175','Ermita de la Virgen del Pla','religioso','religioso_osm','La ermita de Nuestra Señora del Plá (Pllà, en catalán bajorribagorzano) es una ermita situada en la localidad española de Purroy de la Solana, en Benabarre, Huesca, Aragón.​',42.0415185,0.4565763,'https://es.wikipedia.org/wiki/Ermita_de_Nuestra_Señora_del_Plá');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182775,'45163','Ermita Virgen de los Remedios','religioso','religioso_osm','La ermita de la Virgen de los Remedios es una ermita ubicada en la localidad de Sonseca, en la provincia de Toledo, Castilla-La Mancha, España.',39.6785734,-3.9711321,'https://es.wikipedia.org/wiki/Ermita_de_la_Virgen_de_los_Remedios_(Sonseca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182776,'40193','Convento de Nuestra Señora la Hoz','religioso','religioso_osm','El Convento de Nuestra Señora de los Ángeles de la Hoz del Río Duratón fue un antiguo monasterio, hoy en ruinas. Se ubica en el fondo de la Hoz de Los Ángeles del cañón del río Duratón, en el término municipal de Sebúlcor, provincia de Segovia, Castilla y León.',41.3154654,-3.8704418,'https://es.wikipedia.org/wiki/Convento_de_Nuestra_Señora_de_los_Ángeles_(Sebúlcor)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182777,'17160','Monestir benedictí Sant Feliu de Guíxols','religioso','religioso_osm','El monestir de Sant Feliu de Guíxols, està situat en la població de Sant Feliu de Guíxols, al Baix Empordà. A les dependències superiors, juntament amb les del Museu d''Història de Sant Feliu de Guíxols (primera planta), es proposa com a futura seu de la Col·lecció Carmen Thyssen-Bornemisza, en la seva secció de…',41.7798957,3.0264913,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Feliu_de_Guíxols');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182778,'25156','Mare de Déu d''Aguilar','religioso','religioso_osm','La Mare de Déu d''Aguilar és una ermita al terme municipal d''Os de Balaguer (Noguera) inclosa a l''Inventari del Patrimoni Arquitectònic de Catalunya. Fou construïda l''any 1791 amb l''ajut dels veïns del poble i també d''alguns devots forasters.',41.8596891,0.7371719,'https://ca.wikipedia.org/wiki/Mare_de_Déu_d''Aguilar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182779,'18145','Iglesia Nuestra Señora de la Cabeza','religioso','religioso_osm','La Iglesia de Nuestra Señora de la Cabeza, denominada también del Santo Cristo de la Misericordia, en ubicada en el barrio Alto de los Ogíjares (Provincia de Granada, España) constituye un testimonio de lo que fue la primera etapa constructiva del mudéjar granadino generalizado tras la Reconquista. El Templo, que…',37.1192034,-3.6094793,'https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Señora_de_la_Cabeza_(Ogíjares)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182780,'28079','Catedral de la Almudena','religioso','religioso_osm','La Santa Iglesia Catedral Metropolitana de Santa María la Real de la Almudena, conocida simplemente como catedral de la Almudena,​ es una catedral de culto católico, dedicada a la Virgen María bajo la advocación de la Almudena, y sede episcopal de Madrid. Construida muy cerca del emplazamiento de la anterior y muy…',40.4157109,-3.714495,'https://es.wikipedia.org/wiki/Catedral_de_la_Almudena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182781,'15078','Mosteiro e Igrexa de San Paio de Antealtares','religioso','religioso_osm','San Paio de Antealtares é un convento do século IX de monxas beneditinas de clausura. Está situado no casco vello de Santiago de Compostela, fronte á cabeceira da catedral de Santiago de Compostela, pechando a praza da Quintana.',42.8804528,-8.5430712,'https://gl.wikipedia.org/wiki/Convento_de_San_Paio_de_Antealtares');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182782,'42173','Concatedral de San Pedro','religioso','religioso_osm','Para ver otras colegiatas bajo la misma advocación, véase Colegiata de San Pedro. La concatedral de San Pedro es un templo cristiano de estilo románico ubicado en la ciudad de Soria.',41.7662903,-2.4591207,'https://es.wikipedia.org/wiki/Concatedral_de_San_Pedro_de_Soria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182783,'42043','Catedral de Burgo de Osma','religioso','religioso_osm','La catedral de la Asunción es un templo católico ubicado en la localidad del El Burgo de Osma dentro del municipio El Burgo de Osma-Ciudad de Osma en la provincia de Soria en Castilla y León en España. Fue núcleo y sede de la diócesis de Osma desde el siglo VI lo que le hace una de las más antiguas de España.',41.5858826,-3.0705532,'https://es.wikipedia.org/wiki/Catedral_de_El_Burgo_de_Osma');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182784,'09003','La Cartuja de Miraflores','religioso','religioso_osm','La Cartuja de Santa María de Miraflores es un monasterio de la Orden de los Cartujos, edificado en una loma conocida como Miraflores, situada a unos tres kilómetros del centro de la ciudad de Burgos (Castilla y León, España). Es una joya del arte gótico final.',42.3374542,-3.6565971,'https://www.cartuja.org/','https://es.wikipedia.org/wiki/Cartuja_de_Miraflores');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182785,'28120','Monasterio de Santa María de El Paular','religioso','religioso_osm','El Real Monasterio de Santa María de El Paular es un monasterio situado en el municipio español de Rascafría, en la vertiente madrileña de la sierra de Guadarrama, en el valle del Lozoya, parque nacional de la Sierra de Guadarrama. El conjunto monumental del monasterio está declarado como bien de interés cultural…',40.88864,-3.8879259,'https://www.monasteriopaular.com/','https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_El_Paular');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182786,'17079','Basilica de Sant Feliu','religioso','religioso_osm','Sant Feliu o Sant Fèlix és una basílica al Barri Vell de Girona col·legiata originària dels primers temps del cristianisme. Acull els oficis de la Parròquia Major de Sant Feliu del Bisbat de Girona, dita així perquè aquest era el temple principal de Girona abans de la construcció de la catedral.',41.9879799,2.8248903,'https://ca.wikipedia.org/wiki/Església_de_Sant_Feliu_de_Girona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182787,'18005','Catedral de Girona','religioso','religioso_osm','La catedral de Girona, dedicada a Santa Maria, és una església catòlica i seu del Bisbat de Girona. És el major temple cristià de la província.',41.9875074,2.8263403,'https://ca.wikipedia.org/wiki/Catedral_de_Girona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182788,'37010','Santuario de Nuestra Señora de la Peña de Francia (PP. Dominicos)','religioso','religioso_osm','El Santuario de Nuestra Señora de la Peña de Francia, dedicado a la advocación mariana correspondiente a la Natividad de María bajo la denominación homónima, patrona de Ciudad Rodrigo, está situado en la cima de la Peña de Francia, Sierra de Francia, en el término municipal de El Cabaco (Salamanca). Regido por los…',40.5123539,-6.1690906,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_la_Peña_de_Francia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182789,'37011','Convento de las Úrsulas','religioso','religioso_osm','El convento de la Anunciación más conocido como Las Úrsulas es un convento franciscano femenino situado en la ciudad de Salamanca, en el Paseo de las Úrsulas. Situado en el coro bajo de la iglesia se encuentra un pequeño pero interesante museo.',40.9663143,-5.667103,'https://es.wikipedia.org/wiki/Convento_de_la_Anunciación_(Salamanca)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182790,'09003','Convento de San José y Santa Ana','religioso','religioso_osm','El convento carmelita de San José y Santa Ana es un cenobio de monjas carmelitas descalzas sito en la plaza de Santa Teresa, al final del Paseo Sierra de Atapuerca de la ciudad de Burgos (Comunidad de Castilla y León, España). Este convento fue fundado por Santa Teresa de Jesús en 1582,​ siendo esta la última de…',42.3401104,-3.6939278,'https://es.wikipedia.org/wiki/Convento_de_San_José_y_Santa_Ana_(Burgos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182791,'34120','Catedral de San Antolín','religioso','religioso_osm','La Santa Iglesia Catedral-Basílica de San Antolín, más conocida como catedral de San Antolín, es un templo de culto católico, sede episcopal de la diócesis de Palencia, en la ciudad del mismo nombre, comunidad autónoma de Castilla y León, España. Está dedicada a san Antolín mártir, patrono de Palencia, parte de…',42.0112093,-4.5372692,'https://catedraldepalencia.org','https://es.wikipedia.org/wiki/Catedral_de_San_Antolín_de_Palencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182792,'09301','Monasterio de Nuestra Señora del Espino','religioso','religioso_osm','El monasterio de Nuestra Señora del Espino es un cenobio de monjas Clarisas sito en la localidad de Vivar del Cid (provincia de Burgos, Comunidad de Castilla y León, España).',42.4247524,-3.6785575,'https://es.wikipedia.org/wiki/Monasterio_de_Nuestra_Señora_del_Espino_(Vivar_del_Cid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182793,'32049','Mosteiro de Santa María de Montederramo','religioso','religioso_osm','O mosteiro de Santa María de Montederramo é un mosteiro galego medieval, beneditino e logo da orde do Císter posiblemente fundado no século X e que chegou a se converter nun dos mosteiros de maior poderío económico e social ata a desamortización. A fachada da igrexa é un exemplo do estilo herreriano en Galicia.',42.2744405,-7.5022455,'https://gl.wikipedia.org/wiki/Mosteiro_de_Santa_María_de_Montederramo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182794,'27055','Mosteiro de San Xiao de Samos','religioso','religioso_osm','O mosteiro de San Xulián de Samos, tamén mosteiro de San Xiao de Samos, é un mosteiro medieval fundado no século VI, segundo a tradición por Martiño de Dumio, que chegou a ser un dos de maior importancia de Galicia, e que na actualidade se atopa en bo estado de conservación. Pertence á orde dos beneditinos e está…',42.7321254,-7.3260958,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Xulián_de_Samos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182795,'31041','Monasterio de Santa María la Real de Irache','religioso','religioso_osm','El monasterio de Irache (en euskera: Iratxeko monasterioa) es un conjunto monacal situado en la población navarra de Irache perteneciente al municipio de Ayegui, en la Merindad de Estella en Navarra, España. Sus orígenes inciertos se remontarían al siglo VIII, pudiendo haber sido fundado por el monarca Sancho…',42.6501801,-2.0433072,'https://www.turismo.navarra.es/esp/organice-viaje/recurso/Patrimonio/3150/Monasterio-de-Iratxe.htm','https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_la_Real_de_Irache');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182796,'50297','Catedral del Salvador','religioso','religioso_osm','La Seo del Salvador en su Epifanía​​​ es una de las dos seos o catedrales​ metropolitanas de la archidiócesis de Zaragoza, junto con la catedral-basílica de Nuestra Señora del Pilar. Se encuentra en la ciudad de Zaragoza (Aragón, España).',41.6547294,-0.8756552,'https://catedraldezaragoza.es/la-seo-catedral-del-salvador/','https://es.wikipedia.org/wiki/Catedral_del_Salvador_de_Zaragoza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182797,'50297','Basílica de Nuestra Señora del Pilar','religioso','religioso_osm','La Basílica o Santo Templo Metropolitano de Nuestra Señora del Pilar, habitualmente llamada «Basílica del Pilar» o «el Pilar», es una de las dos catedrales metropolitanas de la Archidiócesis de Zaragoza, junto con la Seo del Salvador, en la ciudad de Zaragoza (Aragón, España). Según la tradición, se trata del…',41.6567707,-0.8785225,'https://catedraldezaragoza.es/basilica/','https://es.wikipedia.org/wiki/Catedral-Basílica_de_Nuestra_Señora_del_Pilar_de_Zaragoza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182798,'15078','Convento de Belvís','religioso','religioso_osm','Convento de larga tradición devocional en Santiago de Compostela (A Coruña).',42.8780554,-8.5371695,'https://declausura.org/monasterio/convento-de-santa-maria-de-belvis-santiago-de-compostela-la-coruna/','https://pt.wikipedia.org/wiki/Convento_de_Belvís');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182799,'23046','Catedral de la Natividad de Nuestra Señora de Baeza','religioso','religioso_osm','La catedral de la Natividad de Nuestra Señora es la catedral renacentista de Baeza, provincia de Jaén, España. Fue la sede del obispado de Jaén desde 1227 hasta que la sede episcopal se trasladó a Jaén en 1249.',37.9899611,-3.4688808,'https://es.wikipedia.org/wiki/Catedral_de_la_Natividad_de_Nuestra_Señora_de_Baeza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182800,'45168','Catedral de Santa María','religioso','religioso_osm','La catedral de Santa María, llamada también catedral primada de España, es un templo católico de arquitectura gótica en Toledo, considerado por algunos como el opus magnum​ de este estilo en España. Su construcción comenzó en 1226 bajo el reinado de Fernando III el Santo y las últimas aportaciones góticas se dieron…',39.8573916,-4.0237544,'https://es.wikipedia.org/wiki/Catedral_de_Toledo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182801,'45168','Monasterio de San Juan de los Reyes','religioso','religioso_osm','El convento de San Juan de los Reyes es un cenobio de la ciudad española de Toledo perteneciente a la Orden Franciscana, que fue construido bajo el patrocinio de la reina Isabel I de Castilla con la intención de convertirlo en mausoleo real, en conmemoración de la batalla de Toro y del nacimiento del príncipe Juan.…',39.8577745,-4.0317075,'https://es.wikipedia.org/wiki/Monasterio_de_San_Juan_de_los_Reyes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182802,'38023','Convento de Santa Clara de Asís','religioso','religioso_osm','El convento o monasterio de Santa Clara de Asís y de San Juan Bautista (más conocido simplemente como convento de Santa Clara de Asís) es un convento franciscano situado en la ciudad de San Cristóbal de La Laguna en la isla de Tenerife (Islas Canarias, España).',28.4897985,-16.3136507,'https://es.wikipedia.org/wiki/Convento_de_Santa_Clara_de_Asís_(San_Cristóbal_de_La_Laguna)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182803,'49275','Catedral de San Salvador','religioso','religioso_osm','La catedral de Zamora (Zamora, España), dedicada al Salvador, se inscribe dentro del denominado románico del Duero, distinguiéndose por ser la más pequeña y la más antigua de las once de la Comunidad autónoma de Castilla y León.​ Fue declarada Monumento Nacional por Real Orden de 5 de septiembre de 1889.​ Su planta…',41.4991168,-5.7546407,'https://es.wikipedia.org/wiki/Catedral_de_Zamora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182804,'36042','Convento de San Diego de Canedo','religioso','religioso_osm','O convento de San Diego de Canedo é un mosteiro franciscano de estilo barroco que se atopa no lugar de Canedo, na parroquia de San Miguel de Ponteareas (concello pontevedrés de Ponteareas), nas abas do monte da Picaraña.',42.1819902,-8.4921463,'http://www.conventodecanedo.info/','https://gl.wikipedia.org/wiki/Convento_de_San_Diego_de_Canedo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182805,'50037','Colegiata de Santa María','religioso','religioso_osm','Santa Mariaren kolegiata (gaztelaniaz: colegiata de Santa María) Burgosko Valpuestako eliza gotikoa da, Merindadeetan dagoena. IX. mendeko eliza bisigotiko baten gainean eraikia, bertan Valpuestako kartularioak topatu zituzten non antzinako gaztelaniazko lehendabiziko hitzak dauden.',42.8657489,-3.1246124,'https://eu.wikipedia.org/wiki/Santa_Mariaren_kolegiata_(Valpuesta)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182806,'09248','Monasterio de Santa María de Bujedo de Juarros','religioso','religioso_osm','El monasterio de Santa María de Bujedo de Juarros (Santa Cruz de Juarros, Burgos), perteneció a la orden del Císter y se encuentra situado en el fondo de un pequeño valle surcado por el río Seco, a escasos kilómetros de la ciudad de Burgos.',42.23747,-3.4962628,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_Bujedo_de_Juarros');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182807,'09014','Convento de la Asunción','religioso','religioso_osm','El monasterio de la Asunción o convento de Santa Clara es un cenobio de monjas Clarisas sito en la localidad de Castil de Lences (provincia de Burgos, Comunidad de Castilla y León, España).',42.6417331,-3.5466771,'https://clarisascastil.webnode.es/','https://es.wikipedia.org/wiki/Monasterio_de_la_Asunción_(Castil_de_Lences)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182808,'09449','Monasterio Benedictino de San Salvador','religioso','religioso_osm','El monasterio de San Salvador en Palacios de Benaver en la provincia de Burgos se considera uno de los monasterios cristianos más antiguos de España.',42.3921709,-3.9047549,'https://benedictinaspalacios.com','https://es.wikipedia.org/wiki/Monasterio_de_San_Salvador_(Palacios_de_Benaver)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182809,'09086','Monasterio de San Pedro de Cardeña','religioso','religioso_osm','El monasterio de San Pedro de Cardeña es una abadía trapense situada en el término municipal de Castrillo del Val, a 10 km del centro de Burgos (España). Actualmente, está considerado bien de interés cultural (BIC).',42.3042758,-3.6073716,'https://www.monasteriosanpedrodecardena.com','https://es.wikipedia.org/wiki/Monasterio_de_San_Pedro_de_Cardeña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182810,'28079','Convento de las Trinitarias Descalzas','religioso','religioso_osm','El monasterio de San Ildefonso y San Juan de Mata, más conocido por su antiguo nombre de Convento de las Trinitarias Descalzas de San Ildefonso, es un conjunto arquitectónico de iglesia y monasterio barrocos de la capital de España, dentro del perímetro del Madrid de los Austrias.​ La primitiva construcción data de…',40.4135071,-3.697372,'https://es.wikipedia.org/wiki/Convento_de_las_Trinitarias_Descalzas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182811,'08127','Monestir de Santa Cecília','religioso','religioso_osm','Santa Cecília de Montserrat és una antiga abadia benedictina al municipi de Marganell, al Bages, situada a llevant de la muntanya de Montserrat, prop de l''antic castell Marro, sota de Sant Jeroni, a mig camí de Can Maçana i el monestir de Montserrat. És un edifici catalogat l''Inventari del Patrimoni Arquitectònic…',41.6116313,1.8170913,'https://ca.wikipedia.org/wiki/Santa_Cecília_de_Montserrat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182812,'08127','Monestir de Sant Benet','religioso','religioso_osm','Sant Benet de Montserrat és un monestir de monges Benedictines del municipi de Marganell (Bages). Està situat en un vessant de la muntanya de Montserrat, prop de la Colònia Puig, en un erm sobre un penya-segat que domina el camí de Monistrol de Montserrat.',41.6099792,1.8270484,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Benet_de_Montserrat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182813,'09003','Monasterio Cisterciense de San Bernardo','religioso','religioso_osm','El monasterio de San Bernardo de Burgos es un cenobio de monjas cistercienses​ popularmente conocidas como Bernardas, sito al final del paseo de los Pisones de la capital burgalesa (Comunidad de Castilla y León, España).',42.3288333,-3.6980805,'https://es.wikipedia.org/wiki/Monasterio_de_San_Bernardo_(Burgos)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182814,'09057','Monasterio de Santa María de Bujedo','religioso','religioso_osm','El monasterio de Santa María de Bujedo, también conocido como monasterio de Santa María de Bujedo de Candepajares, se encuentra situado en el municipio de Bujedo, Burgos (España), en la frontera con La Rioja, a 9 km al suroeste de Miranda de Ebro y 4 km al norte de Foncea. Lo fundó Doña Sancha Díaz de Frías en el…',42.6459963,-3.0241683,'https://www.bujedo.com/','https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_Bujedo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182815,'09442','Convento de San Blas','religioso','religioso_osm','El convento de San Blas de la localidad de Lerma (provincia de Burgos, Castilla y León, España) está situado en una plaza anexa a la plaza Ducal, llamada de San Blas. De estilo barroco clasicista, comenzó a construirse a principios del siglo XVII para albergar una comunidad de monjas Dominicas, cuya vida religiosa…',42.0253525,-3.755059,'https://es.wikipedia.org/wiki/Convento_de_San_Blas_(Lerma)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182816,'09442','Convento de la Ascensión','religioso','religioso_osm','El monasterio de la Ascensión de Nuestro Señor, también llamado Convento de Santa Clara, es un cenobio actualmente sin actividad religiosa. El monasterio está situado en la plaza de Santa Clara de Lerma (provincia de Burgos, Castilla y León, España).',42.0267846,-3.7579287,'https://es.wikipedia.org/wiki/Monasterio_de_la_Ascensión_de_Nuestro_Señor_(Lerma)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182817,'40194','Monasterio de San Antonio El Real','religioso','religioso_osm','El monasterio de San Antonio el Real es un complejo monacal situado en la ciudad española de Segovia, capital de la provincia del mismo nombre, perteneciente a la comunidad autónoma de Castilla y León. De estilo gótico es uno de los edificios religiosos más relevantes de Segovia.',40.942537,-4.1106966,'https://es.wikipedia.org/wiki/Monasterio_de_San_Antonio_el_Real');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182818,'15078','Convento e Igrexa das Madres Mercedarias','religioso','religioso_osm','Convento de larga tradición devocional en Santiago de Compostela (A Coruña).',42.8775565,-8.5418899,'https://pt.wikipedia.org/wiki/Convento_das_Mercedárias_(Santiago_de_Compostela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182819,'15078','Mosteiro e Igrexa de San Martiño Piñario e Seminario Maior','religioso','religioso_osm','O mosteiro de San Martiño Pinario é un mosteiro beneditino fundado no século X e que no século XVI, coa reforma promovida polos Reis Católicos, dirixiu e gobernou a totalidade dos mosteiros bieitos masculinos de Galicia. Sitúase na zona vella da cidade de Santiago de Compostela, fronte á fachada da Acibechería da…',42.8821315,-8.5444416,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Martiño_Pinario');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182820,'15078','Convento do Colexio da Compañía de María ou da Ensinanza','religioso','religioso_osm','A Compañía de María de Santiago de Compostela, tamén coñecido como a Ensinanza (debido á rúa onde se atopa, do mesmo nome) é un centro educativo concertado. Foi fundado no ano 1759 baixo a titularidade da Orde da Compañía de María.',42.8786461,-8.5404633,'https://gl.wikipedia.org/wiki/Colexio_Compañía_de_María_de_Santiago_de_Compostela');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182821,'33065','Monasterio de Santa María de Valdediós','religioso','religioso_osm','El monesteriu de San Salvador de Valdediós asítiase nel conceyu de Villaviciosa, a escasos diez quilómetros d''esta llocalidá. Anguaño esti monesteriu ta habitáu por una pequeña comunidá de monxos cistercienses consagraos al trabayu manual en talleres empobinaos a la fabricación d''artesanía.',43.4364318,-5.5068249,'https://monasteriovaldedios.com/','https://ast.wikipedia.org/wiki/Monasteriu_de_Valdediós');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182822,'08113','Monestir de Santa Clara','religioso','religioso_osm','El convent de Santa Clara, formalment Nostra Senyora dels Àngels i Santa Clara, és un antic convent de la ciutat de Manresa (Bages) protegit com a bé cultural d''interès local. Es troba en un extrem del raval de les Escodines, en l''antic camí de Barcelona, entre els barris de les Escodines i la Balconada, sobre la…',41.7203275,1.8356287,'https://ca.wikipedia.org/wiki/Convent_de_Santa_Clara_de_Manresa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182823,'34047','Monasterio San Zoilo','religioso','religioso_osm','El monasterio de San Zoilo se encuentra al oeste de la localidad de Carrión de los Condes, cercano al puente del río Carrión en dirección a Sahagún, en la Comarca de Tierra de Campos de la provincia de Palencia, España. Actualmente es un hotel denominado Hotel Real Monasterio San Zoilo.',42.3402572,-4.6114293,'https://es.wikipedia.org/wiki/Monasterio_de_San_Zoilo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182824,'35001','Monasterio de Santa Clara','religioso','religioso_osm','El convento de Santa Clara de Aguilar es un cenobio situado en la ribera derecha del río Pisuerga a su paso por la villa de Aguilar de Campoo, cuyas trazas arquitectónicas representan la sencillez característica de la expresión artística de la Orden de Santa Clara. Fue originalmente un convento franciscano fundado…',42.7911187,-4.2632341,'https://es.wikipedia.org/wiki/Convento_de_Santa_Clara_de_Aguilar_de_Campoo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182825,'35001','Monasterio de Santa María la Real','religioso','religioso_osm','El monasterio de Santa María la Real es una antigua abadía de la orden Premonstratense situada en la localidad de Aguilar de Campoo, provincia de Palencia, comunidad autónoma de Castilla y León, España. Monumento construido a caballo entre los siglos XII y XIII en un estilo de transición del románico al gótico con…',42.7959245,-4.2719897,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_la_Real_(Aguilar_de_Campoo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182826,'33001','Irantzuko Andre Mariaren monasterioa','religioso','religioso_osm','Irantzuko Andre Maria monasterioa abadia katolikoa da, Abartzuzan dagoena, Nafarroa Garaiko mendebaldean. Petri Artaxoakoak 1176an fundatua, zistertar arkitekturaren eredu ederra da.',42.7507829,-2.0387717,'https://eu.wikipedia.org/wiki/Irantzuko_monasterioa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182827,'09347','Convento de Santa María del Espino','religioso','religioso_osm','El monasterio o convento del Espino es un edificio del municipio español de Santa Gadea del Cid, en la provincia de Burgos.',42.7271332,-3.04752,'https://es.wikipedia.org/wiki/Monasterio_del_Espino_(Santa_Gadea_del_Cid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182828,'09421','Monasterio de Santa María de la Vid','religioso','religioso_osm','El monasterio de Santa María de la Vid se encuentra en el municipio español de La Vid y Barrios, en la Provincia de Burgos. Fue en sus inicios un monasterio premostratense, pero hoy pertenece a los agustinos.',41.6289113,-3.4876848,'https://www.monasteriodelavid.org/','https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_la_Vid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182829,'27006','Catedral de Santa Maria d''Urgell','religioso','religioso_osm','La catedral de la Seu d''Urgell o de Santa Maria és un temple catòlic de la localitat homònima, declarat bé cultural d''interès nacional. És considerat com un exemplar únic dins el romànic català per les seves característiques italianitzants, altament visibles en l''ornamentació de la façana i la galeria oberta de la…',42.3577194,1.461987,'https://ca.wikipedia.org/wiki/Catedral_de_la_Seu_d''Urgell');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182830,'08003','Catedral de la Santa Creu i Santa Eulàlia','religioso','religioso_osm','La catedral de la Santa Creu i Santa Eulàlia és una basílica gòtica seu de l''arquebisbat de Barcelona, declarada bé cultural d''interès nacional. Es va construir durant els segles xiii al xv, al mateix lloc on hi havia hagut una catedral romànica, i encara abans una de paleocristiana.',41.3839273,2.1763464,'https://www.catedralbcn.org/','https://ca.wikipedia.org/wiki/Catedral_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182831,'51025','Real Monasterio de Santo Tomás','religioso','religioso_osm','El real monasterio de Santo Tomás es un edificio de estilo gótico que se encuentra en la ciudad de Ávila. Su fundación, en 1480, se debió al tesorero de los Reyes Católicos, Hernán Núñez de Arnalte, quien otorgó poder a favor de su esposa, María Dávila, y de fray Tomás de Torquemada para que actuasen en su nombre…',40.6503049,-4.6883384,'https://es.wikipedia.org/wiki/Real_Monasterio_de_Santo_Tomás_(Ávila)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182832,'19257','Catedral de Sigüenza','religioso','religioso_osm','La catedral de Santa María de la ciudad española de Sigüenza tiene su origen en enero de 1124, cuando el obispo Bernardo de Agén (1080-1152) conquistó la ciudad a los musulmanes, en tiempos del reinado de Doña Urraca, hija de Alfonso VI de León. Fue nombrado obispo en 1121 (antes de la conquista del lugar), por el…',41.0687287,-2.6409578,'https://catedralsiguenza.es','https://es.wikipedia.org/wiki/Catedral_de_Santa_María_de_Sigüenza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182833,'46218','Monasterio de Sant Jeroni de Cotalba','religioso','religioso_osm','El Reial monestir de Sant Jeroni de Cotalba és un monestir fundat pel duc reial de Gandia Alfons el Vell en l''any 1388 i va acollir la primera comunitat jerònima de l''antiga corona d''Aragó. Està situat al terme municipal d''Alfauir, al costat de Ròtova, a la comarca de la Safor, País Valencià.',38.9406982,-0.2460768,'https://ca.wikipedia.org/wiki/Sant_Jeroni_de_Cotalba');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182834,'41011','Convento Madres Concepcionistas','religioso','religioso_osm','El convento de la Concepción es un convento de clausura monástica de las Madres Concepcionistas situado en la villa española de Ágreda, en la provincia de Soria.',41.8520089,-1.9165519,'https://es.wikipedia.org/wiki/Convento_de_la_Concepción_(Ágreda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182835,'23092','Convento de Santa Clara','religioso','religioso_osm','El Real Convento de Santa Clara es un edificio religioso, catalogado como convento, bajo la advocación de Santa Clara de Asís en la ciudad de Úbeda, en la provincia de Jaén, España, declarado monumento nacional en 1979, y es uno de los monasterios más antiguos de Úbeda, que aún se encuentra habitado por monjas de…',38.0093763,-3.3702379,'https://es.wikipedia.org/wiki/Convento_de_Santa_Clara_(Úbeda)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182836,'41039','Convento de la Santísima Trinidad (las Marroquíes)','religioso','religioso_osm','El convento de la Santísima Trinidad y Purísima Concepción, es un convento católico de la ciudad de Écija en la provincia de Sevilla, regido por las Concepcionistas Franciscanas, es conocido popularmente como las Marroquies está situado a escasos metros de la Iglesia de los Descalzos. Está declarado como BIC el 17…',37.5423782,-5.0821848,'https://es.wikipedia.org/wiki/Convento_de_la_Santísima_Trinidad_y_Purísima_Concepción_(Écija)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182837,'45168','Monasterio de Santo Domingo El Real','religioso','religioso_osm','El monasterio de Santo Domingo el Real, situado en la ciudad de Toledo (España), es un monasterio de monjas dominicas.',39.8607181,-4.0268196,'https://es.wikipedia.org/wiki/Monasterio_de_Santo_Domingo_el_Real_(Toledo)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182838,'40194','Monasterio Jerónimo Santa María del Parral','religioso','religioso_osm','El monasterio de Santa María del Parral, o simplemente monasterio de El Parral, es un monasterio de clausura de la Orden de San Jerónimo ubicado en la ciudad de Segovia, en la comunidad autónoma de Castilla y León en España. El monasterio de El Parral se encuentra a extramuros de la ciudad, en el barrio de San…',40.9557482,-4.1260745,'https://monjesjeronimos.es/','https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_del_Parral');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182839,'51025','Monasterio de San José','religioso','religioso_osm','El convento de San José es un convento de clausura de monjas carmelitas descalzas que se encuentra en la ciudad española de Ávila, en la comunidad autónoma de Castilla y León. Se trata de la primera fundación conventual llevada a cabo por Santa Teresa de Jesús, quien contó con el apoyo de importantes…',40.6553156,-4.6923506,'https://es.wikipedia.org/wiki/Convento_de_San_José_(Ávila)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182840,'51025','Convento de la Encarnación','religioso','religioso_osm','El convento de la Encarnación​ es un convento de clausura de monjas carmelitas que se encuentra en la ciudad española de Ávila, en la comunidad autónoma de Castilla y León. Este convento se tornó conocido porque en él ingresó Santa Teresa de Jesús en 1535, donde fue primero monja y después madre priora, antes de…',40.6629405,-4.6993265,'https://es.wikipedia.org/wiki/Convento_de_la_Encarnación_(Ávila)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182841,'04052','Catedral de la Encarnación','religioso','religioso_osm','La catedral de Nuestra Señora de la Encarnación, en la ciudad española de Almería, es la sede episcopal de la diócesis de Almería. El edificio, con estructura de fortaleza, presenta una arquitectura de transición entre el Gótico tardío y el Renacimiento, así como rasgos posteriores barrocos y neoclásicos.',36.8380555,-2.467446,'https://es.wikipedia.org/wiki/Catedral_de_Almería');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182842,'37011','Catedral Vieja o de Santa María de la Sede','religioso','religioso_osm','La catedral de Santa María de la Sede, conocida como catedral Vieja, es una de las dos catedrales que hay en Salamanca. Fundada por el obispo Jerónimo de Perigord, se empezó a construir en el primer tercio del siglo XII y se terminó a finales del siglo XIV, en estilo románico y gótico.',40.9605036,-5.6666149,'https://es.wikipedia.org/wiki/Catedral_Vieja_de_Salamanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182843,'31232','Iglesia de la Virgen del Rosario y Convento de Las Dominicas','religioso','religioso_osm','El convento de las Dominicas e iglesia de la Virgen del Rosario de Tudela (Navarra, España) es un templo construido en el siglo XVII,​ que se sitúa en la calle del mismo nombre del Casco Antiguo de Tudela.​',42.0632377,-1.6105557,'https://es.wikipedia.org/wiki/Iglesia_y_convento_de_las_Dominicas_(Tudela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182844,'45168','Convento de la Concepción Benedictina y de San Pablo','religioso','religioso_osm','El convento de la Concepción Benedictina, conocido como "de las Benitas", es un edificio de la ciudad española de Toledo, con origen en un beaterio para mujeres fundado en 1487 por Diego Fernández de Úbeda. A partir de un pequeño núcleo inicial, el beaterio fue adquiriendo otros inmuebles adyacentes para levantar…',39.8544427,-4.0219642,'https://es.wikipedia.org/wiki/Convento_de_la_Concepción_Benedictina_y_de_San_Pablo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182845,'28084','Catedral de Nuestra Señora del Pilar de Justo Gallego Martínez','religioso','religioso_osm','La catedral de Justo es un edificio semejante a una catedral cristiana, situado en Mejorada del Campo (Madrid, España). Estaba siendo construido como proyecto de autoconstrucción por Justo Gallego Martínez, hasta su fallecimiento con 96 años; cuando la donó a Mensajeros de la Paz para que la acabara.​ Justo comenzó…',40.3941221,-3.4884796,'https://catedraljustomensajeros.com/','https://es.wikipedia.org/wiki/Catedral_de_Justo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182846,'90603','Monestir de Sant Esteve','religioso','religioso_osm','El Monestir de Sant Esteve de Banyoles és una obra de Banyoles (Pla de l''Estany) declarada bé cultural d''interès nacional. Es pot considerar una de les primeres fundacions monàstiques benedictines a Catalunya i és considerat el bressol de la ciutat de Banyoles.',42.1204328,2.7697053,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Esteve_de_Banyoles');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182847,'49219','Convento de Santa Sofía','religioso','religioso_osm','El monasterio de Santa Sofía, sito en la localidad de Toro (Zamora, Castilla y León, España) es un cenobio habitado desde su creación en el siglo XIV por una comunidad de monjas Canónigas Norbertinas Premonstratenses. Su arquitectura y mobiliario aúnan elementos góticos, morisco-mudéjares y renacentistas.',41.5225833,-5.3992311,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_Sofía_(Toro)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182848,'49127','Ermita del Cristo de Morales','religioso','religioso_osm','La ermita del Cristo es un santuario español situado en el término municipal de Morales del Vino (Zamora, Castilla y León).​​',41.469904,-5.7386677,'https://es.wikipedia.org/wiki/Ermita_del_Cristo_de_Morales');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182849,'34134','Abadía de Lebanza','religioso','religioso_osm','La abadía de Lebanza se encuentra a tres kilómetros de la localidad de Lebanza, en el término municipal de La Pernía, en la Montaña palentina (comunidad autónoma de Castilla y León, España).',42.9625689,-4.5531926,'https://es.wikipedia.org/wiki/Abadía_de_Lebanza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182850,'08140','Monestir de Sant Benet de Bages','religioso','religioso_osm','El Monestir Sant Benet de Bages és un edifici del municipi de Sant Fruitós de Bages (Bages) declarada bé cultural d''interès nacional. És una antiga abadia benedictina del terme municipal de Sant Fruitós de Bages, a la comarca catalana del Bages.',41.7426525,1.8992518,'https://ca.wikipedia.org/wiki/Monestir_de_Sant_Benet_de_Bages');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182851,'36055','Mosteiro de San Domingos','religioso','religioso_osm','El Convento e Iglesia de Santo Domingo de Tuy es un conjunto monástico de la ciudad de Tuy, en la provincia de Pontevedra (Galicia), erigido en el siglo XIV por los frailes dominicos.​',42.0492814,-8.6399783,'https://es.wikipedia.org/wiki/Convento_de_Santo_Domingo_(Tuy)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182852,'90217','Monasterio de San Miguel de las Dueñas','religioso','religioso_osm','El monasterio de San Miguel de las Dueñas es un cenobio femenino de la Congregación de Monasterios de Monjas Cistercienses de San Bernardo situado en la población homónima de la comarca de El Bierzo de la provincia de León (Comunidad de Castilla y León, España).',42.5830776,-6.5231758,'https://cistersanmiguel.net/','https://es.wikipedia.org/wiki/Monasterio_de_San_Miguel_de_las_Dueñas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182853,'40063','Convento de Santa Clara','religioso','religioso_osm','El monasterio de Santa Clara es un complejo monacal de monjas franciscanas de clausura, situado en la villa segoviana de Cuéllar (Castilla y León, España). Se trata de una de las primeras fundaciones clarisas en España,​ pues consta que ya lo estaba en 1244; en el siglo XVI sufrió una importante renovación por una…',41.3942047,-4.306477,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_Clara_(Cuéllar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182854,'42173','Convento del Carmen','religioso','religioso_osm','El convento de Nuestra Señora del Carmen se encuentra en el casco histórico de la ciudad de Soria (España). Es el mejor conjunto de estilo barroco construido en la capital soriana.',41.7645303,-2.4625865,'https://es.wikipedia.org/wiki/Convento_de_Nuestra_Señora_del_Carmen_(Soria)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182855,'15078','Catedral de Santiago de Compostela','religioso','religioso_osm','A catedral de Santiago de Compostela é un templo de culto católico situado na cidade de Santiago de Compostela. Acolle o que, segundo a tradición católica, é o sepulcro do Apóstolo Santiago, o cal converteu o templo nun dos principais destinos de peregrinación de Europa durante a Idade Media a través do chamado…',42.8803762,-8.5445752,'https://gl.wikipedia.org/wiki/Catedral_de_Santiago_de_Compostela');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182856,'18087','Monasterio de La Cartuja','religioso','religioso_osm','El Real Monasterio de Nuestra Señora de la Asunción de la Cartuja, situado en la ciudad española de Granada, comunidad autónoma de Andalucía, albergó a una comunidad de monjes cartujos desde su fundación en el siglo XVI hasta la exclaustración del año 1835. Aunque mezcla diversos estilos, representa una de las…',37.1919846,-3.5994314,'https://es.wikipedia.org/wiki/Cartuja_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182857,'40194','Convento de San José','religioso','religioso_osm','El convento de San José es un convento de clausura de monjas Carmelitas Descalzas que se encuentra en la ciudad española de Segovia.',40.9515153,-4.126736,'https://es.wikipedia.org/wiki/Convento_de_San_José_(Segovia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182858,'40194','Convento de Santo Domingo el Real','religioso','religioso_osm','El convento de Santo Domingo el Real es un monasterio de clausura situado en la ciudad española de Segovia. En el monasterio se enclava la torre de Hércules, bien de interés cultural desde el 3 de junio de 1931.',40.9514213,-4.1228993,'https://es.wikipedia.org/wiki/Convento_de_Santo_Domingo_el_Real_(Segovia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182859,'40194','Convento del Corpus Christi (Antigua Sinagoga Mayor)','religioso','religioso_osm','La Antigua Sinagoga Mayor de Segovia fue un edificio religioso de Segovia, España. La construcción de la antigua sinagoga principal tuvo lugar a mediados del siglo XIV. A partir del siglo XV, fue confiscado por las autoridades y convertido en un convento de monjas de la orden de Santa Clara en 1419.',40.9492439,-4.1240146,'https://es.wikipedia.org/wiki/Convento_del_Corpus_Christi_(Segovia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182860,'41091','Catedral de Sevilla','religioso','religioso_osm','La Santa, Metropolitana y Patriarcal Iglesia Catedral de Santa María de la Sede y de la Asunción de Sevilla; más conocida como catedral de Sevilla, es una iglesia catedral de culto cristiano católico, sede de la archidiócesis de Sevilla. Su estructura es de arquitectura gótica, con añadidos renacentistas.',37.3859155,-5.9931531,'https://www.catedraldesevilla.es','https://es.wikipedia.org/wiki/Catedral_de_Sevilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182861,'50067','Colegiata de Santa María','religioso','religioso_osm','La colegiata de Santa María la Mayor o Colegiata de la Asunción de la Virgen de Calatayud es un templo parroquial católico que fue edificado en Calatayud (Zaragoza) sobre una antigua mezquita a partir del año 1120. Al estar situada en mitad de la villa medieval, se la llamó Santa María de Mediavilla.',41.3541678,-1.645272,'https://es.wikipedia.org/wiki/Colegiata_de_Santa_María_(Calatayud)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182862,'17188','Monestir de Sant Pere de Rodes','religioso','religioso_osm','El monestir de Sant Pere de Rodes (o de Roda) fou un monestir benedictí de l''antic comtat d''Empúries, dins els límits del bisbat de Girona, situat a l''actual terme municipal del Port de la Selva (Alt Empordà). En concret, es troba al sud-oest de la població del Port de la Selva, al vessant de llevant de la muntanya…',42.3233443,3.1664303,'https://ca.wikipedia.org/wiki/Sant_Pere_de_Rodes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182863,'36041','Mosteiro de San Xoán de Poio','religioso','religioso_osm','San Xoán de Poio é un mosteiro medieval beneditino situado na parroquia de San Xoán de Poio, ocupado por unha comunidade de mercedarios.',42.4464474,-8.6851043,'https://gl.wikipedia.org/wiki/Convento_de_San_Xoán_de_Poio');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182864,'17098','Mare de Déu del Mont','religioso','religioso_osm','La Mare de Déu del Mont és un santuari marià del bisbat de Girona, sobre el pic culminant de la serra del Mont (també coneguda com el Mont o, popularment, la Mare de Déu del Mont), a l''antic terme de Sous, a l''extrem meridional de l''antic municipi de Bassegoda, actualment agregat al d''Albanyà (Alt Empordà). La seva…',42.2585208,2.7068612,'https://ca.wikipedia.org/wiki/Mare_de_Déu_del_Mont');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182865,'50251','Catedral Santa Maria de la Huerta','religioso','religioso_osm','La Seo de Nuestra Señora de la Huerta de Tarazona,​​ también denominada catedral de Tarazona, se encuentra en la ciudad de Tarazona (Aragón, España) y es el templo cabeza de la diócesis homónima. Iniciada su construcción en el siglo XII con planta gótica clásica, fue reformulada en el siglo XVI en estilo renacentista.',41.9026169,-1.7248718,'https://www.catedraldetarazona.es/','https://es.wikipedia.org/wiki/Catedral_de_Tarazona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182866,'28075','Monasterio de la Inmaculada Concepción','religioso','religioso_osm','El monasterio de la Inmaculada Concepción es un monasterio de monjas dominicas ubicado en la localidad española de Loeches, frente a la plaza de la duquesa de Alba. Es conocido también como «el convento grande».',40.3861576,-3.4122099,'https://es.wikipedia.org/wiki/Monasterio_de_la_Inmaculada_Concepción_(Loeches)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182867,'37011','Catedral Nueva de la Asunción de María','religioso','religioso_osm','La catedral de la Asunción de la Virgen, llamada popularmente catedral Nueva, es, junto con la Vieja, una de las dos catedrales de la ciudad de Salamanca, en España. Como tal, es la sede de la diócesis de Salamanca.',40.9606168,-5.6660423,'https://catedralsalamanca.org/','https://es.wikipedia.org/wiki/Catedral_Nueva_de_Salamanca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182868,'40194','Monasterio de Santa María y San Vicente el Real','religioso','religioso_osm','El Monasterio de Santa María y San Vicente el Real es un monasterio de clausura de las monjas de la Orden del Císter que está situado en el barrio de San Lorenzo, extramuros de la ciudad de Segovia, en la comunidad autónoma de Castilla y León, en España, a orillas del río Eresma, en un paisaje de gran belleza, en…',40.9571342,-4.1161826,'https://es.wikipedia.org/wiki/Monasterio_de_San_Vicente_el_Real');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182869,'40194','Monasterio de los Carmelitas Descalzos','religioso','religioso_osm','El convento de San Juan de la Cruz​ es un convento de la ciudad española de Segovia.',40.9556263,-4.1332816,'https://sanjuandelacruzsegovia.com/','https://es.wikipedia.org/wiki/Convento_de_San_Juan_de_la_Cruz_(Segovia)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182870,'32061','Mosteiro de Oseira','religioso','religioso_osm','O mosteiro de Santa María de Oseira é un mosteiro medieval da parroquia de Oseira, no concello de San Cristovo de Cea. De fundación bieita, no século XII incorporouse ao Císter, e ao longo da súa historia tivo unha grande importancia económica e social para a comarca e terras máis afastadas.',42.5383682,-7.9510671,'https://gl.wikipedia.org/wiki/Mosteiro_de_Santa_María_de_Oseira');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182871,'45003','Iglesia del Sagrado Corazón de Jesús','religioso','religioso_osm','L''església parroquial del Sagrat Cor és un temple catòlic situat al carrer Teodor Llorente, 9, al municipi de Burjassot. És un Bé de Rellevància Local amb identificador nombre 46.13.078-006.',39.5089859,-0.4163351,'https://ca.wikipedia.org/wiki/Església_del_Sagrat_Cor_de_Burjassot');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182872,'31233','Monasterio Cisterciense Santa Maria de la Caridad','religioso','religioso_osm','El Real Monasterio de Santa María de la Caridad de Tulebras (Navarra, España), o simplemente, el monasterio de Tulebras, es un cenobio de monjas trapenses que acoge vida religiosa ininterrumpidamente desde su fundación hacia 1147.​ Artísticamente destaca por los elementos de estilo románico-cisterciense en su…',41.9767529,-1.6758977,'https://www.monasteriodetulebras.com/vista/index.html','https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_de_la_Caridad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182873,'46169','Parroquia De Nuestra Señora De La Misericordia','religioso','religioso_osm','L''església de Nostra Senyora de la Misericòrdia s''ubica al barri de Campanar (València), antic poble ara integrat i absorbit per la ciutat de València el 1897. Exactament està a la plaça de l''Església de Campanar, plaça configurada per habitatges construïts quan encara era independent, amb una tipologia i alçada…',39.4820401,-0.3974239,'https://www.parroquiadecampanar.es/','https://ca.wikipedia.org/wiki/Església_de_la_Nostra_Senyora_de_la_Misericòrdia_(Campanar)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182874,'90001','Mosteiro de Santa Catalina de Montefaro','religioso','religioso_osm','O mosteiro de Santa Catarina de Montefaro é unha construción relixiosa situada na parroquia de Cervás do concello de Ares, fundada no século XIV polo conde Fernán Pérez de Andrade. Foi declarado Ben de Interese Cultural no ano 2000.',43.4506824,-8.2819062,'https://gl.wikipedia.org/wiki/Mosteiro_de_Santa_Catarina_de_Montefaro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182875,'43056','Mare de Déu de la Misericòrdia','religioso','religioso_osm','L''ermita de la Misericòrdia és un edifici del municipi de la Fatarella inclòs en l''Inventari del Patrimoni Arquitectònic de Catalunya.',41.1604394,0.4736317,'https://ca.wikipedia.org/wiki/Ermita_de_la_Misericòrdia_(la_Fatarella)');
