INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182877,'30030','Convento Iglesia de las Agustinas del Corpus Christi','religioso','religioso_osm','El convento de las Agustinas del Corpus Christi; o como popularmente se le conoce, las Agustinas, es un conjunto monástico perteneciente a la rama femenina de la Orden de San Agustín, situado en la ciudad de Murcia (Región de Murcia, España), concretamente en la plaza de las Agustinas, en lo que antiguamente era…',37.9877353,-1.1380854,'https://es.wikipedia.org/wiki/Convento_de_las_Agustinas_del_Corpus_Christi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182878,'27030','Catedral de Mondoñedo','religioso','religioso_osm','Non confundir coa Basílica de San Martiño de Mondoñedo. A catedral de Mondoñedo é un templo católico da vila de Mondoñedo, unha das sés episcopais da diocese de Mondoñedo-Ferrol xunto coa Concatedral de Ferrol.',43.4280722,-7.3627237,'https://gl.wikipedia.org/wiki/Catedral_de_Mondoñedo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182879,'24148','Catedral de Astorga','religioso','religioso_osm','La catedral de Santa María, es la sede episcopal de la diócesis de Astorga, documentada desde el siglo XIII con el título de Apostólica. Se encuentra en la ciudad de Astorga, provincia de León (España).',42.4580478,-6.0570959,'https://es.wikipedia.org/wiki/Catedral_de_Astorga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182880,'08003','Basílica dels Sants Màrtirs Just i Pastor','religioso','religioso_osm','L''església dels Sants Just i Pastor és un temple gòtic situat a la plaça de Sant Just de Barcelona, declarat bé cultural d''interès nacional en la categoria de monument històric el juny del 2012 pels seus valors històrics singulars i excepcionals.',41.3826836,2.1780468,'https://www.basilicasantjust.cat/','https://ca.wikipedia.org/wiki/Església_dels_Sants_Just_i_Pastor');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182881,'08003','Basílica de la Sagrada Família','religioso','religioso_osm','El Temple Expiatori de la Sagrada Família, o simplement Sagrada Família, és una església catòlica en construcció situada al barri del mateix nom de Barcelona, declarada basílica menor pel papa Benet XVI en la seva visita a la ciutat el 7 de novembre del 2010. És el monument més visitat de l''estat espanyol, per…',41.4035047,2.1742801,'https://sagradafamilia.org/','https://ca.wikipedia.org/wiki/Temple_Expiatori_de_la_Sagrada_Família');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182882,'39018','Santuario de Nuestra Señora de Las Caldas','religioso','religioso_osm','El santuario de Nuestra Señora de Las Caldas está situado en la localidad de Las Caldas de Besaya, término municipal de Los Corrales de Buelna (Cantabria, España), y es un conjunto arquitectónico que se compone de iglesia, claustro y dos cuerpos en sus lados este y sur destinados a usos de celdas, ofertorio,…',43.2988335,-4.0758734,'https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Señora_de_Las_Caldas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182883,'90211','Monasterio de Santa María de Carracedo','religioso','religioso_osm','O mosteiro de Santa María de Carracedo é unha antiga abadía, xa exclaustrada, fundada no século X e pertencente ás ordes beneditina e, posteriormente, cisterciense. Sitúase en Carracedo do Mosteiro, no concello de Carracedelo, na comarca do Bierzo, na provincia de León, a carón do Camiño de Santiago.',42.5708084,-6.7314995,'https://gl.wikipedia.org/wiki/Mosteiro_de_Santa_María_de_Carracedo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182884,'06006','Catedral de San Juan Bautista','religioso','religioso_osm','La Santa Iglesia Catedral Metropolitana de Badajoz o catedral de San Juan Bautista, que posee rango metropolitano, está situada en la plaza de España, en el centro de la ciudad de Badajoz (España), siendo la sede arzobispal.',38.8783653,-6.9695095,'https://es.wikipedia.org/wiki/Catedral_de_San_Juan_Bautista_de_Badajoz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182885,'04052','Parroquia Virgen del Mar','religioso','religioso_osm','El santuario de la Virgen del Mar, patrona de Almería, o iglesia de Santo Domingo de Guzmán es un templo de la ciudad española de Almería, Andalucía, originalmente concebido como iglesia conventual de la comunidad religiosa de Santo Domingo de Guzmán, los padres dominicos, que residen en el convento anexo.',36.8373007,-2.4646721,'https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_del_Mar_(Almería)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182886,'39075','Catedral de Nuestra Señora de la Asunción','religioso','religioso_osm','La catedral de la Asunción de Nuestra Señora se encuentra en la ciudad española de Santander. Su estructura es principalmente gótica, si bien ha sido posteriormente ampliada y reformada.',43.4606641,-3.8072744,'https://es.wikipedia.org/wiki/Catedral_de_Santander');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182887,'30015','Santuario de la Vera Cruz','religioso','religioso_osm','La Real Basílica-Santuario de la Vera Cruz​ es una basílica católica situada en la ciudad de Caravaca de la Cruz (Región de Murcia, España).',38.1078568,-1.858501,'https://es.wikipedia.org/wiki/Basílica_de_la_Vera_Cruz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182888,'23092','Basílica menor de Santa María de los Reales Alcázares','religioso','religioso_osm','La Basílica y Real Colegiata de Santa María la Mayor de los Reales Alcázares de Úbeda, declarada Monumento Nacional y parte de conjunto Patrimonio de la Humanidad, es la iglesia principal de la ciudad de Úbeda, Jaén y tercera de la diócesis jiennense.',38.0070594,-3.3684269,'https://es.wikipedia.org/wiki/Basílica_de_Santa_María_de_los_Reales_Alcázares');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182889,'08003','Mare de Déu de Betlem','religioso','religioso_osm','L''església de Betlem és un temple de culte catòlic situat al carrer del Carme, 2 cantonada amb la Rambla, 107 de Barcelona, declarat bé cultural d''interès nacional, amb un entorn de protecció comú amb el Palau Moja, situat just al davant.',41.3830973,2.1712258,'https://ca.wikipedia.org/wiki/Església_de_Betlem');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182890,'31232','Convento de las Madres Clarisas','religioso','religioso_osm','El convento e iglesia de Santa Clara de Tudela (Navarra) es un convento perteneciente a la orden de las clarisas, situado entre las calles Blanca de Navarra, Sancho Abarca y Monasterio de la Oliva,​ cerca de la Plaza de Toros de Tudela. Fue construido a mediados del siglo XX, tras la vuelta de las clarisas a la…',42.0540505,-1.5951508,'https://es.wikipedia.org/wiki/Convento_de_Santa_Clara_(Tudela)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182891,'27027','Mosteiro de San Salvador de Lourenzá','religioso','religioso_osm','O mosteiro de San Salvador de Lourenzá é un mosteiro de orixe medieval situado en Lourenzá, no val do río Masma, a poucos quilómetros de Mondoñedo. Considérase fundador do mosteiro o conde Osorio Gutiérrez, que o ampliou, protexeu e actuou como mecenas, sobre un pequeno cenobio apenas sen vida.',43.4710226,-7.297873,'https://gl.wikipedia.org/wiki/Mosteiro_de_San_Salvador_de_Lourenzá');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182892,'01001','Convento de Santa Bárbara','religioso','religioso_osm','O convento de Santa Bárbara é un convento de clausura situado na praza homónima da Cidade Vella da Coruña.',43.3708626,-8.3912456,'https://gl.wikipedia.org/wiki/Convento_de_Santa_Bárbara_da_Coruña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182893,'43155','Catedral de Tortosa','religioso','religioso_osm','La catedral de Tortosa és un edifici religiós de Tortosa que està sota l''advocació de Santa Maria, i se situa en el nucli antic, a tocar del riu Ebre. L''actual edifici gòtic de l''any 1347 i va ser edificat sobre un anterior romànic; és consagrat per primera vegada el 1441 i les fases de construcció continuaren fins…',40.8141305,0.5223848,'https://ca.wikipedia.org/wiki/Catedral_de_Tortosa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182894,'17087','Santuari de la Mare de Déu dels Àngels','religioso','religioso_osm','El Santuari dels Àngels és un dels santuaris més visitats i de més devoció de les terres gironines, i s''hi venera la Mare de Déu dels Àngels. És al cim del Puig Alt al Massís de les Gavarres, al terme municipal de Sant Martí Vell (Gironès).',41.9846871,2.9089104,'https://ca.wikipedia.org/wiki/Santuari_dels_Àngels');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182895,'46250','Reial Monestir de la Santíssima Trinitat','religioso','religioso_osm','El Monestir de la Trinitat o també el Reial Monestir de la Santíssima Trinitat està situat a la vora del riu Túria al seu pas per la ciutat de València, l''Horta, al País Valencià. És el conjunt conventual més antic de la ciutat que resta habitat, i té gran importància històrica i artística, tant per l''art moble que…',39.4803602,-0.3720794,'https://ca.wikipedia.org/wiki/Monestir_de_la_Trinitat');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182896,'09391','Monasterio de Santa María la Real','religioso','religioso_osm','El monasterio de Santa María la Real se encuentra en la localidad de Tórtoles de Esgueva, actual provincia de Burgos, España. Se localiza muy cerca del monasterio de San Pelayo de Cerrato (Palencia), a unos 30 km al norte de Peñafiel y pertenecía a la diócesis de Burgos.',41.8195269,-4.0219277,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_María_la_Real_(Tórtoles_de_Esgueva)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182897,'27030','Mosteiro dos Picos','religioso','religioso_osm','O mosteiro dos Picos ou mosteiro de San Martiño de Vilalourente é un antigo mosteiro medieval situado nos arredores da vila de Mondoñedo, na parroquia dos Remedios do concello de Mondoñedo.',43.4341677,-7.3800094,'https://gl.wikipedia.org/wiki/Mosteiro_dos_Picos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182898,'09003','Catedral de Santa María','religioso','religioso_osm','La Catedral Basílica Metropolitana de Santa María es un templo catedralicio de culto católico dedicado a la Virgen María, en la ciudad española de Burgos. Pertenece a la archidiócesis de Burgos.',42.3407336,-3.7043491,'https://www.catedraldeburgos.es/','https://es.wikipedia.org/wiki/Catedral_de_Burgos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182899,'14021','Mezquita-Catedral de Córdoba','religioso','religioso_osm','La mezquita-catedral de Córdoba,​​​ conocida eclesiásticamente como catedral de Nuestra Señora de la Asunción​ y de forma popular como la Mezquita, es la catedral de la diócesis de Córdoba ubicada en la ciudad española de Córdoba, Andalucía.​ Según las fuentes islámicas, antes de la conquista musulmana de la…',37.8790246,-4.7795353,'https://mezquita-catedraldecordoba.es','https://es.wikipedia.org/wiki/Mezquita-catedral_de_Córdoba');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182900,'29094','Convento de Jesús, María y José','religioso','religioso_osm','El monasterio de las Carmelitas Descalzas, también llamado convento de Jesús, María y José, situado en la plaza de las Carmelitas de Vélez-Málaga, uno de los núcleos urbanos de la provincia de Málaga (España) con mayor concentración de establecimientos religiosos, supone, por su existencia y tipología, un claro…',36.7810285,-4.1046669,'https://es.wikipedia.org/wiki/Monasterio_de_las_Carmelitas_Descalzas_(Vélez-Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182901,'29094','Real Monasterio de Nuestra Señora de Gracia','religioso','religioso_osm','El Real Monasterio de Nuestra Señora de Gracia, más conocido como convento de las Claras,​ es uno de los conventos que mejor representa la tradición conventual de la ciudad malagueña de Vélez-Málaga (España) durante los siglos XVI y XVII. Fundado en 1503 por Beatriz de Arellano, bajo la advocación de la Purísima…',36.7839734,-4.1049441,'https://es.wikipedia.org/wiki/Real_Monasterio_de_Nuestra_Señora_de_Gracia_(Vélez-Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182902,'90240','Monasterio nuestra señora de Alconada','religioso','religioso_osm','El monasterio (1) y santuario (2) de Nuestra Señora de Alconada (o Arconada) es la denominación del actual monasterio cisterciense, secular santuario mariano, que desde 1985 viene siendo regentado y custodiado por las madres de la Congregación de san Bernardo o de Castilla del císter. Situado en Ampudia, en la…',41.9215377,-4.7470432,'https://es.wikipedia.org/wiki/Monasterio_de_Nuestra_Señora_de_Alconada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182903,'21050','Monasterio de Santa Clara','religioso','religioso_osm','El monasterio de Santa Clara se encuentra en Moguer, provincia de Huelva (España).​​ Está incluido como bien de interés cultural de los Lugares Colombinos.​​ Es el monumento colombino más destacado de Moguer. Su abadesa Inés Enríquez, tía del rey Fernando el Católico, apoyó el viaje descubridor en la corte.',37.2759475,-6.8394342,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_Clara_(Moguer)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182904,'22006','Convento Mercedario','religioso','religioso_osm','El convento Mercedario tiene sita en la calle de Jovellanos, en pleno barrio de La Ribera de la localidad de Ayamonte (provincia de Huelva, Andalucía, España), junto a su templo, la Iglesia de la Merced que data de mediados del siglo XVII.',37.2136496,-7.4067523,'https://es.wikipedia.org/wiki/Convento_Mercedario_(Ayamonte)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182905,'21074','Convento de San Juan Bautista','religioso','religioso_osm','El convento de San Juan Bautista o Convento de las Madres Carmelitas está situado en la calle de Francisco Alcalá, número 40, en la localidad onubense de Villalba del Alcor. Fue fundado por García Jiménez Franco en 1618 y dedicado a la Virgen del Carmen.',37.3973937,-6.4748881,'https://es.wikipedia.org/wiki/Convento_de_San_Juan_Bautista_(Villalba_del_Alcor)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182906,'90597','Mare de Déu de la Pietat','religioso','religioso_osm','La Mare de Déu de la Pietat del Pedreguet és una església d''Amer (Selva) protegida com a Bé Cultural d''Interès Local.',42.0060406,2.6047654,'https://ca.wikipedia.org/wiki/Mare_de_Déu_de_la_Pietat_del_Pedreguet');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182907,'03027','Catedral de Orihuela','religioso','religioso_osm','La Santa Iglesia Catedral del Salvador y Santa María de Orihuela, o simplemente catedral de Orihuela, es la sede de la diócesis de Orihuela-Alicante,​ Su construcción se inició a finales del siglo XIII sobre restos visigodos e hispano-árabes. En 1281, Alfonso X el Sabio estableció que la iglesia del Salvador y…',38.0858661,-0.9460463,'https://es.wikipedia.org/wiki/Catedral_de_Orihuela');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182908,'37003','Monasterio de la Caridad','religioso','religioso_osm','El monasterio de la Caridad es un edificio del municipio español de Ciudad Rodrigo, en la provincia de Salamanca.',40.5736457,-6.4942924,'https://es.wikipedia.org/wiki/Monasterio_de_la_Caridad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182909,'21025','Ermita de Nuestra Señora de la Concepción','religioso','religioso_osm','La mezquita de Almonaster la Real es un oratorio islámico situado en dicho municipio español de la provincia de Huelva, en Andalucía. Fue construida durante el Califato de Córdoba, entre los IX y X, en el interior del castillo de Almonaster, sobre los restos de una basílica visigótica del siglo VI, cuyos materiales…',37.87041,-6.7870866,'https://es.wikipedia.org/wiki/Mezquita_de_Almonaster_la_Real');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182910,'35017','Nuestra Señora del Rosario','religioso','religioso_osm','La Parroquia Matriz de Nuestra Señora del Rosario es la parroquia matriz de la localidad de Puerto del Rosario, capital de la isla de Fuerteventura, Islas Canarias, España.',28.4990808,-13.8607787,'https://es.wikipedia.org/wiki/Iglesia_Matriz_de_Nuestra_Señora_del_Rosario_(Puerto_del_Rosario)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182911,'40194','Catedral de Segovia','religioso','religioso_osm','La Santa Iglesia Catedral de Nuestra Señora de la Asunción y de San Frutos de Segovia, conocida como la Dama de las Catedrales por sus dimensiones y su elegancia,[cita requerida] es una catedral construida entre los siglos XVI y XVIII, de estilo gótico con algunos rasgos renacentistas. La catedral de Segovia es una…',40.9501149,-4.1256062,'https://catedralsegovia.es','https://es.wikipedia.org/wiki/Catedral_de_Segovia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182912,'22129','Catedral de San Vicente Mártir','religioso','religioso_osm','La Catedral de Sant Vicent màrtir de Roda d''Isàvena a la comarca de la Ribagorça és una catedral romànica que fou seu del bisbat de Roda-Barbastre entre el 887 i el 1149, quan va ser traslladada al bisbat de Lleida. Roda és la localitat espanyola més petita amb una seu catedralícia, si bé deixà de ser seu episcopal…',42.2915997,0.5281788,'https://ca.wikipedia.org/wiki/Catedral_de_Roda_d''Isàvena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182913,'36011','Convento de San Francisco','religioso','religioso_osm','O convento de San Francisco é un convento franciscano de Pontevedra, situado no centro da vila. Na actualidade está ocupado por catro frades.',42.431284,-8.6429262,'https://gl.wikipedia.org/wiki/Convento_de_San_Francisco_de_Pontevedra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182914,'36055','Catedral de Santa María de Tui','religioso','religioso_osm','A catedral de Santa María de Tui é un templo católico situado na cidade de Tui, próxima á beira do río Miño. É sé da diocese de Tui-Vigo, convertida en sé episcopal durante o reino suevo.',42.0459285,-8.6444218,'https://www.catedraldetui.com','https://gl.wikipedia.org/wiki/Catedral_de_Tui');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182915,'40194','Monasterio de la Humilde Encarnación','religioso','religioso_osm','El monasterio de la Humilde Encarnación​ es un monasterio de clausura de las Madres Agustinas que se encuentra en la ciudad de Segovia, en la comunidad autónoma de Castilla y León, en España. Fundado en el siglo XVI, es conocido también como Monasterio de Santa Rita.',40.9442528,-4.1111524,'https://declausura.org/monasterio/monasterio-de-la-encarnacion-segovia-segovia','https://es.wikipedia.org/wiki/Monasterio_de_la_Humilde_Encarnación');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182916,'14021','Basílica de San Pedro','religioso','religioso_osm','La basílica menor de San Pedro es una de las denominadas iglesias fernandinas situada en Córdoba (España), en la plaza de San Pedro del barrio homónimo a los cuales da nombre. Aunque fue construida en estilo gótico tras la conquista de Córdoba por Fernando III el Santo, sufrió grandes intervenciones renacentistas y…',37.882626,-4.7718323,'https://es.wikipedia.org/wiki/Basílica_de_San_Pedro_(Córdoba)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182917,'25156','Monestir de Santa Maria de Bellpuig de les Avellanes','religioso','religioso_osm','Santa Maria de Bellpuig de les Avellanes o simplement les Avellanes és una antiga abadia de canonges regida per l''orde de Sant Agustí. És al terme municipal d''Os de Balaguer, a la comarca de la Noguera.',41.8750937,0.7575992,'https://www.monestirdelesavellanes.com','https://ca.wikipedia.org/wiki/Monestir_de_Santa_Maria_de_Bellpuig_de_les_Avellanes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182918,'43148','Catedral de Tarragona','religioso','religioso_osm','La Catedral de Tarragona és una catedral catòlica d''estil gòtic a Tarragona, seu de l''Arquebisbat de Tarragona. El títol formal de la Catedral de Tarragona és el de Santa Església Catedral Basílica Metropolitana i Primada de les Espanyes, i està dedicada a Santa Tecla.',41.1193471,1.2581363,'https://ca.wikipedia.org/wiki/Catedral_de_Tarragona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182919,'15078','Convento de San Francisco do Val de Deus','religioso','religioso_osm','San Francisco de Val de Deus é un convento franciscano fundado a comezos do século XIII en Santiago de Compostela, declarado monumento histórico artístico. Está situado no casco vello da cidade, no lugar coñecido como o Val de Deus.',42.8838341,-8.5454264,'https://gl.wikipedia.org/wiki/Convento_de_San_Francisco_do_Val_de_Deus');
