INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182944,'49275','Convento de San Francisco','religioso','religioso_osm','El convento de San Francisco Extraponte fue una institución franciscana construida en el siglo XIV en Zamora.​ Es conocido por haber sido el lugar de reposo del polígrafo Juan Gil de Zamora, estrecho colaborador de Alfonso X el Sabio y preceptor de su hijo, Sancho IV de Castilla. La denominación "extraponte"…',41.497316,-5.7495567,'https://es.wikipedia.org/wiki/Convento_de_San_Francisco_Extraponte');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182945,'09048','Convento de Nuestra Señora de la Bretonera','religioso','religioso_osm','El monasterio de Santa Clara de Belorado (provincia de Burgos, comunidad autónoma de Castilla y León, España) es un cenobio de monjas Clarisas. Debido a que fue construido en un lugar conocido como Bretonera, también se le conoce como Monasterio de Nuestra Señora de Bretonera.',42.419473,-3.1989155,'https://es.wikipedia.org/wiki/Monasterio_de_Santa_Clara_(Belorado)');
