INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182949,'09311','Monasterio de San Pedro de Arlanza','religioso','religioso_osm','El monasterio de San Pedro de Arlanza, situado en la localidad burgalesa de Hortigüela (Castilla y León, España) a orillas del río que le da nombre, fue uno de los centros monásticos más importantes del condado y luego reino de Castilla. Aunque los restos más antiguos existentes hoy en el conjunto monacal,…',42.0485332,-3.4668701,'https://es.wikipedia.org/wiki/Monasterio_de_San_Pedro_de_Arlanza');
