INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182952,'46098','Monestir de Santa María de la Murta','religioso','religioso_osm','El monasterio de Santa María de la Murta (siglos XIV - XV), es un antiguo cenobio de la orden de los jerónimos situado en el Valle de La Murta, en Alcira (Valencia) España. A lo largo de su historia fue un importante emporio de cultura y espiritualidad y centro de peregrinaje de la realeza, la aristocracia y de…',39.128878,-0.3610642,'https://es.wikipedia.org/wiki/Monasterio_de_La_Murta');
