INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(182954,'47165','Real Monasterio de Santa Clara','religioso','religioso_osm','El Real Monasterio de Santa Clara se encuentra situado en la vallisoletana villa de Tordesillas (Castilla y León, España) sobre la cornisa del río Duero, protegido por las antiguas murallas de la ciudad. Se trata de un complejo de dependencias en las que se agrupan en el monasterio de monjas clarisas, más las…',41.5000078,-4.9972616,'https://www.patrimonionacional.es/visita/real-monasterio-de-santa-clara-de-tordesillas','https://es.wikipedia.org/wiki/Monasterio_de_Santa_Clara_(Tordesillas)');
