INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182972,'27041','Igrexa de San Miguel de Eiré','religioso','religioso_osm','A Igrexa de San Miguel de Eiré, tamén chamado Mosteiro de Eiré, é unha igrexa románica de orixe monástica e un dos mellores exemplos conservados en Galicia de arquitectura románica. Está situada no lugar do Mosteiro na parroquia de Eiré, no concello lucense de Pantón.',42.5182583,-7.6478484,'https://gl.wikipedia.org/wiki/Igrexa_de_San_Miguel_de_Eiré');
