INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182982,'39075','Convento de las Madres Clarisas de Santa Cruz','religioso','religioso_osm','El convento de las Madres Clarisas de Santa Cruz es un edificio declarado Bien de Interés Cultural de la ciudad de Santander, Cantabria (España). El convento fue habitado desde sus inicios por monjas clarisas coletinas, hasta que a mediados del siglo XIX fue transformado en fábrica de tabaco.',43.4604584,-3.8133468,'https://es.wikipedia.org/wiki/Convento_de_Santa_Cruz_de_Santander');
