INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(182999,'03002','Monasterio del Santo Sepulcro','religioso','religioso_osm','El monasterio del Santo Sepulcro de Alcoy (Alicante), Comunidad Valenciana, es la única muestra de arquitectura religiosa antigua que se conserva en Alcoy, ya que todas las otras han desaparecido. Se trata de un templo barroco construido entre 1596 y 1598 por los maestros de obras Baltasar García, Honorato de…',38.6988952,-0.4738094,'https://es.wikipedia.org/wiki/Monasterio_del_Santo_Sepulcro_(Alcoy)');
