INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(183002,'47218','Cartuja de Aniago','religioso','religioso_osm','La cartuja de Nuestra Señora de Aniago fue un monasterio católico español fundado por los monjes cartujos en 1441 bajo la tutela y patrocinio de la reina María de Aragón, esposa de Juan II. Se construyó en un lugar llamado Aniago, en la provincia de Valladolid. A principios del siglo XIV era un pueblecito con un…',41.5351487,-4.8558573,'https://es.wikipedia.org/wiki/Cartuja_de_Nuestra_Señora_de_Aniago');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(183003,'47186','Monasterio de las Huelgas Reales','religioso','religioso_osm','El monasterio de las Huelgas Reales o de Santa María la Real de las Huelgas es un monasterio femenino de la Orden del Císter situado en Valladolid (España). Su fundación hacia 1300 corresponde a una época en la que se comenzaba a levantar la segunda muralla de la ciudad, hecho indicativo de una situación social…',41.6536635,-4.7164244,'https://es.wikipedia.org/wiki/Monasterio_de_las_Huelgas_Reales_(Valladolid)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(183004,'47114','Convento de San Pablo','religioso','religioso_osm','El convento de San Pablo es un templo cristiano católico levantado sobre los restos históricos del Alcázar de Alfonso X en la localidad de Peñafiel, en la provincia de Valladolid, comunidad autónoma de Castilla y León, España. Data del siglo XIII. En el siglo XIV se convirtió en monasterio.',41.594143,-4.1203762,'https://es.wikipedia.org/wiki/Convento_de_San_Pablo_(Peñafiel)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(183005,'42173','Convento de Nuestra Señora de la Merced','religioso','religioso_osm','El convento de Nuestra Señora de la Merced es la actual sede de la Fundación Duques de Soria que se encuentra en la ciudad de Soria (España). En origen la iglesia del convento se consagró con el nombre de San Martín de Canales pero su advocación cambió cuando fue ocupada por los frailes mercedarios.',41.7665957,-2.4647787,'https://es.wikipedia.org/wiki/Convento_de_Nuestra_Señora_de_la_Merced_(Soria)');
