INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(183011,'47186','Convento de las Descalzas Reales','religioso','religioso_osm','El convento de las Descalzas Reales de Valladolid estuvo en su origen consagrado y dedicado a Nuestra Señora de la Piedad; tras una orden del rey Felipe III se cambió la advocación por la de Nuestra Señora de la Asunción. Su fundación data de 1550 y su estancia en Valladolid de 1552.',41.6560762,-4.7210154,'https://es.wikipedia.org/wiki/Convento_de_las_Descalzas_Reales_(Valladolid)');
