INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(183015,'28131','Real Monasterio de San Lorenzo de El Escorial','religioso','religioso_osm','El Real Monasterio de San Lorenzo de El Escorial es un complejo que incluye un palacio real, una basílica, un panteón, una biblioteca, un colegio y un monasterio. Se encuentra en la localidad española de San Lorenzo de El Escorial, en la Comunidad de Madrid, y fue construido en el siglo XVI entre 1563 y 1584.',40.5890625,-4.1477722,'https://www.patrimonionacional.es/','https://es.wikipedia.org/wiki/Real_Monasterio_de_San_Lorenzo_de_El_Escorial');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace,wiki_url) VALUES(183016,'15080','Mosteiro de Santa María de Sobrado dos Monxes','religioso','religioso_osm','O mosteiro de Santa María de Sobrado dos Monxes é un mosteiro cisterciense situado no concello de Sobrado, na comarca da Terra de Melide. Dende mediados do século XX está ocupado por monxes trapistas.',43.0385005,-8.0225849,'https://www.monasteriodesobrado.org/','https://gl.wikipedia.org/wiki/Mosteiro_de_Santa_María_de_Sobrado_dos_Monxes');
